import { useEffect, useRef, type MouseEvent, type RefObject, type SyntheticEvent } from "react";

/**
 * Lifecycle for the shared `Lightbox`: native `<dialog>` open/close, focus capture and return,
 * arrow-key navigation, Escape and backdrop dismissal. Absorbs the open/close and focus logic the
 * media lightboxes and `ImagePreviewModal` each carried, so every caller gets the same behavior.
 */

/** Idempotent native open. `showModal()` throws on an already-open dialog in real browsers; the
 *  attribute fallback covers DOM environments without it (jsdom). */
export function openLightboxDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.showModal === "function") {
    if (!dialog.open) dialog.showModal();
    return;
  }
  dialog.setAttribute("open", "");
}

/** The close-side mirror of {@link openLightboxDialog} — same fallback and already-closed guard. */
export function closeLightboxDialog(dialog: HTMLDialogElement): void {
  if (typeof dialog.close === "function") {
    if (dialog.open) dialog.close();
    return;
  }
  dialog.removeAttribute("open");
}

export interface LightboxHookInput {
  open: boolean;
  onClose: () => void;
  /** Zero-based position in the set; with `count > 1` and `onNavigate` the arrow pair renders. */
  index?: number | undefined;
  count?: number | undefined;
  onNavigate?: ((index: number) => void) | undefined;
}

export interface LightboxController {
  dialogRef: RefObject<HTMLDialogElement | null>;
  closeRef: RefObject<HTMLButtonElement | null>;
  prevRef: RefObject<HTMLButtonElement | null>;
  nextRef: RefObject<HTMLButtonElement | null>;
  /** Whether the arrow pair renders at all (a single item has nowhere to go). */
  navigable: boolean;
  hasPrev: boolean;
  hasNext: boolean;
  /** "3 / 12", or "" when there is no set to count. */
  counter: string;
  previous: () => void;
  next: () => void;
  handleCancel: (event: SyntheticEvent<HTMLDialogElement>) => void;
  handleClick: (event: MouseEvent<HTMLDialogElement>) => void;
}

/** Marks the stage's empty area: the dialog fills the viewport, so "backdrop" is any click that
 *  lands on the dialog itself or the stage around the media rather than on a control or the media. */
export const LIGHTBOX_DISMISS_ATTR = "data-jini-lightbox-dismiss";

function isDismissTarget(target: EventTarget | null): boolean {
  return target instanceof Element && (target.tagName === "DIALOG" || target.hasAttribute(LIGHTBOX_DISMISS_ATTR));
}

function navState(input: LightboxHookInput) {
  const count = input.count ?? 0;
  const index = input.index ?? 0;
  const navigable = count > 1 && typeof input.onNavigate === "function";
  return { count, index, navigable, hasPrev: navigable && index > 0, hasNext: navigable && index + 1 < count };
}

export function useLightbox(input: LightboxHookInput): LightboxController {
  const dialogRef = useRef<HTMLDialogElement>(null);
  const closeRef = useRef<HTMLButtonElement>(null);
  const prevRef = useRef<HTMLButtonElement>(null);
  const nextRef = useRef<HTMLButtonElement>(null);
  // Captured when the dialog opens, before focus moves inside: by construction the element that
  // opened it (a card's expand button). Restored on close so keyboard users land where they were.
  const triggerRef = useRef<Element | null>(null);
  const pendingFocusRef = useRef<RefObject<HTMLButtonElement | null> | null>(null);
  const nav = navState(input);

  useEffect(() => {
    pendingFocusRef.current?.current?.focus({ preventScroll: true });
    pendingFocusRef.current = null;
  }, [input.index]);

  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog) return;
    if (input.open) {
      triggerRef.current = dialog.ownerDocument.activeElement;
      openLightboxDialog(dialog);
      // Close exists at every position (a single item has no arrows), so it is the stable initial
      // focus target. Only opening focuses it; navigation preserves the operator's current focus.
      closeRef.current?.focus({ preventScroll: true });
      return;
    }
    closeLightboxDialog(dialog);
    const trigger = triggerRef.current as { focus?: (options?: FocusOptions) => void } | null;
    trigger?.focus?.({ preventScroll: true });
    // Keyed on `open`, not `index`: navigating while open must not reopen the dialog (showModal on
    // an open dialog throws) or recapture its trigger from inside the lightbox.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input.open]);

  function go(target: number) {
    // Clamps rather than wrapping: staying on the last asset is the less surprising default for an
    // operator navigating a specific set of uploads, not a slideshow.
    if (!nav.navigable || target < 0 || target >= nav.count) return;
    // An arrow becomes disabled at its end, and a disabled focused button drops focus out of the
    // dialog. Hand focus to its neighbour first; interior moves leave focus where the operator put it.
    // The neighbour may itself be disabled until the caller re-renders, so the move is applied
    // after the index changes.
    const active = dialogRef.current?.ownerDocument.activeElement;
    if (target === 0 && active === prevRef.current) pendingFocusRef.current = nextRef;
    if (target === nav.count - 1 && active === nextRef.current) pendingFocusRef.current = prevRef;
    input.onNavigate?.(target);
  }

  // Listens on the document rather than the dialog: when the focused media is swapped out (an
  // image that failed over to a video) focus drops to the body, and arrow keys must keep working.
  useEffect(() => {
    const dialog = dialogRef.current;
    if (!dialog || !input.open) return undefined;
    const onKey = (event: globalThis.KeyboardEvent) => {
      if (event.key !== "ArrowLeft" && event.key !== "ArrowRight") return;
      // Known limitation: a focused `<video controls>` also seeks on these keys natively, so the
      // press both seeks and navigates. Callers know their media; the shell does not.
      event.preventDefault();
      go(nav.index + (event.key === "ArrowRight" ? 1 : -1));
    };
    dialog.ownerDocument.addEventListener("keydown", onKey);
    return () => dialog.ownerDocument.removeEventListener("keydown", onKey);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [input.open, nav.index, nav.count, input.onNavigate]);

  return {
    dialogRef,
    closeRef,
    prevRef,
    nextRef,
    navigable: nav.navigable,
    hasPrev: nav.hasPrev,
    hasNext: nav.hasNext,
    counter: nav.count > 1 ? `${nav.index + 1} / ${nav.count}` : "",
    previous: () => go(nav.index - 1),
    next: () => go(nav.index + 1),
    // Always prevented so the `open` prop stays the single source of truth; Escape routes through
    // onClose and the caller's state change is what actually closes the dialog.
    handleCancel: (event) => {
      event.preventDefault();
      input.onClose();
    },
    handleClick: (event) => {
      if (isDismissTarget(event.target)) input.onClose();
    },
  };
}

/**
 * Keep state/effects and DOM helpers separate from JSX so the dropdown hook can be
 * injected through useDropdown and exercised directly without driving a portaled tree.
 * Compose the smaller hooks unconditionally in their original relative order to obey
 * React hook ordering. Extracting the live DOM key handling from pure highlight decisions
 * reduces the review burden without changing focus or event-order contracts.
 */
import { useSelectPopover, useSelectPopoverPosition, repositionSelectPopover, openSelectOnKey, applySelectNavigationKey } from '../../../../react/components/select-popover.js';
export { focusableInDomOrder, resolveTabTarget } from '../../../../react/components/select-popover.js';
import { useEffect, useId, useMemo, useRef, useState } from "react";

// Below eight options, a search field adds clutter to a list that is already easy to scan.
const SEARCH_VISIBILITY_THRESHOLD = 8;

// 280px is only a placement heuristic; the panel actual maxHeight and scroll limit use
// the remaining viewport space so a low trigger does not open a mostly off-screen panel.
const ESTIMATED_PANEL_HEIGHT = 280;

export interface SelectOption {
  value: string;
  label: string;
  /** Heading shown above the first option of each run with this value (e.g. "Pages", "Posts").
   *  Callers pass options already ordered by group; search narrows rows, headings follow. */
  group?: string | undefined;
  /** Short state shown as a muted pill after the label (e.g. "draft"); omit for the normal state. */
  badge?: string | undefined;
  /** Muted secondary text after the label, e.g. a slug telling two same-titled rows apart.
   *  Search matches it too. */
  detail?: string | undefined;
}

/** The group heading to paint before `options[index]`, or null when it continues the previous run. */
export function groupHeadingAt({ options, index }: { options: readonly SelectOption[]; index: number }): string | null {
  const group = options[index]?.group;
  return group && group !== options[index - 1]?.group ? group : null;
}

export interface PanelPosition {
  top?: number | undefined;
  bottom?: number | undefined;
  left: number;
  width: number;
  maxHeight: number;
}

/**
 * Use fixed viewport-relative coordinates to escape scrolling/overflow-hidden ancestors
 * without coupling to their layout. maxHeight uses actual remaining space, not the estimate,
 * so the panel scroll area clips options before the viewport edge does.
 */
export function computePosition({ trigger }: { trigger: HTMLElement }): PanelPosition {
  const rect = trigger.getBoundingClientRect();
  const gap = 4;
  const viewportHeight = window.innerHeight;
  const spaceBelow = viewportHeight - rect.bottom;
  // Space above ends at the trigger's scrolling pane, not the viewport: an app bar above that pane
  // is not room for the panel (owner, 2026-10-15: on a short phone the list flipped up and covered
  // the top bar). With nothing scrolling but the page this is 0 and placement is unchanged.
  const spaceAbove = rect.top - scrollPaneTop({ trigger });
  const openUpward = spaceBelow < ESTIMATED_PANEL_HEIGHT && spaceAbove > spaceBelow;
  if (openUpward) {
    return { bottom: viewportHeight - rect.top + gap, left: rect.left, width: rect.width, maxHeight: Math.max(120, spaceAbove - gap * 2) };
  }
  return { top: rect.bottom + gap, left: rect.left, width: rect.width, maxHeight: Math.max(120, spaceBelow - gap * 2) };
}

/** Top edge (viewport px, never negative) of the nearest scrollable PANE around the trigger, or 0.
 * A pane is an `overflow-y: auto|scroll` ancestor at least half the viewport tall — whether or not
 * it currently overflows (a short form still sits under the app bar), while a small scrolling
 * wrapper such as a table or chip strip does not count and leaves placement as it was.
 * @complexity O(depth) computed-style reads per measurement. */
export function scrollPaneTop({ trigger }: { trigger: HTMLElement }, _optional: Record<string, never> = {}): number {
  for (let el = trigger.parentElement; el && el !== document.body && el !== document.documentElement; el = el.parentElement) {
    const overflowY = getComputedStyle(el).overflowY;
    if ((overflowY === "auto" || overflowY === "scroll") && el.clientHeight * 2 >= window.innerHeight) {
      return Math.max(0, el.getBoundingClientRect().top);
    }
  }
  return 0;
}

export function buildOptionId({ listboxId, index }: { listboxId: string; index: number }): string {
  return `${listboxId}-option-${index}`;
}

/**
 * Positioning reports a clipped or obscured trigger through onOutOfView; deciding whether
 * to close belongs to the dropdown lifecycle rather than this reusable measurement hook.
 */
export function usePanelPosition({
  open,
  triggerRef,
  panelRef,
  searchInputRef,
  showSearch,
  onOutOfView,
}: {
  open: boolean;
  triggerRef: React.RefObject<HTMLButtonElement | null>;
  panelRef: React.RefObject<HTMLDivElement | null>;
  searchInputRef: React.RefObject<HTMLInputElement | null>;
  showSearch: boolean;
  onOutOfView: () => void;
}, _optional: Record<string, never> = {}) {
  return useSelectPopoverPosition({ open, triggerRef, panelRef, measurePosition: computePosition }, {
    focusInitial: ({ panel }) => (showSearch ? searchInputRef.current : panel)?.focus(), onOutOfView,
  });
}

/** Compatibility geometry seam; lifecycle decisions are owned by the shared popover. */
export function repositionOrClose({ trigger, onOutOfView, setPosition }: { trigger: HTMLElement; onOutOfView: () => void; setPosition: (position: PanelPosition) => void }, _optional: Record<string, never> = {}) {
  repositionSelectPopover({ trigger, measurePosition: computePosition, setPosition }, { onOutOfView });
}

// A search can remove the previously highlighted option; re-anchor to the first match
// rather than keep a stale index outside the narrowed list.
function useResetHighlightOnQueryChange({
  open,
  query,
  hasMatches,
  setHighlightedIndex,
}: {
  open: boolean;
  query: string;
  hasMatches: boolean;
  setHighlightedIndex: (index: number) => void;
}) {
  useEffect(() => {
    if (!open) return;
    setHighlightedIndex(hasMatches ? 0 : -1);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [query]);
}

/**
 * Keyboard highlight used to move logically past the visible fold without scrolling its
 * row into view. nearest scrolls only what is needed instead of recentering the list and
 * fighting a user who has already scrolled it manually.
 */
function useScrollHighlightedIntoView({
  open,
  highlightedIndex,
  optionRefs,
}: {
  open: boolean;
  highlightedIndex: number;
  optionRefs: React.RefObject<Map<number, HTMLLIElement>>;
}) {
  useEffect(() => {
    if (!open || highlightedIndex < 0) return;
    const el = optionRefs.current.get(highlightedIndex);
    // Guarded the same way as `document.elementFromPoint` above — this app's own jsdom test
    // harness doesn't implement `scrollIntoView` at all (not even as a no-op), so an unguarded call
    // throws inside the effect on every highlight change.
    if (el && typeof el.scrollIntoView === "function") el.scrollIntoView({ block: "nearest" });
  }, [open, highlightedIndex]);
}

export function edgeHighlightIndex({ filteredLength, edge }: { filteredLength: number; edge: "first" | "last" }): number {
  if (filteredLength === 0) return -1;
  return edge === "first" ? 0 : filteredLength - 1;
}

export function highlightedOptionOrNull({ filtered, highlightedIndex }: { filtered: SelectOption[]; highlightedIndex: number }): SelectOption | null {
  return highlightedIndex >= 0 ? (filtered[highlightedIndex] ?? null) : null;
}

export function applyHighlightKey({ key, filtered, highlightedIndex, actions }: { key: string; filtered: SelectOption[]; highlightedIndex: number; actions: {
    preventDefault: () => void;
    moveHighlight: (delta: 1 | -1) => void;
    setHighlightedIndex: (index: number) => void;
    selectOption: (option: SelectOption) => void;
  } }
): boolean {
  return applySelectNavigationKey({ key, actions: {
    preventDefault: actions.preventDefault, move: actions.moveHighlight,
    edge: (edge) => actions.setHighlightedIndex(edgeHighlightIndex({ filteredLength: filtered.length, edge })),
    choose: () => {
      const option = highlightedOptionOrNull({ filtered, highlightedIndex });
      if (option) actions.selectOption(option);
    },
  } });
}

// Keep live event/focus effects in the key handler; move the trigger-neighbour calculation
// out so changing the DOM effects does not bury the independently testable focus decision.
/**
 * Separate hook state from rendering so search visibility, wraparound, placement and
 * out-of-view closing can be asserted directly without coupling every case to portal DOM.
 */
export function useSelectDropdown({
  value,
  onChange,
  options,
}: {
  value: string;
  onChange: (value: string) => void;
  options: SelectOption[];
}, { disabled }: { disabled?: boolean | undefined } = {}) {
  const [query, setQuery] = useState("");
  const [highlightedIndex, setHighlightedIndex] = useState(-1);

  const searchInputRef = useRef<HTMLInputElement | null>(null);
  // Index -> `<li>` node, so the highlight-follow effect below can scroll the right row into view
  // without an id-based `querySelector` (this component's ids come from `useId()`, which can
  // contain characters — `:`, in React's own scheme — that need escaping in a CSS selector; a
  // direct ref avoids that entirely). Populated by each option's own ref callback below.
  const optionRefs = useRef<Map<number, HTMLLIElement>>(new Map());

  const listboxId = useId();

  const showSearch = options.length >= SEARCH_VISIBILITY_THRESHOLD;
  const popover = useSelectPopover({ measurePosition: computePosition }, {
    disabled, dismissWhenHidden: true,
    focusInitial: ({ panel }) => (showSearch ? searchInputRef.current : panel)?.focus(),
  });
  const { open, position, triggerRef, panelRef, closePanel } = popover;
  const filtered = useMemo(() => {
    if (!showSearch || !query.trim()) return options;
    const q = query.trim().toLowerCase();
    return options.filter((o) => o.label.toLowerCase().includes(q) || Boolean(o.detail?.toLowerCase().includes(q)));
  }, [options, query, showSearch]);

  const selectedOption = options.find((o) => o.value === value) ?? null;

  function openPanel() {
    if (disabled) return;
    const initialIndex = options.findIndex((o) => o.value === value);
    setQuery("");
    popover.openPanel();
    const firstIndex = options.length ? 0 : -1;
    setHighlightedIndex(initialIndex >= 0 ? initialIndex : firstIndex);
  }

  function selectOption(option: SelectOption) {
    onChange(option.value);
    closePanel({ refocusTrigger: true });
  }

  function moveHighlight(delta: 1 | -1) {
    setHighlightedIndex((current) => {
      if (filtered.length === 0) return -1;
      return (current + delta + filtered.length) % filtered.length;
    });
  }

  useResetHighlightOnQueryChange({ open, query, hasMatches: filtered.length > 0, setHighlightedIndex });
  useScrollHighlightedIntoView({ open, highlightedIndex, optionRefs });

  function handleTriggerKeyDown(event: React.KeyboardEvent<HTMLButtonElement>) {
    openSelectOnKey({ event, open, openPanel }, { disabled });
  }
  // Escape/Tab need live propagation and focus effects. Highlight/selection keys delegate
  // to the pure helper; preventDefault is injected to preserve its order before each action.
  function handlePanelKeyDown(event: React.KeyboardEvent<HTMLDivElement>) {
    if (popover.handleDismissKey(event)) return;
    applyHighlightKey({ key: event.key, filtered, highlightedIndex, actions: {
      preventDefault: () => event.preventDefault(), moveHighlight, setHighlightedIndex, selectOption,
    } });
  }

  const optionId = (index: number) => buildOptionId({ listboxId: listboxId, index: index });

  return {
    open,
    query,
    setQuery,
    highlightedIndex,
    setHighlightedIndex,
    position,
    triggerRef,
    panelRef,
    searchInputRef,
    optionRefs,
    listboxId,
    showSearch,
    filtered,
    selectedOption,
    openPanel,
    closePanel,
    selectOption,
    handleTriggerKeyDown,
    handlePanelKeyDown,
    optionId,
  };
}

import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react';
import { useT } from '../../../i18n/index.js';
import { dayKeyFromTimestamp, resolveFacetLabel } from '../../rules.js';
import type { AssetGridDependencies } from '../../ports.js';
import type { AssetGridFacetOption, AssetGridItem, AssetGridSelectors, AssetGridViewMode } from '../../types.js';
import { useWiredAssetGridData } from '../hooks/useAssetGridData.js';
import { useWiredAssetGridLiveUpdates } from '../hooks/useAssetGridLiveUpdates.js';
import { useAssetGridSelection } from '../hooks/useAssetGridSelection.js';
import { useRubberBandDrag } from '../hooks/useRubberBandDrag.js';
import { useAssetGridKeyboardShortcuts } from '../hooks/useAssetGridKeyboardShortcuts.js';
import { useAssetGridFilters } from './useAssetGridFilters.js';
import { AssetCard } from './AssetCard.js';
import { AssetGridBody, type AssetGridBodyProps } from './AssetGridBody.js';
import { AssetGridToolbar } from './AssetGridToolbar.js';
import { SelectionActionBar } from './SelectionActionBar.js';
import { SelectionBand } from './SelectionBand.js';
import { DeleteConfirmDialog } from './DeleteConfirmDialog.js';

export interface AssetGridProps<TAsset extends AssetGridItem> {
  /** Whether this grid is the visible/active surface — gates fetch-on-mount, live updates, and keyboard shortcuts (a tab-visibility gate). Defaults to `true`. */
  active?: boolean;
  selectors: AssetGridSelectors<TAsset>;
  /** Defaults to an empty in-memory fake — a host supplies its own `data` (and optionally `liveUpdates`) port. */
  dependencies?: AssetGridDependencies<TAsset>;
  kindFacets?: AssetGridFacetOption[];
  sourceFacets?: AssetGridFacetOption[];
  /** Host-supplied, kind-aware thumbnail renderer — required, since only the host knows its asset kinds. */
  renderThumbnail: (asset: TAsset) => ReactNode;
  renderThumbnailPlaceholder?: (asset: TAsset) => ReactNode;
  /** Host-owned per-card extra actions (e.g. an "open origin" link), rendered alongside the generic Remove action. */
  renderCardExtra?: (asset: TAsset) => ReactNode;
  /** Host-owned extra bulk actions, rendered in the selection bar before the generic Delete action. */
  renderBulkActions?: (selectedIds: string[]) => ReactNode;
  /** The actual per-asset delete call. Omit to hide the built-in per-card Remove action. */
  onDeleteAsset?: (id: string) => void | Promise<void>;
  /** The actual bulk-delete call, invoked after the user confirms the dialog. Omit to hide the bulk-delete action and Delete-key shortcut entirely. */
  onDeleteSelected?: (ids: string[]) => void | Promise<void>;
  onPreview?: (asset: TAsset) => void;
  /** True while a host-owned preview surface is open — Escape/Delete then defer to it instead of the grid. */
  isPreviewOpen?: boolean;
  /** Host-specific extra toolbar controls (e.g. Upload/Sync buttons). */
  toolbarActions?: ReactNode;
  emptyState?: ReactNode;
  searchPlaceholder?: string;
  searchDebounceMs?: number;
  liveUpdateCoalesceMs?: number;
  initialViewMode?: AssetGridViewMode;
  /** Custom hook overrides for dependency injection / testing. */
  useWiredAssetGridData?: typeof useWiredAssetGridData;
  useAssetGridSelection?: typeof useAssetGridSelection;
}

function renderGridContent<TAsset extends AssetGridItem>(
  { loading, emptyState, t, ...bodyProps }: AssetGridBodyProps<TAsset> & {
    loading: boolean;
    emptyState: ReactNode;
    t: ReturnType<typeof useT>;
  },
  _options: Record<string, never> = {},
) {
  if (loading && bodyProps.assets.length === 0) return <p className="asset-grid-empty">{t('Loading…')}</p>;
  if (bodyProps.assets.length === 0) return emptyState ?? <div className="asset-grid-empty">{t('No assets yet.')}</div>;
  return <AssetGridBody {...bodyProps} />;
}

function withoutAssetIds<TAsset extends AssetGridItem>(
  { assets, ids }: { assets: TAsset[]; ids: ReadonlySet<string> }, _options = {},
): TAsset[] {
  return assets.filter(asset => !ids.has(asset.id));
}

/**
 * A live-updating, filterable, multi-selectable asset grid — the generic
 * pattern behind a photo library / DAM. See `packages/ui/source-map.md` for
 * the full retained-behavior manifest against the original `LibrarySection.tsx`.
 */
export function AssetGrid<TAsset extends AssetGridItem>({
  active = true,
  selectors,
  dependencies,
  kindFacets: configuredKindFacets,
  sourceFacets: configuredSourceFacets,
  renderThumbnail,
  renderThumbnailPlaceholder,
  renderCardExtra,
  renderBulkActions,
  onDeleteAsset,
  onDeleteSelected,
  onPreview,
  isPreviewOpen = false,
  toolbarActions,
  emptyState,
  searchPlaceholder,
  searchDebounceMs,
  liveUpdateCoalesceMs,
  initialViewMode = 'grid',
  useWiredAssetGridData: useWiredAssetGridDataHook = useWiredAssetGridData,
  useAssetGridSelection: useAssetGridSelectionHook = useAssetGridSelection,
}: AssetGridProps<TAsset>) {
  const t = useT();

  const {
    kind, setKind, source, setSource, search, setSearch,
    debouncedSearch, filtersActive, kindFacets, sourceFacets, kindFacetLabels, sourceFacetLabels,
  } = useAssetGridFilters({
    kindFacets: configuredKindFacets,
    sourceFacets: configuredSourceFacets,
    searchDebounceMs,
  });
  const [viewMode, setViewMode] = useState<AssetGridViewMode>(initialViewMode);
  const [confirmDeleteOpen, setConfirmDeleteOpen] = useState(false);
  /** Message from a delete the host rejected. Rendered inline — see `runDelete`. */
  const [deleteError, setDeleteError] = useState<string | null>(null);

  // `dependencies` (host-supplied, or omitted to fall back to the package's
  // in-memory fake) is resolved by each wirer independently — neither this
  // component nor the real `useAssetGridData`/`useAssetGridLiveUpdates`
  // hooks import `dependencies.ts` themselves.
  const { assets, setAssets, loading, reload } = useWiredAssetGridDataHook({
    dependencies,
    active,
    kind,
    source,
    debouncedSearch,
    getKind: selectors.getKind,
    matchesKindFilter: selectors.matchesKindFilter,
    mapKindToQuery: selectors.mapKindToQuery,
  });

  useWiredAssetGridLiveUpdates({
    dependencies,
    active,
    filtersActive,
    setAssets,
    reload,
    coalesceMs: liveUpdateCoalesceMs,
  });

  const { selectedIds, setSelectedIds, toggleOne, rangeTo, selectAll, clearSelection } = useAssetGridSelectionHook(assets);
  const containerRef = useRef<HTMLDivElement>(null);
  const { band, dragging, onMouseDown } = useRubberBandDrag({ containerRef, selectedIds, setSelectedIds });

  const requestDeleteSelected = useCallback(() => {
    if (selectedIds.size) setConfirmDeleteOpen(true);
  }, [selectedIds]);

  /**
   * Drops rows from the grid only once the host has actually deleted them.
   *
   * Two distinct defects here, each reported independently and each reproduced:
   *
   * - **No handler.** `onDelete*` is optional and the API says a host may omit
   *   it — but `await undefined` resolves happily, so the rows were filtered out
   *   of local state anyway. The assets appeared to delete and reappeared on the
   *   next load: the UI lying about state, with nothing persisted.
   * - **Rejected handler.** No `catch`, and the caller discards the promise with
   *   `void`, so a failed delete became an unhandled rejection with no toast, no
   *   inline error, and no visual change of any kind.
   *
   * The error is surfaced rather than swallowed. `resource-dashboard` in this
   * same package already threads an `actionError` through for exactly this
   * situation, so this follows the established pattern rather than inventing one.
   */
  const runDelete = useCallback(
    async (deleteFn: ((ids: readonly string[]) => unknown) | null, ids: readonly string[], drop: () => void) => {
      // No handler means the host cannot persist this — do not pretend it did.
      if (!deleteFn) return;
      setDeleteError(null);
      try {
        await deleteFn(ids);
      } catch (error: unknown) {
        setDeleteError(error instanceof Error ? error.message : String(error));
        return;
      }
      drop();
    },
    [],
  );

  const confirmDelete = useCallback(async () => {
    setConfirmDeleteOpen(false);
    const ids = [...selectedIds];
    if (!ids.length) return;
    const idSet = new Set(ids);
    const removeDeleted = (prev: TAsset[]) => withoutAssetIds({ assets: prev, ids: idSet });
    await runDelete(onDeleteSelected ? (batch) => onDeleteSelected([...batch]) : null, ids, () => {
      setAssets(removeDeleted);
      setSelectedIds(new Set());
    });
  }, [selectedIds, onDeleteSelected, setAssets, setSelectedIds, runDelete]);

  // Built only when the host supplied `onDeleteAsset`: the card shows its per-asset delete control
  // only when it receives a handler, so there is no "no handler" path to route through `runDelete`
  // here (the old inline `onDeleteAsset ? … : null` could never see `null` from a rendered card).
  const handleDeleteAsset = useMemo(
    () => onDeleteAsset
      ? async (id: string) => {
        const removeDeleted = (prev: TAsset[]) => withoutAssetIds({ assets: prev, ids: new Set([id]) });
        await runDelete((batch) => onDeleteAsset(batch[0]!), [id], () => {
          setAssets(removeDeleted);
        });
      }
      : undefined,
    [onDeleteAsset, setAssets, runDelete],
  );

  const handlePreview = useCallback(
    (id: string) => {
      const asset = assets.find((a) => a.id === id);
      if (asset) onPreview?.(asset);
    },
    [assets, onPreview],
  );

  useAssetGridKeyboardShortcuts({
    active,
    enabled: !confirmDeleteOpen,
    hasAssets: assets.length > 0,
    hasSelection: selectedIds.size > 0,
    isPreviewOpen,
    onSelectAll: selectAll,
    onClearSelection: clearSelection,
    onRequestDeleteSelected: requestDeleteSelected,
  });

  const getDayKey = useMemo(
    () => selectors.getDayKey ?? ((asset: TAsset) => dayKeyFromTimestamp(selectors.getTimestamp(asset))),
    [selectors],
  );

  const renderCard = useCallback(
    (asset: TAsset, index: number) => {
      const kindValue = selectors.getKind(asset);
      const sourceValue = selectors.getSource?.(asset);
      return (
        <AssetCard
          key={asset.id}
          asset={asset}
          index={index}
          selected={selectedIds.has(asset.id)}
          title={selectors.getTitle(asset)}
          subtitle={selectors.getSubtitle?.(asset)}
          kindLabel={resolveFacetLabel(kindValue, kindFacetLabels)}
          sourceLabel={sourceValue ? resolveFacetLabel(sourceValue, sourceFacetLabels) : undefined}
          renderThumbnail={renderThumbnail}
          renderThumbnailPlaceholder={renderThumbnailPlaceholder}
          onToggle={toggleOne}
          onRange={rangeTo}
          onPreview={handlePreview}
          onDeleteAsset={handleDeleteAsset}
          renderCardExtra={renderCardExtra}
        />
      );
    },
    [
      selectedIds,
      selectors,
      kindFacetLabels,
      sourceFacetLabels,
      renderThumbnail,
      renderThumbnailPlaceholder,
      toggleOne,
      rangeTo,
      handlePreview,
      onDeleteAsset,
      handleDeleteAsset,
      renderCardExtra,
    ],
  );

  return (
    <div className="asset-grid-root">
      <AssetGridToolbar
        search={search}
        onSearchChange={setSearch}
        searchPlaceholder={searchPlaceholder}
        kind={kind}
        onKindChange={setKind}
        kindFacets={kindFacets}
        source={source}
        onSourceChange={setSource}
        sourceFacets={sourceFacets}
        viewMode={viewMode}
        onViewModeChange={setViewMode}
        onRefresh={() => void reload()}
        loading={loading}
        toolbarActions={toolbarActions}
      />

      {selectedIds.size > 0 && !dragging ? (
        <SelectionActionBar
          selectedIds={[...selectedIds]}
          onSelectAll={selectAll}
          onClear={clearSelection}
          onRequestDelete={requestDeleteSelected}
          renderBulkActions={renderBulkActions}
        />
      ) : null}

      {renderGridContent({
        loading,
        emptyState,
        t,
        viewMode,
        assets,
        getDayKey,
        containerRef,
        onMouseDown,
        selecting: selectedIds.size > 0,
        renderCard,
      })}

      <SelectionBand band={band} />

      {deleteError ? (
        <p className="jini-hint jini-hint-error" role="alert">
          {deleteError}
        </p>
      ) : null}

      {confirmDeleteOpen ? (
        <DeleteConfirmDialog
          count={selectedIds.size}
          onCancel={() => setConfirmDeleteOpen(false)}
          onConfirm={() => void confirmDelete()}
        />
      ) : null}
    </div>
  );
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { BrowserHistoryEntry } from '../../types.js';
import { HISTORY_SAVE_DEBOUNCE_MS } from '../../constants.js';
import { mergeHistoryEntry, type MergeHistoryEntryMeta, type MergeHistoryEntryOptions } from '../../rules.js';
import type { BrowserHistoryStoragePort } from '../../ports.js';
import { createBrowserHistoryStorage } from '../../dependencies.js';

export interface UseBrowserHistoryOptions {
  debounceMs?: number;
}

export interface BrowserHistoryController {
  history: BrowserHistoryEntry[];
  commitVisit: (url: string, meta?: MergeHistoryEntryMeta, options?: MergeHistoryEntryOptions) => void;
  clearHistory: () => void;
}

/**
 * Loads a scope's browsing history on mount and debounce-persists it on every
 * change (mirroring the origin's 140ms-debounced save-on-change effect).
 */
export function useBrowserHistory(
  scopeKey: string,
  dependencies: { historyStorage: BrowserHistoryStoragePort },
  options: UseBrowserHistoryOptions = {},
): BrowserHistoryController {
  const debounceMs = options.debounceMs ?? HISTORY_SAVE_DEBOUNCE_MS;
  const [history, setHistory] = useState<BrowserHistoryEntry[]>(() => dependencies.historyStorage.loadHistory(scopeKey));
  const storageRef = useRef(dependencies.historyStorage);
  storageRef.current = dependencies.historyStorage;

  useEffect(() => {
    setHistory(storageRef.current.loadHistory(scopeKey));
    // Re-hydrating on scope change only; the storage port is read via a ref
    // above so a fresh `dependencies` object each render doesn't re-trigger this.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scopeKey]);

  useEffect(() => {
    const timer = setTimeout(() => storageRef.current.saveHistory(scopeKey, history), debounceMs);
    return () => clearTimeout(timer);
  }, [history, scopeKey, debounceMs]);

  const commitVisit = useCallback((url: string, meta?: MergeHistoryEntryMeta, mergeOptions?: MergeHistoryEntryOptions) => {
    setHistory((current) => mergeHistoryEntry(current, url, meta ?? {}, mergeOptions ?? {}));
  }, []);

  const clearHistory = useCallback(() => {
    setHistory([]);
    storageRef.current.saveHistory(scopeKey, []);
  }, [scopeKey]);

  return { history, commitVisit, clearHistory };
}

// Module-level singleton: `createBrowserHistoryStorage()` is stateless
// (closures over namespace/limit only), so one shared instance is enough —
// avoids reallocating a fresh port object on every `useWiredBrowserHistory`
// render for no benefit.
const defaultHistoryStorage: BrowserHistoryStoragePort = createBrowserHistoryStorage();

/**
 * Production wiring for `useBrowserHistory`: binds the real, SSR-guarded
 * `localStorage`-backed history port from `dependencies.ts` under the
 * default namespace/limit. A host that needs a non-default namespace/limit,
 * or a swappable/test port, should call `useBrowserHistory` directly with
 * its own `{ historyStorage }` instead of this zero-arg wirer.
 */
export function useWiredBrowserHistory(scopeKey: string, options?: UseBrowserHistoryOptions): BrowserHistoryController {
  return useBrowserHistory(scopeKey, { historyStorage: defaultHistoryStorage }, options);
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { CONNECTOR_AUTH_PENDING_POLL_MS } from '../constants.js';
import type {
  ConnectorAuthBridgePort,
  ConnectorAuthPendingStoragePort,
  ConnectorsPort,
} from '../ports.js';
import {
  applyConnectorStatuses,
  clearConnectorAuthorizationCancelFailuresForConnected,
  clearConnectorAuthorizationErrorsForConnected,
  clearConnectorAuthorizationPending,
  findStaleAuthorizations,
  hasConnectorStatusChanges,
  mergeConnectorActionResult,
  pruneConnectorAuthorizationPending,
  updateConnectorAuthorizationPendingFromConnectResponse,
  updateConnectorAuthorizationPendingFromStatuses,
} from '../rules.js';
import type {
  Connector,
  ConnectorAction,
  ConnectorActionResult,
  ConnectorAuthorizationPendingState,
  ConnectorAuthResultEvent,
  ConnectorStatusMap,
  PendingConnectorAction,
} from '../types.js';

export interface UseConnectorAuthorizationParams {
  connectors: Connector[];
  setConnectors: Dispatch<SetStateAction<Connector[]>>;
  /** Fired when a status refresh detects a real connect/disconnect change (for cross-surface refresh). */
  onConnectorsChanged?: () => void;
  onAuthResult?: (event: ConnectorAuthResultEvent) => void;
  pollMs?: number;
}

export interface ConnectorAuthorizationController {
  pending: ConnectorAuthorizationPendingState;
  cancelFailed: Record<string, boolean>;
  authError: Record<string, string>;
  pendingConnectorAction: PendingConnectorAction | null;
  reloadStatuses: () => Promise<ConnectorStatusMap>;
  runConnectorAction: (connectorId: string, action: ConnectorAction) => Promise<void>;
  cancelAuthorization: (connectorId: string) => Promise<void>;
}

/** Removes `key` from `record`, preserving referential identity when the key
 *  was already absent — the shared shape behind this file's several
 *  "clear this connector's flag if it has one" state updates. */
export function withoutKey<T>(record: Record<string, T>, key: string): Record<string, T> {
  if (record[key] === undefined) return record;
  const next = { ...record };
  delete next[key];
  return next;
}

export interface ConnectorActionSetters {
  onConnectorsChanged?: (() => void) | undefined;
  onAuthResult?: ((event: ConnectorAuthResultEvent) => void) | undefined;
  setPending: Dispatch<SetStateAction<ConnectorAuthorizationPendingState>>;
  setAuthError: Dispatch<SetStateAction<Record<string, string>>>;
}

/** Reports a thrown (as opposed to a resolved failure result) connector
 *  action failure via `onAuthResult`, then rethrows — shared by both
 *  {@link performConnectorConnect}'s and {@link performConnectorDisconnect}'s
 *  catch blocks, which previously duplicated this formatting. Exported for
 *  direct unit testing. */
export function reportThrownConnectorActionFailure(
  { connectorId, action }: { connectorId: string; action: ConnectorAction },
  { onAuthResult }: { onAuthResult?: ((event: ConnectorAuthResultEvent) => void) | undefined },
  err: unknown,
): never {
  onAuthResult?.({
    connectorId,
    action,
    result: 'failed',
    errorCode: err instanceof Error ? err.message : String(err),
  });
  throw err;
}

/** The resolved-success half of `performConnectorConnect`'s result handling. */
function applyConnectorConnectSuccess(
  { connectorId, result }: { connectorId: string; result: ConnectorActionResult },
  { onConnectorsChanged, onAuthResult, setPending }: Omit<ConnectorActionSetters, 'setAuthError'> & {
    setPending: Dispatch<SetStateAction<ConnectorAuthorizationPendingState>>;
  },
): void {
  if (result.connector?.status === 'connected') onConnectorsChanged?.();
  setPending((curr) => updateConnectorAuthorizationPendingFromConnectResponse(curr, result, Date.now()));
  onAuthResult?.({ connectorId, action: 'connect', result: 'success' });
}

/** The resolved-failure half of `performConnectorConnect`'s result handling
 *  (a `{ error }` result, as opposed to a thrown rejection). */
function applyConnectorConnectFailureResult(
  { connectorId, result }: { connectorId: string; result: ConnectorActionResult },
  { onAuthResult, setPending, setAuthError }: ConnectorActionSetters,
): void {
  setPending((curr) => clearConnectorAuthorizationPending(curr, connectorId));
  if (result.error) {
    setAuthError((curr) => ({ ...curr, [connectorId]: result.error! }));
  }
  onAuthResult?.({ connectorId, action: 'connect', result: 'failed', ...(result.error ? { errorCode: result.error } : {}) });
}

/** `runConnectorAction`'s `'connect'` branch, thinly wrapped by the callback
 *  below — isolated so its own control flow (success / failed-result /
 *  thrown) is readable and testable without a rendered hook. Exported for
 *  direct unit testing; not part of this package's public barrel. */
export async function performConnectorConnect(
  { connectorId, port, updateConnector }: { connectorId: string; port: ConnectorsPort; updateConnector: (next: Connector | null) => void },
  { onConnectorsChanged, onAuthResult, setPending, setAuthError, setCancelFailed }: ConnectorActionSetters & {
    setCancelFailed: Dispatch<SetStateAction<Record<string, boolean>>>;
  },
): Promise<void> {
  setCancelFailed((curr) => withoutKey(curr, connectorId));
  setAuthError((curr) => withoutKey(curr, connectorId));
  try {
    const result = await port.connectConnector(connectorId);
    updateConnector(result.connector);
    if (result.connector && !result.error) {
      applyConnectorConnectSuccess({ connectorId, result }, { onConnectorsChanged, onAuthResult, setPending });
      return;
    }
    applyConnectorConnectFailureResult({ connectorId, result }, { onAuthResult, setPending, setAuthError });
  } catch (err) {
    reportThrownConnectorActionFailure({ connectorId, action: 'connect' }, { onAuthResult }, err);
  }
}

/** `runConnectorAction`'s `'disconnect'` branch — see {@link performConnectorConnect}. */
export async function performConnectorDisconnect(
  { connectorId, port, updateConnector }: { connectorId: string; port: ConnectorsPort; updateConnector: (next: Connector | null) => void },
  { onConnectorsChanged, onAuthResult, setPending, setAuthError }: ConnectorActionSetters,
): Promise<void> {
  setPending((curr) => clearConnectorAuthorizationPending(curr, connectorId));
  setAuthError((curr) => withoutKey(curr, connectorId));
  try {
    updateConnector(await port.disconnectConnector(connectorId));
    onConnectorsChanged?.();
    onAuthResult?.({ connectorId, action: 'disconnect', result: 'success' });
  } catch (err) {
    reportThrownConnectorActionFailure({ connectorId, action: 'disconnect' }, { onAuthResult }, err);
  }
}

/**
 * The concurrency-correctness core: persists in-flight OAuth authorization
 * state, polls statuses while anything is pending, listens for the OAuth
 * popup's postMessage callback, and refreshes + auto-cancels stale
 * authorizations on window refocus (a system-browser auth flow has no
 * opener to post back to, so this is the only way that path resolves).
 */
export function useConnectorAuthorization(
  port: ConnectorsPort,
  authPendingStorage: ConnectorAuthPendingStoragePort,
  authBridge: ConnectorAuthBridgePort,
  params: UseConnectorAuthorizationParams,
): ConnectorAuthorizationController {
  const { connectors, setConnectors, onConnectorsChanged, onAuthResult, pollMs = CONNECTOR_AUTH_PENDING_POLL_MS } = params;

  const [pending, setPending] = useState<ConnectorAuthorizationPendingState>(() =>
    pruneConnectorAuthorizationPending(authPendingStorage.load(), Date.now()),
  );
  const [cancelFailed, setCancelFailed] = useState<Record<string, boolean>>({});
  const [authError, setAuthError] = useState<Record<string, string>>({});
  const [pendingConnectorAction, setPendingConnectorAction] = useState<PendingConnectorAction | null>(null);

  const connectorsRef = useRef(connectors);
  useEffect(() => {
    connectorsRef.current = connectors;
  }, [connectors]);

  const pendingRef = useRef(pending);
  useEffect(() => {
    pendingRef.current = pending;
  }, [pending]);

  const updateConnector = useCallback(
    (next: Connector | null) => {
      if (!next) return;
      setConnectors((curr) => curr.map((c) => (c.id === next.id ? mergeConnectorActionResult(c, next) : c)));
    },
    [setConnectors],
  );

  const reloadStatuses = useCallback(async (): Promise<ConnectorStatusMap> => {
    const statuses = await port.fetchConnectorStatuses();
    const statusChanged = hasConnectorStatusChanges(connectorsRef.current, statuses);
    setConnectors((curr) => applyConnectorStatuses(curr, statuses));
    setPending((curr) => updateConnectorAuthorizationPendingFromStatuses(curr, statuses, Date.now()));
    setAuthError((curr) => clearConnectorAuthorizationErrorsForConnected(curr, statuses));
    setCancelFailed((curr) => clearConnectorAuthorizationCancelFailuresForConnected(curr, statuses));
    if (statusChanged) onConnectorsChanged?.();
    return statuses;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port, setConnectors, onConnectorsChanged]);

  const cancelStaleAuthorizations = useCallback(
    async (pendingBeforeReload: ConnectorAuthorizationPendingState, statuses: ConnectorStatusMap) => {
      const stuck = findStaleAuthorizations(pendingBeforeReload, statuses, Date.now());
      if (stuck.length === 0) return;
      await Promise.allSettled(
        stuck.map(async (connectorId) => {
          let connector: Connector | null = null;
          try {
            connector = await port.cancelConnectorAuthorization(connectorId);
          } catch {
            connector = null;
          }
          if (!connector) {
            setCancelFailed((curr) => ({ ...curr, [connectorId]: true }));
            return;
          }
          updateConnector(connector);
          setCancelFailed((curr) => {
            if (curr[connectorId] === undefined) return curr;
            const next = { ...curr };
            delete next[connectorId];
            return next;
          });
          // This clear's `curr[connectorId] !== undefined` guard is
          // structurally unreachable as *true*: `authError[connectorId]`
          // and `pending[connectorId]` (this function only ever runs for
          // ids that were in `pendingBeforeReload`) can never both be set
          // for the same id at the same time. Every path that sets
          // `authError[id]` (`runConnectorAction`'s connect-failure branch)
          // unconditionally clears `pending[id]` in that same update, and
          // the only path that ever sets `pending[id]` to a new truthy
          // value again (a later connect call's success branch)
          // unconditionally clears `authError[id]` first, before ever
          // reaching its own success branch. So by the time any id reaches
          // this stale-sweep success path with a real `pending[id]` entry,
          // `authError[id]` is guaranteed already absent. Left in place
          // (not stripped) as a guard against a future refactor breaking
          // that invariant — see packages/ui/archived provenance ledger's 2026-07-22
          // dated entry for the full proof.
          // Correction (2026-10-21 coverage pass): the proof above misses one interleaving. While this
          // sweep's `cancelConnectorAuthorization` call is still awaiting, a `runConnectorAction(id,
          // 'connect')` that resolves with `{ error }` sets `authError[id]`; the cancel then succeeds and
          // this clear removes that NEWER error. Reproduced in
          // `__tests__/hooks/useConnectorAuthorization.stale-race.test.ts`; flagged for an owner decision
          // on whether the sweep should leave a fresher error alone.
          setAuthError((curr) => {
            if (curr[connectorId] === undefined) return curr;
            const next = { ...curr };
            delete next[connectorId];
            return next;
          });
          setPending((curr) => clearConnectorAuthorizationPending(curr, connectorId));
        }),
      );
    },
    [port, updateConnector],
  );

  // Persist pending state whenever it changes.
  useEffect(() => {
    authPendingStorage.save(pending);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [pending]);

  // Poll statuses while any authorization is in flight.
  useEffect(() => {
    if (Object.keys(pending).length === 0) return undefined;
    const interval = setInterval(() => {
      setPending((curr) => pruneConnectorAuthorizationPending(curr, Date.now()));
      void reloadStatuses();
    }, pollMs);
    return () => clearInterval(interval);
  }, [pending, pollMs, reloadStatuses]);

  // OAuth popup/system-browser callback.
  useEffect(() => authBridge.subscribeAuthCallback(() => void reloadStatuses()), [authBridge, reloadStatuses]);

  // Refresh + auto-cancel stale authorizations on window refocus.
  useEffect(
    () =>
      authBridge.subscribeWindowRefocus(() => {
        void (async () => {
          const pendingBeforeReload = pendingRef.current;
          const statuses = await reloadStatuses();
          await cancelStaleAuthorizations(pendingBeforeReload, statuses);
        })();
      }),
    [authBridge, reloadStatuses, cancelStaleAuthorizations],
  );

  const runConnectorAction = useCallback(
    async (connectorId: string, action: ConnectorAction) => {
      if (pendingConnectorAction) return;
      setPendingConnectorAction({ connectorId, action });
      try {
        if (action === 'connect') {
          await performConnectorConnect(
            { connectorId, port, updateConnector },
            { onConnectorsChanged, onAuthResult, setPending, setAuthError, setCancelFailed },
          );
        } else {
          await performConnectorDisconnect(
            { connectorId, port, updateConnector },
            { onConnectorsChanged, onAuthResult, setPending, setAuthError },
          );
        }
      } finally {
        setPendingConnectorAction(null);
      }
    },
    [pendingConnectorAction, port, updateConnector, onConnectorsChanged, onAuthResult],
  );

  const cancelAuthorization = useCallback(
    async (connectorId: string) => {
      const connector = await port.cancelConnectorAuthorization(connectorId);
      if (connector) {
        updateConnector(connector);
        setCancelFailed((curr) => {
          if (curr[connectorId] === undefined) return curr;
          const next = { ...curr };
          delete next[connectorId];
          return next;
        });
        setAuthError((curr) => {
          if (curr[connectorId] === undefined) return curr;
          const next = { ...curr };
          delete next[connectorId];
          return next;
        });
        setPending((curr) => clearConnectorAuthorizationPending(curr, connectorId));
        return;
      }
      try {
        const statuses = await reloadStatuses();
        if (statuses[connectorId]?.status === 'connected') return;
      } catch {
        // Keep the local failure visible when the status refresh itself fails.
      }
      setCancelFailed((curr) => ({ ...curr, [connectorId]: true }));
    },
    [port, updateConnector, reloadStatuses],
  );

  return { pending, cancelFailed, authError, pendingConnectorAction, reloadStatuses, runConnectorAction, cancelAuthorization };
}

import { useEffect, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import type { ConnectorsPort } from '../ports.js';
import { mergeConnectors } from '../rules.js';
import type { Connector } from '../types.js';

export interface ConnectorCatalogOptions {
  /** Whether the host's provider is configured (e.g. an API key is saved) — gates lazy enrichment. */
  unlocked: boolean;
  /** Bump to force both the base catalog and the enrichment pass to re-run. */
  refreshKey?: string | number;
}

export interface ConnectorCatalogController {
  connectors: Connector[];
  setConnectors: Dispatch<SetStateAction<Connector[]>>;
  loading: boolean;
  enriching: boolean;
  enriched: boolean;
}

/**
 * Owns the connector catalog's two-phase load: an always-on lightweight
 * fetch (so already-configured connectors render immediately), then a lazy
 * enrichment pass gated on `unlocked` — heavier, only worth it once the
 * host's provider is actually configured.
 * Failed reads retain the current catalog, settle their loading state and
 * report a fixed diagnostic; host/provider errors may contain credentials.
 */
export function useConnectorCatalog(port: ConnectorsPort, options: ConnectorCatalogOptions): ConnectorCatalogController {
  const { unlocked, refreshKey = 0 } = options;
  const [connectors, setConnectors] = useState<Connector[]>([]);
  const [loading, setLoading] = useState(true);
  const [enriching, setEnriching] = useState(false);
  const [enriched, setEnriched] = useState(false);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setEnriched(false);
    void (async () => {
      try {
        const next = await port.fetchConnectors();
        if (!cancelled) setConnectors((curr) => mergeConnectors(curr, next));
      } catch {
        if (!cancelled) console.error('[connectors] Catalog load failed.');
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unlocked, refreshKey]);

  useEffect(() => {
    if (!unlocked || !port.fetchConnectorEnrichment) {
      setEnriched(false);
      setEnriching(false);
      return undefined;
    }
    if (enriched) return undefined;

    let cancelled = false;
    setEnriching(true);
    void (async () => {
      try {
        const next = await port.fetchConnectorEnrichment!({ refresh: true });
        if (cancelled) return;
        setConnectors((curr) => mergeConnectors(curr, next));
        setEnriched(true);
      } catch {
        if (!cancelled) console.error('[connectors] Catalog enrichment failed.');
      } finally {
        if (!cancelled) setEnriching(false);
      }
    })();
    return () => {
      cancelled = true;
      setEnriching(false);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unlocked, refreshKey, enriched]);

  return { connectors, setConnectors, loading, enriching, enriched };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import type { Dispatch, SetStateAction } from 'react';
import { CONNECTOR_TOOL_PREVIEW_LIMIT } from '../constants.js';
import type { ConnectorsPort } from '../ports.js';
import { hasLoadedAllAdvertisedConnectorTools, mergeConnectorToolPreview } from '../rules.js';
import type { Connector } from '../types.js';

export interface UseConnectorDetailParams {
  connectors: Connector[];
  setConnectors: Dispatch<SetStateAction<Connector[]>>;
  /** Gates tool-preview hydration (e.g. the host's provider must be configured). */
  unlocked: boolean;
  /** Changes whenever a previously-failed preview fetch should be retried (e.g. catalog refresh). */
  retryToken: string;
  /** Page size requested per tool-preview fetch. Defaults to {@link CONNECTOR_TOOL_PREVIEW_LIMIT}. */
  toolsLimit?: number;
}

export interface ConnectorDetailController {
  detailConnectorId: string | null;
  detailConnector: Connector | null;
  toolPreviewLoading: boolean;
  toolsLoaded: boolean;
  openDetails: (connectorId: string) => void;
  closeDetails: () => void;
  loadMoreTools: (connectorId: string, cursor?: string) => Promise<void>;
}

/** Owns the detail drawer's open/close state and its paginated tool-preview hydration. */
export function useConnectorDetail(port: ConnectorsPort, params: UseConnectorDetailParams): ConnectorDetailController {
  const { connectors, setConnectors, unlocked, retryToken, toolsLimit = CONNECTOR_TOOL_PREVIEW_LIMIT } = params;
  const [detailConnectorId, setDetailConnectorId] = useState<string | null>(null);
  const [loadingIds, setLoadingIds] = useState<Record<string, boolean>>({});
  const [fetchedIds, setFetchedIds] = useState<Record<string, boolean>>({});
  const [failedIds, setFailedIds] = useState<Record<string, string>>({});

  const detailConnector = useMemo(
    () => (detailConnectorId ? connectors.find((c) => c.id === detailConnectorId) ?? null : null),
    [detailConnectorId, connectors],
  );

  const hydrateToolPreview = useCallback(
    async (connectorId: string, cursor?: string) => {
      if (!unlocked) return;
      if (loadingIds[connectorId]) return;
      setLoadingIds((curr) => ({ ...curr, [connectorId]: true }));
      try {
        const next = await port.fetchConnectorDetail(connectorId, {
          hydrateTools: true,
          toolsLimit,
          ...(cursor === undefined ? {} : { toolsCursor: cursor }),
        });
        if (next) {
          setConnectors((curr) => curr.map((c) => (c.id === next.id ? mergeConnectorToolPreview(c, next, cursor !== undefined) : c)));
          setFetchedIds((curr) => ({ ...curr, [connectorId]: true }));
          setFailedIds((curr) => {
            if (curr[connectorId] === undefined) return curr;
            const nextFailed = { ...curr };
            delete nextFailed[connectorId];
            return nextFailed;
          });
        } else {
          setFailedIds((curr) => ({ ...curr, [connectorId]: retryToken }));
        }
      } catch {
        setFailedIds((curr) => ({ ...curr, [connectorId]: retryToken }));
      } finally {
        setLoadingIds((curr) => ({ ...curr, [connectorId]: false }));
      }
    },
    [unlocked, loadingIds, port, setConnectors, retryToken, toolsLimit],
  );

  useEffect(() => {
    if (!detailConnector) return;
    if (!unlocked) return;
    if (hasLoadedAllAdvertisedConnectorTools(detailConnector)) return;
    if (fetchedIds[detailConnector.id]) return;
    if (failedIds[detailConnector.id] === retryToken) return;
    if (loadingIds[detailConnector.id]) return;
    void hydrateToolPreview(detailConnector.id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [unlocked, detailConnector, failedIds, fetchedIds, loadingIds, retryToken]);

  const openDetails = useCallback((connectorId: string) => {
    setFailedIds((curr) => {
      if (curr[connectorId] === undefined) return curr;
      const next = { ...curr };
      delete next[connectorId];
      return next;
    });
    setDetailConnectorId(connectorId);
  }, []);

  const closeDetails = useCallback(() => setDetailConnectorId(null), []);

  const toolsLoaded = detailConnector
    ? Boolean(fetchedIds[detailConnector.id]) ||
      failedIds[detailConnector.id] === retryToken ||
      hasLoadedAllAdvertisedConnectorTools(detailConnector)
    : false;

  return {
    detailConnectorId,
    detailConnector,
    toolPreviewLoading: detailConnector ? Boolean(loadingIds[detailConnector.id]) : false,
    toolsLoaded,
    openDetails,
    closeDetails,
    loadMoreTools: hydrateToolPreview,
  };
}

import { useEffect, type CSSProperties, type ReactNode } from 'react';
import { agentHandleProps, agentSubHandle } from '@jini-ai/agentic';
import { useT } from '../../../i18n/index.js';
import { DEFAULT_AGENT_CLI_ENV_FIELDS } from '../../constants.js';
import type { ExecutionPort } from '../../ports.js';
import {
  groupPresets,
  isProviderConfigured,
  nextConfigForAgentCliEnvChange,
  nextConfigForAgentModel,
  nextConfigForAgentReasoning,
  nextConfigForAgentSelect,
  nextConfigForModeChange,
  nextConfigForPresetSelect,
  resolveSelectedPreset,
  selectedAgentModel,
} from '../../rules.js';
import type {
  AgentCliEnvFieldSpec,
  DetectedAgent,
  ExecutionConfig,
  ExecutionMode,
  ProviderPreset,
} from '../../types.js';
import { useExecutionTab } from '../hooks/useExecutionTab.js';
import { ByokProviderForm } from './ByokProviderForm.js';
import { LocalCliAgentList } from './LocalCliAgentList.js';
import { ProviderChipGroup } from './ProviderChipGroup.js';

export interface ExecutionTabProps {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  port: ExecutionPort;
  /** Host-owned endpoint catalog. Omitted means manual endpoint entry. */
  presets?: readonly ProviderPreset[];
  /** Per-agent CLI env-var catalog (proxy URLs, custom config dirs, a
   *  binary-path override). Defaults to this package's starter set for the
   *  CLIs it already knows about — a host with a different/larger agent
   *  roster passes its own, same convention as `presets`. */
  cliEnvFields?: readonly AgentCliEnvFieldSpec[];
  /** Disables Local CLI with an explanatory title, for hosts that cannot run
   *  local subprocesses (e.g. a hosted deployment). */
  localCliUnavailableReason?: string;
  /** Rendered in each agent card's icon slot — vendor marks are the host's to
   *  supply, since this package ships no logo set. */
  renderAgentIcon?: (agent: DetectedAgent) => ReactNode;
  /** Where local-CLI detection actually runs, in the host's words. See
   *  `LocalCliAgentListProps.scopeLabel` — a hosted deployment must not tell
   *  the operator these are the CLIs "on this machine". */
  localCliScopeLabel?: string;
  autoDetect?: boolean;
  ariaLabel?: string;
  /**
   * Pass-throughs to the internal `ByokProviderForm`'s identically-named props — see that
   * component's own doc comments for the full contract (write-only credential display, the
   * placeholder-never-a-value safety property, and the footer slot).
   *
   * Added here rather than only on `ByokProviderForm` because a host whose BYOK config is
   * ALSO offering Local CLI (the common case — see `types.ts`'s `ExecutionMode`) has no way to
   * reach `ByokProviderForm` directly: it is `ExecutionTab` that owns the mode switch and
   * renders the BYOK section conditionally. Without these, a host storing its admin's own key
   * server-side (as opposed to the visitor-key screen, which renders `ByokProviderForm` on its
   * own because it has no Local CLI option to switch away from) would have to fork this
   * component to add write-only display — exactly the mistake one host integration already made
   * and reverted. Omitted by every existing caller, so the rendered output is byte-identical
   * without them.
   */
  apiKeyFooter?: ReactNode;
  formFooter?: ReactNode;
  apiKeyStoredExternally?: boolean;
  apiKeyPlaceholder?: string;
  /**
   * Whether the tab may run model discovery right now. Defaults to `true`.
   *
   * For a host that holds a key the browser cannot read and knows that key cannot be used at the
   * selected endpoint, e.g. a key its backend saved for another provider and refuses to send anywhere
   * else. With nothing typed, discovery then has nothing it may send, so the tab stays idle instead of
   * showing that refusal.
   *
   * Read when discovery would run anyway (an endpoint change, a key typed or cleared, Test connection)
   * and deliberately NOT a trigger of its own. A host flips it to `true` when its stored key is
   * re-pointed at the selected endpoint, and probing on that flip alone would send the key there
   * without the operator asking. Turning it `false` only resets discovery to idle and discards any
   * response still in flight, which sends nothing.
   */
  canDiscoverModels?: boolean;
  /** Pass-through to `useExecutionTab`'s `describeProbeError` — see that option's doc. Words a failed
   *  model discovery and a failed Test connection. */
  describeProbeError?: (error: unknown) => string;
  /**
   * This tab's own agent handle, published by the host. Every interactive control below — the mode
   * switch, every provider chip, the whole BYOK card, and every detected-CLI card — derives its own
   * `data-agent-*` handle from this ONE base via `agentHandleProps`/`agentSubHandle`. Omit and no
   * `data-agent-*` markup is emitted anywhere in this tab — additive, never a behavior change.
   */
  agentHandle?: string;
}

/**
 * "Execution mode" — the Local CLI ↔ bring-your-own-key switch, its provider
 * and gateway chip rows, and the BYOK credential form.
 *
 * Controlled: the host owns `config` and persists it however it likes (in the
 * canary host that is a settings ledger). The tab owns only the async edges,
 * via `ExecutionPort`.
 *
 * Origin: `SettingsDialog.tsx` lines 4080-5336. The origin's managed-runtime
 * wallet — balance polling, top-up, sign-in coachmarks — is deliberately not
 * ported; it is product-bound, not generic.
 */
export function ExecutionTab({
  config,
  onConfigChange,
  port,
  presets = [],
  cliEnvFields = DEFAULT_AGENT_CLI_ENV_FIELDS,
  localCliUnavailableReason,
  renderAgentIcon,
  localCliScopeLabel,
  autoDetect = true,
  ariaLabel,
  apiKeyFooter,
  formFooter,
  apiKeyStoredExternally,
  apiKeyPlaceholder,
  canDiscoverModels = true,
  describeProbeError,
  agentHandle,
}: ExecutionTabProps) {
  const t = useT();
  const tab = useExecutionTab({
    port,
    autoDetect: autoDetect && config.mode === 'local-cli',
    ...(describeProbeError ? { describeProbeError } : {}),
  });
  const { loadModels, resetModelDiscovery } = tab;

  const selectedPreset = resolveSelectedPreset(presets, config.byok);

  /**
   * Whether a key EXISTS, never what it is. Keyed on the boolean specifically so the effect below
   * re-runs exactly once on the `false -> true` transition — a saved key hydrating from storage
   * after first paint, or an operator finishing entry — and NOT once per character, which is what
   * keying on `apiKey` itself would have done.
   */
  const hasApiKey = config.byok.apiKey.trim().length > 0;

  // Re-discover models whenever the selected endpoint changes (preset pick,
  // manual protocol switch, or a typed base URL settling on a new value), and
  // once a key first becomes available (`hasApiKey`).
  //
  // Still deliberately NOT keyed on `apiKey`'s VALUE or on `model` — refetching
  // on every keystroke would spam the provider (and this catalog's own
  // discovery has been observed tripping Gemini's per-minute "Model operations"
  // rate limit, which then presents as an ordinary discovery failure).
  //
  // `hasApiKey` is what makes this effect self-healing. Before it, a discovery
  // attempt that ran before any key existed left its error on screen forever —
  // typing or saving a key changes none of `protocol`/`baseUrl`/`providerId`,
  // so nothing re-triggered it, and the Model field silently fell back to the
  // preset's short static `preferredModels` list while the operator's key could
  // actually see far more. Reported live: the field defaulted to a stale
  // `gemini-2.5-flash` even though `Test Key` — the one control that did force
  // a fresh attempt, see `ByokProviderForm`'s `onTestConnection` below —
  // returned 42 models.
  //
  // `canDiscoverModels` is read here but is deliberately not a dependency — see that prop's doc for why
  // its turning `true` on its own must never probe.
  useEffect(() => {
    if (config.mode !== 'byok' || typeof port.listModels !== 'function' || !canDiscoverModels) return;
    loadModels(config.byok);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [config.mode, port, loadModels, config.byok.protocol, config.byok.baseUrl, config.byok.providerId, hasApiKey]);

  // All a turn to "cannot discover" does: drop the current result and any response still in flight —
  // e.g. one started before the host learned that its stored key belongs to another endpoint.
  useEffect(() => {
    if (!canDiscoverModels) resetModelDiscovery();
  }, [canDiscoverModels, resetModelDiscovery]);
  // No "local-cli while unavailable" guard here: `ExecutionModeSwitch` renders that tab `disabled`
  // whenever `localCliUnavailableReason` is set, and React never dispatches `onClick` for a disabled
  // button, so `setMode('local-cli')` cannot be reached in that state.
  const setMode = (mode: ExecutionMode) => {
    onConfigChange(nextConfigForModeChange(config, mode));
  };

  const modes: ReadonlyArray<{ id: ExecutionMode; title: string; meta: string }> = [
    { id: 'local-cli', title: t('Local CLI'), meta: t('Run an agent installed on this machine') },
    { id: 'byok', title: t('BYOK'), meta: t('Use your own API credentials') },
  ];

  return (
    <div className="jini-settings-execution" aria-label={ariaLabel ?? t('Execution mode')}>
      <ExecutionModeSwitch
        modes={modes}
        activeMode={config.mode}
        localCliUnavailableReason={localCliUnavailableReason}
        onSelect={setMode}
        agentHandle={agentHandle}
      />

      {config.mode === 'local-cli' ? (
        <LocalCliPane
          config={config}
          onConfigChange={onConfigChange}
          tab={tab}
          cliEnvFields={cliEnvFields}
          renderAgentIcon={renderAgentIcon}
          localCliScopeLabel={localCliScopeLabel}
          agentHandle={agentHandle}
        />
      ) : (
        <ByokPane
          config={config}
          onConfigChange={onConfigChange}
          presets={presets}
          selectedPreset={selectedPreset}
          tab={tab}
          canDiscoverModels={canDiscoverModels}
          canListModels={typeof port.listModels === 'function'}
          formProps={{ apiKeyFooter, formFooter, apiKeyStoredExternally, apiKeyPlaceholder }}
          agentHandle={agentHandle}
        />
      )}
    </div>
  );
}

/** The Local CLI ↔ BYOK segmented control. Local CLI is disabled, with the host's reason as its
 *  tooltip and caption, while the host says it is unavailable. */
function ExecutionModeSwitch({ modes, activeMode, localCliUnavailableReason, onSelect, agentHandle }: {
  modes: ReadonlyArray<{ id: ExecutionMode; title: string; meta: string }>;
  activeMode: ExecutionMode;
  localCliUnavailableReason: string | undefined;
  onSelect: (mode: ExecutionMode) => void;
  agentHandle: string | undefined;
}) {
  const t = useT();
  const localCliDisabled = Boolean(localCliUnavailableReason);
  return (
    <div
      className="jini-seg-control"
      role="tablist"
      aria-label={t('Execution mode')}
      style={{ '--seg-cols': modes.length } as CSSProperties}
    >
      {modes.map((mode) => {
        const disabled = mode.id === 'local-cli' && localCliDisabled;
        return (
          <button
            key={mode.id}
            type="button"
            role="tab"
            aria-selected={activeMode === mode.id}
            disabled={disabled}
            title={disabled ? localCliUnavailableReason : undefined}
            className={'jini-seg-btn' + (activeMode === mode.id ? ' active' : '')}
            onClick={() => onSelect(mode.id)}
            {...agentHandleProps({}, { base: agentHandle, ...({ action: `mode-${mode.id}`, role: 'button', label: mode.title }) })}
          >
            <span className="jini-seg-title">{mode.title}</span>
            <span className="jini-seg-meta">
              {disabled ? localCliUnavailableReason : mode.meta}
            </span>
          </button>
        );
      })}
    </div>
  );
}

/** The BYOK half of the tab: protocol and gateway chip rows over the credential card. */
function ByokPane({
  config, onConfigChange, presets, selectedPreset, tab, canDiscoverModels, canListModels, formProps, agentHandle,
}: {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  presets: readonly ProviderPreset[];
  selectedPreset: ProviderPreset | null;
  tab: ReturnType<typeof useExecutionTab>;
  canDiscoverModels: boolean;
  canListModels: boolean;
  formProps: {
    apiKeyFooter: ReactNode;
    formFooter: ReactNode;
    apiKeyStoredExternally: boolean | undefined;
    apiKeyPlaceholder: string | undefined;
  };
  agentHandle: string | undefined;
}) {
  const t = useT();
  const { protocols, gateways } = groupPresets(presets);
  const configuredPresetIds = new Set(
    presets.filter((preset) => isProviderConfigured(config.byok, preset)).map((preset) => preset.id),
  );
  const selectPreset = (preset: ProviderPreset) =>
    onConfigChange({ ...config, byok: nextConfigForPresetSelect(config.byok, preset) });
  const selectedPresetId = selectedPreset?.id ?? null;
  return (
    <section className="jini-settings-section jini-settings-byok">
      <ProviderChipGroup
        label={t('Protocols')}
        presets={protocols}
        selectedPresetId={selectedPresetId}
        configuredPresetIds={configuredPresetIds}
        onSelect={selectPreset}
        configuredLabel={t('Configured')}
        unsetLabel={t('Not configured')}
        {...subHandleProps(agentHandle, 'protocol')}
      />
      <ProviderChipGroup
        label={t('Gateways')}
        presets={gateways}
        selectedPresetId={selectedPresetId}
        configuredPresetIds={configuredPresetIds}
        onSelect={selectPreset}
        configuredLabel={t('Configured')}
        unsetLabel={t('Not configured')}
        {...subHandleProps(agentHandle, 'gateway')}
      />
      <ByokProviderForm
        config={config.byok}
        onConfigChange={(byok) => onConfigChange({ ...config, byok })}
        preset={selectedPreset}
        {...subHandleProps(agentHandle, 'byok')}
        // The WHOLE catalog, not the `protocols`/`gateways` halves the chip rows take: the card
        // only reads it to recognise a pasted key as some other row's, and a key pasted from a
        // gateway into a protocol field is exactly the mistake worth naming.
        presets={presets}
        modelDiscovery={tab.modelDiscovery}
        connectionTest={tab.connectionTest}
        // Also re-runs discovery with the CURRENT byok config, not just the
        // connectivity probe — see this file's model-discovery effect above
        // for why that matters: a stale "could not load live models" error
        // from before this key existed (or from any earlier transient
        // failure) would otherwise never clear, even once Test Connection
        // itself goes green with the same config.
        onTestConnection={() => {
          tab.testConnection(config.byok);
          if (canDiscoverModels && canListModels) tab.loadModels(config.byok);
        }}
        {...(formProps.apiKeyFooter !== undefined ? { apiKeyFooter: formProps.apiKeyFooter } : {})}
        {...(formProps.formFooter !== undefined ? { formFooter: formProps.formFooter } : {})}
        {...(formProps.apiKeyStoredExternally !== undefined ? { apiKeyStoredExternally: formProps.apiKeyStoredExternally } : {})}
        {...(formProps.apiKeyPlaceholder !== undefined ? { apiKeyPlaceholder: formProps.apiKeyPlaceholder } : {})}
      />
    </section>
  );
}

/** The Local CLI half of the tab: detected agents, wired to the config's next-state rules. */
function LocalCliPane({ config, onConfigChange, tab, cliEnvFields, renderAgentIcon, localCliScopeLabel, agentHandle }: {
  config: ExecutionConfig;
  onConfigChange: (config: ExecutionConfig) => void;
  tab: ReturnType<typeof useExecutionTab>;
  cliEnvFields: readonly AgentCliEnvFieldSpec[];
  renderAgentIcon: ExecutionTabProps['renderAgentIcon'];
  localCliScopeLabel: ExecutionTabProps['localCliScopeLabel'];
  agentHandle: string | undefined;
}) {
  return (
    <LocalCliAgentList
      agents={tab.agents}
      config={config.localCli}
      scan={tab.scan}
      agentTest={tab.agentTest}
      onSelect={(agentId) => onConfigChange(nextConfigForAgentSelect(config, agentId))}
      onModelChange={(agentId, model) =>
        onConfigChange(nextConfigForAgentModel(config, agentId, model))
      }
      onReasoningChange={(agentId, reasoning) =>
        onConfigChange(nextConfigForAgentReasoning(config, agentId, reasoning))
      }
      onEnvChange={(agentId, envKey, value) =>
        onConfigChange(nextConfigForAgentCliEnvChange(config, agentId, envKey, value))
      }
      cliEnvFields={cliEnvFields}
      onRescan={tab.canRescan ? tab.rescan : undefined}
      onTest={
        tab.canTestAgent
          ? (agent) => tab.testAgent(agent.id, selectedAgentModel(config.localCli, agent) || undefined)
          : undefined
      }
      renderAgentIcon={renderAgentIcon}
      scopeLabel={localCliScopeLabel}
      {...subHandleProps(agentHandle, 'local-cli')}
    />
  );
}

/** `{ agentHandle }` for a child's sub-handle under this tab's base, or nothing when no base is set. */
function subHandleProps(agentHandle: string | undefined, action: string): { agentHandle?: string } {
  return agentHandle ? { agentHandle: agentSubHandle({ base: agentHandle, action }) } : {};
}

import { useEffect, useRef, useState } from "react";
import type { ByokConfig } from "../../types.js";
import { useSerialWrites } from "../../../panel-kit/hooks/use-serial-writes.hooks.js";
import { useSettlementGeneration } from "../../../panel-kit/hooks/use-settlement-generation.hooks.js";
import type { SettingsSliceRefreshPort } from "../../../panel-kit/hooks/use-settings-slice.hooks.js";

/** The metadata read by this controller. Hosts retain any additional write-only view fields. */
export interface ExecutionCredentialView { isSet: boolean; masked: string | null; baseUrl: string | null }
/** Explicit key and non-secret patches remain distinct; the controller never autosaves a key. */
export interface ExecutionCredentialPatch {
  apiKey?: string; protocol?: string; providerId?: string | null; baseUrl?: string; model?: string; maxTokens?: number;
}
/** The host owns routes and authorization; only a write-only view may be returned. */
export interface ExecutionCredentialPort<TStored extends ExecutionCredentialView> {
  loadAdminExecutionCredential(required: Record<string, never>, optional?: Record<string, never>): Promise<TStored>;
  saveAdminExecutionCredential(required: { patch: ExecutionCredentialPatch }, optional?: Record<string, never>): Promise<TStored>;
}
/** Host migration, notification and display policies. Product-specific error/copy stays in the host. */
export interface ExecutionCredentialEffects<TStored extends ExecutionCredentialView> {
  namespace: string;
  refreshPort: SettingsSliceRefreshPort;
  readLegacyCredential(required: Record<string, never>, optional?: Record<string, never>): string | null;
  clearLegacyCredential(required: Record<string, never>, optional?: Record<string, never>): void;
  describeError(required: { error: unknown; fallback: string }, optional?: Record<string, never>): string;
  hasTypedKey(required: { apiKey: string }, optional?: Record<string, never>): boolean;
  storedKeyIsForOtherEndpoint(required: { stored: TStored | null; baseUrl: string }, optional?: Record<string, never>): boolean;
  hasUsableKey(required: { apiKey: string; stored: TStored | null; baseUrl: string }, optional?: Record<string, never>): boolean;
  storedKeyBlocksProbe(required: { apiKey: string; stored: TStored | null; baseUrl: string }, optional?: Record<string, never>): boolean;
  credentialHint(required: { stored: TStored | null; storedKeyIsForOtherEndpoint: boolean }, optional?: { locale?: string | undefined }): string | undefined;
}
/**
 * @file State for the admin's own BYOK credential — the "Save key" and "Save settings" controls and
 * the one-time `localStorage`-to-server migration prompt, shared verbatim by `SettingsUi.tsx`'s Execution tab
 * and `AiAssistant.tsx`'s `AdminExecutionMode` (both render `ExecutionTab` over the SAME ledger
 * namespace and now the same server-side credential row; per `AdminExecutionMode`'s own "must never
 * disagree" comment about `useStoredCredential`, the two mounts cannot be allowed to diverge here
 * either — hence one hook rather than two independent implementations).
 *
 * Modeled closely on the already-shipped, owner-reviewed
 * `features/ai-assistant/hooks/use-visitor-credential-form.hooks.ts`: explicit save only, the field
 * clears on success, a failed save never touches what is already stored/local. The two differ where
 * the underlying screens differ — this one does not own the whole BYOK form (only the "Save key"
 * affordance under the key field and the "Save settings" affordance at the foot of the card, since
 * `ExecutionTab` owns the provider chips and the fields themselves via the existing `core.execution`
 * ledger slice) and it additionally owns the migration prompt, which the visitor screen has no
 * equivalent of (there was never a browser-local visitor key to migrate).
 *
 * ## One button per patch (owner ruling, 2026-09-02)
 *
 * There used to be ONE control here, writing the key and the row's non-secret companion fields
 * together. That overload is what made the screen lie: pressing it with a blank field sent a patch
 * with no `apiKey` at all and still answered "Saved to the server, encrypted." Patching the message
 * left the cause in place, and disabling the button on a blank field broke the only way to save a
 * model change. The split closes both: `saveKey` writes `{ apiKey }`, `saveSettings` writes the
 * non-secret fields and never an `apiKey` property, and each carries its own save state so neither
 * can report the other's work.
 *
 * ## Cross-mount staleness (disclosed residual, closed here)
 *
 * `stored`/`apiKeyStoredExternally` is each mounted instance's OWN copy of one server fact — every
 * `SettingsUi.tsx` mount, every `AiAssistant.tsx` mount, AND `AssistantDock.hooks.tsx`'s own
 * independent `loadAdminExecutionCredential()` call (`useExecutionConfig`'s `hasStoredAdminKey`) are
 * three separate reads of the same row. A save/migrate in ONE of them updated only its own local
 * `stored` state, so the other two kept showing whatever they last fetched — briefly, if the operator
 * happened to remount that screen soon after, or indefinitely for the dock, which mounts once at the
 * app shell and never remounts for the session (`AssistantDock.tsx`'s own header comment). Now wired
 * to `settings-refresh-bus.ts`, the same seam `useSettingsSlice`'s `runSave` already uses for exactly
 * this "same-tab sibling with no shared state" problem: every successful write publishes
 * `EXECUTION_NAMESPACE`, and every mount (including the publisher's own, harmlessly — see
 * `runSave`'s doc for why that redundant self-refresh is accepted rather than tracked around) re-reads
 * on receiving it.
 *
 * `port` (the two functions that reach `api.getAdminExecutionCredential`/`api.setAdminExecutionCredential`
 * under the hood) is injected — see `admin-execution-credential-port.hooks.ts` for exactly what is and
 * is not in it, and why. `useWiredAdminExecutionCredential` below is the zero-argument pair
 * `SettingsUi.tsx`/`AiAssistant.tsx` actually mount; `AssistantDock.hooks.tsx`'s own separate
 * `loadAdminExecutionCredential()` call (this file's "Cross-mount staleness" doc above) is a
 * different hook entirely, out of scope here.
 */

export type ExecutionCredentialSaveState =
  | { status: "idle" }
  | { status: "saving" }
  | { status: "saved" }
  | { status: "error"; message: string };

export interface UseExecutionCredentialInput {
  locale?: string | undefined;
  /** The live BYOK half of whichever `ExecutionConfig` the host owns. Read fresh on every
   *  `saveKey()`/`migrateLegacyKey()` call (never captured once), so a save always sends whatever
   *  protocol/baseUrl/model/maxTokens the operator currently has selected. */
  byok: ByokConfig;
  /** How a successful key save clears the just-saved plaintext back out of the host's own state —
   *  same reasoning `use-visitor-credential-form.hooks.ts`'s `saveCredential` documents: leaving it
   *  in React state after it is safely persisted keeps it readable in devtools for no benefit, and
   *  the masked placeholder now carries the "which key" answer the field would otherwise be giving. */
  onByokChange: (next: ByokConfig) => void;
}

export interface ExecutionCredentialController<TStored extends ExecutionCredentialView> {
  /** The server's write-only view of what is currently stored — `null` until the initial GET
   *  settles. Never contains key material. */
  stored: TStored | null;
  /** Tells `ExecutionTab`'s `apiKeyStoredExternally` prop that an empty key field is not a missing
   *  required field, because a credential already exists server-side FOR THE FORM'S ENDPOINT. A key
   *  stored for another endpoint does not count (the server will not send it here), so after a
   *  provider switch the field is required again and Test connection waits for a typed key. Same rule
   *  as the visitor screen: `lib/stored-credential-endpoint.ts`'s `hasUsableKey`. */
  apiKeyStoredExternally: boolean;
  /** The server's `••••<last 4>`, or `undefined` when nothing is stored or the stored key belongs to
   *  another endpoint (under a different provider it would read as that provider's key) — feeds
   *  `ExecutionTab`'s `apiKeyPlaceholder`. Always a placeholder, never a value: `byok.apiKey` is
   *  untouched by this controller until an explicit save succeeds. */
  apiKeyPlaceholder: string | undefined;
  /** A key is stored, but the server saved it for another endpoint than the form's (a provider
   *  switch). Drives the key footer's "paste a key for this one" line. See
   *  `lib/stored-credential-endpoint.ts`'s `storedKeyIsForOtherEndpoint`; `false` until the stored
   *  view loads. */
  storedKeyIsForOtherEndpoint: boolean;
  /** Feeds `ExecutionTab`'s `canDiscoverModels`: `false` only when nothing is typed and the stored key
   *  belongs to another endpoint, the one discovery the server can only refuse. `ExecutionTab` reads
   *  it but never probes merely because it turned `true` — "Save settings" re-pointing the stored row
   *  flips it, and that must not send the old provider's key to the new endpoint unasked. */
  canDiscoverModels: boolean;
  /** The "Save key" button's own save state — and the migration prompt's, which writes the same
   *  key. Never advanced by {@link saveSettings}; see {@link settingsSaveState}. */
  saveState: ExecutionCredentialSaveState;
  /** The "Save settings" button's own save state, deliberately separate from {@link saveState}.
   *
   *  One shared state is what made the old single control dishonest: its status line said "Saved to
   *  the server, encrypted." after a press that sent no key at all. Two buttons that write two
   *  disjoint patches need two answers, so each owns its own status line and neither can report the
   *  other's work. */
  settingsSaveState: ExecutionCredentialSaveState;
  /** Whether {@link saveKey} would do anything right now — the same "is there a key in the field"
   *  guard `saveKey` itself applies, exposed so the Save key button can disable correctly without
   *  duplicating the rule.
   *
   *  Derived synchronously from the trimmed field on every render, never debounced: a delayed
   *  evaluation would leave the button enabled for the moment right after the field is cleared,
   *  which is the bug this rule exists to close, merely shortened. */
  canSaveKey: boolean;
  /**
   * Explicit save, called ONLY from a "Save key" button press — never from any debounced or
   * automatic path. Writes the KEY and nothing else: the patch is `{ apiKey }`, with no
   * protocol/providerId/baseUrl/model/maxTokens riding along.
   *
   * That narrowing (owner ruling, 2026-09-02) is the fix for a whole defect class rather than one
   * bug. A control that wrote two different things could not honestly report what it had just done,
   * and the "which of my two jobs did I do" bookkeeping that answer needed was itself the thing that
   * let an `apiKey: ""` reach the server. A button with one job needs no bookkeeping. The
   * non-secret fields moved to {@link saveSettings}.
   *
   * A no-op when the field is empty — see {@link canSaveKey}.
   */
  saveKey: () => Promise<void>;
  /**
   * Explicit save, called ONLY from a "Save settings" button press. Writes
   * protocol/providerId/baseUrl/model/maxTokens and NEVER an `apiKey` property — not even an empty
   * string, which the server rejects (400) and which is precisely the write the old overloaded
   * control could make.
   *
   * ## Why this is not a second writer for the ledger's values
   *
   * The same protocol/baseUrl/model the operator edits here ALSO live in the `core.execution`
   * settings ledger, written on their own debounced path by `use-admin-execution-mode.hooks.ts`'s
   * `useSettingsSlice`. Two stores, deliberately (see `execution-settings.ts`'s
   * `loadAdminExecutionCredential` doc): the ledger holds the live values this browser's form shows,
   * while the credential ROW holds a snapshot the SERVER reads when a browser sends no credential of
   * its own — `byok-credential.ts`'s `createStoredExecutionCredentialPort`, which treats a row with
   * no `model` as unusable.
   *
   * Before the split, that snapshot was refreshed as a side effect of every key save. With
   * {@link saveKey} narrowed to the key, this button is the ONLY thing that writes it. Each of the
   * two stores still has exactly one writer; what changed is that the credential row's writer is now
   * a control the operator can see and press, rather than a hidden passenger on a different button.
   */
  saveSettings: () => Promise<void>;
  /** A pre-server-store `localStorage` key this browser still holds, or `null` when there is
   *  nothing to migrate (never had one, already migrated, or the prompt was dismissed this
   *  session). Non-`null` is what a caller renders the migration banner on. */
  legacyKey: string | null;
  /** Confirms the migration: PUTs the legacy key (plus the current `byok` non-secret fields) to the
   *  server, and clears the `localStorage` entry ONLY once that PUT has actually succeeded — a
   *  failed save leaves the local copy fully intact, per the design's explicit "no auto-clear"
   *  requirement. */
  migrateLegacyKey: () => Promise<void>;
  /** Declines the prompt for the rest of this mount — no `localStorage` change either way. The
   *  design's "no auto-clear" rule means a decline must not delete the local key, so the prompt is
   *  free to reappear on a later mount (a page reload, navigating back to this tab); that is a minor
   *  repeat-ask, not a data-loss risk, which is the asymmetry the design accepts. */
  dismissLegacyPrompt: () => void;
}

/**
 * @complexity Time: O(1) per call — one GET on mount, one PUT per explicit save/migrate. Space:
 * O(1) — no caller-controlled collections.
 */
export function useExecutionCredential<TStored extends ExecutionCredentialView>(
  { byok, onByokChange, locale, port, effects }: UseExecutionCredentialInput & { port: ExecutionCredentialPort<TStored>; effects: ExecutionCredentialEffects<TStored> },
  _options: Record<string, never> = {},
): ExecutionCredentialController<TStored> {
  const [stored, setStored] = useState<TStored | null>(null);
  const [saveState, setSaveState] = useState<ExecutionCredentialSaveState>({ status: "idle" });
  const [settingsSaveState, setSettingsSaveState] = useState<ExecutionCredentialSaveState>({ status: "idle" });
  const [legacyKey, setLegacyKey] = useState<string | null>(null);
  const [legacyDismissed, setLegacyDismissed] = useState(false);

  // The operator's latest `byok`/`onByokChange`, read back by `saveKey` AFTER its await — never the
  // `byok` its own closure captured at button-press time. Without this, a provider chip click, a
  // model edit, or a newly typed key made while a key save was in flight was reverted to the
  // click-time config the instant the response landed, and the ledger slice then autosaved that
  // revert (S1). Assigning a ref during render is the same idiom `use-visitor-credential-
  // form.hooks.ts`'s `apiRef` uses for the identical reason.
  const inputRef = useRef<UseExecutionCredentialInput>({ byok, onByokChange });
  inputRef.current = { byok, onByokChange };

  // The server rebuilds every write from the row it read when the request arrived
  // (`execution-credential-store.ts`'s `setExecutionCredential`: read -> seal -> upsert the WHOLE
  // merged record), so a key save, a settings save and a migration in flight together each merge
  // over the same stale row and the later upsert reverts the other's fields — both still answer
  // 200. Chained, each write reads what the one before it actually wrote. Tab-local only: two tabs,
  // or the Settings and AI Assistant mounts in two different browser windows, can still race — that
  // needs a server-side concurrency check (see the plan's "Needs owner decision" section). Same
  // shared lane `use-visitor-credential-form.hooks.ts` (`8ac256353`) and
  // `use-other-credentials.hooks.ts` queue their own credential writes through.
  const writes = useSerialWrites();

  // Guards `setStored` against an out-of-order read: the mount GET, the post-save refresh GET, and
  // each write's own response are all independent round trips with no ordering between them. A slow
  // mount GET that resolves after a save (or after the save's own refresh) must not overwrite the
  // fresher view those already installed — see F2 in plan-components.md (2026-09-20). Only `setStored`
  // is guarded; `setSaveState`/`setSettingsSaveState`, `clearLegacyLocalCredential`, `setLegacyKey`
  // and `publishSettingsRefresh` all belong to the button that called them and the write really did
  // happen, so none of those are stale just because a later call also started.
  const storedSettlement = useSettlementGeneration();

  // A write's own response is the freshest view of the row this mount has at the instant it lands,
  // so it mints its generation THEN — after the await, and only on success — superseding any read
  // still in flight, and installs unconditionally. Minting before the PUT instead let a FAILED
  // write (which learned nothing about the row) strand a slower read that was still coming back:
  // `stored` then stayed at its pre-load value until some unrelated refresh ran. Unlike
  // `useSerialWrites`' own "mint before `run`" rule, this generation orders RESPONSES by arrival,
  // not button presses by intent — nothing here is a "which click owns the UI" decision.
  function installWrittenView(view: TStored): void {
    storedSettlement.next();
    setStored(view);
  }

  // Hydrate the stored view, on mount AND whenever another mount (or `AssistantDock`'s own separate
  // copy) publishes a change to this same server row — see this file's "Cross-mount staleness" doc
  // above. Silent on failure, same posture `use-visitor-credential-form.hooks.ts` takes for its own
  // GET: a failed read must not put an error next to a key field the operator has not touched yet,
  // and the only visible consequence is that the "already stored" affordances stay at whatever they
  // last held until a refresh works.
  useEffect(() => {
    let cancelled = false;
    const refresh = () => {
      const generation = storedSettlement.next();
      port
        .loadAdminExecutionCredential({}, {})
        .then((view) => {
          if (!cancelled && storedSettlement.isCurrent({ generation })) setStored(view);
        })
        .catch(() => undefined);
    };
    refresh();
    // `scope` is `null` ("refresh everything") or the list of namespaces a publisher named — narrow
    // to this credential's own namespace so an unrelated slice's save does not trigger a pointless
    // refetch here, matching `useSettingsSlice`'s identical narrowing.
    const unsubscribe = effects.refreshPort.subscribe({ listener: (scope) => {
      if (scope && !scope.includes(effects.namespace)) return;
      refresh();
    } }, {});
    return () => {
      cancelled = true;
      unsubscribe();
    };
    // `port` is referentially stable in production (`useWiredAdminExecutionCredential` always passes
    // the same module-level singleton), so adding it changes nothing about when this effect re-runs —
    // it is here only because it is now a function-scoped value ESLint's exhaustive-deps rule can see,
    // where the old `loadAdminExecutionCredential` import was invisible to that rule.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port, effects]);

  // Offer the migration prompt only once the server's own state is known AND nothing is already
  // stored there — an admin who already has a server-side credential (migrated earlier, or just
  // saved fresh this session) gets no benefit from being asked to migrate a now-superseded local
  // value, and re-asking would read as the screen not noticing its own save.
  useEffect(() => {
    if (stored === null) return;
    setLegacyKey(stored.isSet ? null : effects.readLegacyCredential({}, {}));
  }, [stored, effects]);

  function saveKey(): Promise<void> {
    const apiKey = byok.apiKey.trim();
    // The BUTTON's rule, applied again here so a blank field cannot reach the server even through a
    // direct call. Deliberately NOT `hasUsableAdminKey`: a stored key makes the credential usable,
    // not the empty field writable. See `hasTypedAdminKey`'s own doc for the bug that distinction fixes.
    // OUTSIDE the write chain on purpose: a no-op call must never queue a link that would only hold
    // up the migrate/settings writes behind it for nothing.
    if (!effects.hasTypedKey({ apiKey }, {})) return Promise.resolve(); // nothing typed — there is no key to write
    // Set synchronously, at call time, so a press queued behind another write shows "Saving…"
    // immediately rather than sitting at "idle" until its turn on the chain arrives.
    setSaveState({ status: "saving" });
    return writes.run({ task: async () => {
      try {
        // The key ALONE. Every other field is `saveSettings`'s, and building the patch from one
        // literal (rather than spreading `byok` and deleting) is what makes that readable at a glance
        // — there is no branch here that could let another field through.
        const patch: ExecutionCredentialPatch = { apiKey };
        const view = await port.saveAdminExecutionCredential({ patch }, {});
        installWrittenView(view);
        setSaveState({ status: "saved" });
        // Tells every other mounted copy of this credential (the other settings screen, the dock) to
        // re-read — see this file's "Cross-mount staleness" doc above.
        effects.refreshPort.publish({ namespaces: [effects.namespace] }, {});
        // Clear the field once the key is safely stored — see this file's `onByokChange` doc. Reads
        // the LATEST input, not the `byok`/`onByokChange` this closure captured at button-press time
        // (S1 above), and only actually clears when the field still holds exactly the key that was
        // just saved — otherwise the operator has since typed something new, and clearing it would
        // discard that unsaved edit instead of the key this save actually persisted.
        const latestInput = inputRef.current;
        if (latestInput.byok.apiKey.trim() === apiKey) {
          latestInput.onByokChange({ ...latestInput.byok, apiKey: "" });
        }
      } catch (error) {
        setSaveState({ status: "error", message: effects.describeError({ error, fallback: "failed to save the key" }, {}) });
      }
    } });
  }

  function saveSettings(): Promise<void> {
    setSettingsSaveState({ status: "saving" });
    return writes.run({ task: async () => {
      try {
        // No `apiKey` key at all, under any condition — see this controller's `saveSettings` doc. The
        // field's contents are not consulted here, so there is no state of the form in which this
        // patch can grow one.
        const patch: ExecutionCredentialPatch = {
          protocol: byok.protocol,
          providerId: byok.providerId,
          baseUrl: byok.baseUrl,
          model: byok.model,
          ...(byok.maxTokens !== undefined ? { maxTokens: byok.maxTokens } : {}),
        };
        const view = await port.saveAdminExecutionCredential({ patch }, {});
        installWrittenView(view);
        setSettingsSaveState({ status: "saved" });
        effects.refreshPort.publish({ namespaces: [effects.namespace] }, {});
      } catch (error) {
        setSettingsSaveState({
          status: "error",
          message: effects.describeError({ error, fallback: "failed to save the settings" }, {}),
        });
      }
    } });
  }

  function migrateLegacyKey(): Promise<void> {
    if (!legacyKey) return Promise.resolve();
    setSaveState({ status: "saving" });
    return writes.run({ task: async () => {
      try {
        const patch: ExecutionCredentialPatch = {
          apiKey: legacyKey,
          protocol: byok.protocol,
          providerId: byok.providerId,
          baseUrl: byok.baseUrl,
          model: byok.model,
          ...(byok.maxTokens !== undefined ? { maxTokens: byok.maxTokens } : {}),
        };
        const view = await port.saveAdminExecutionCredential({ patch }, {});
        // Clear the local copy ONLY after the PUT above has actually resolved successfully — the
        // design's explicit ordering requirement (§6: "only after that PUT succeeds does the code
        // clear the localStorage entry"). A throw above skips every line from here down, so a failed
        // migration leaves both the local key AND `legacyKey` state untouched — the prompt stays up
        // and the admin can retry or decline.
        effects.clearLegacyCredential({}, {});
        installWrittenView(view);
        setLegacyKey(null);
        setSaveState({ status: "saved" });
        // Same cross-mount notification `saveKey` above sends — a migration is a write to the same row.
        effects.refreshPort.publish({ namespaces: [effects.namespace] }, {});
      } catch (error) {
        setSaveState({ status: "error", message: effects.describeError({ error, fallback: "failed to save the migrated key" }, {}) });
      }
    } });
  }

  function dismissLegacyPrompt(): void {
    setLegacyDismissed(true);
  }

  // All three read the form's CURRENT endpoint, so they follow a provider switch on the same render.
  const storedKeyIsForOtherEndpoint = effects.storedKeyIsForOtherEndpoint({ stored, baseUrl: byok.baseUrl }, {});
  const apiKeyPlaceholder = effects.credentialHint({ stored, storedKeyIsForOtherEndpoint }, { locale });
  return {
    stored,
    apiKeyStoredExternally: effects.hasUsableKey({ apiKey: byok.apiKey, stored, baseUrl: byok.baseUrl }, {}),
    apiKeyPlaceholder,
    storedKeyIsForOtherEndpoint,
    canDiscoverModels: !effects.storedKeyBlocksProbe({ apiKey: byok.apiKey, stored, baseUrl: byok.baseUrl }, {}),
    saveState,
    settingsSaveState,
    canSaveKey: effects.hasTypedKey({ apiKey: byok.apiKey }, {}),
    saveKey,
    saveSettings,
    legacyKey: legacyDismissed ? null : legacyKey,
    migrateLegacyKey,
    dismissLegacyPrompt,
  };
}

import { useEffect, useRef } from 'react';
import {
  FILE_DIALOG_FOCUS_DELAY_MS,
  FILE_DIALOG_STALE_MS,
  FILE_DIALOG_WARMUP_MS,
  FILE_DROPZONE_PROCESSING_MIN_VISIBLE_MS,
} from '../../constants.js';

export interface UseFileDialogTrackingResult {
  /** Call when the file input is clicked, before the OS dialog opens. A no-op if no `onProcessingStart` was supplied. */
  prepareTracking: () => void;
  /**
   * Call once the input's `change` event fires (a real selection). Clears
   * every timer and returns any in-flight "finish" callback (`undefined` if
   * no loading affordance was ever shown) — undelayed, so the caller
   * decides its own timing around the staging work that follows.
   */
  completeTracking: () => (() => void) | undefined;
  /** Call from the input's `cancel` event: completes tracking and, if a loading affordance was showing, schedules its finish after the minimum-visible delay so it doesn't flash. */
  handleDialogCancelled: () => void;
}

/**
 * The file-dialog cancel-vs-still-loading detection heuristic, ported from
 * `DesignSystemFlow.tsx`'s `DropZone`. A native `<input type=file>` click
 * opens an OS-level dialog with no DOM signal for "still open" — only
 * `window` regaining `focus` (the dialog closed, picked or not) and the
 * input's own `cancel` event (dismissed with no selection) are observable.
 * Two racing timers decide when a `focus` is trustworthy enough to start a
 * loading affordance: a short delay that ignores a spurious focus firing
 * immediately after the click, and a longer warmup that force-starts the
 * affordance if `focus` never arrives at all (some platforms never blur the
 * main window for a file dialog). A stale-timeout safety net force-clears a
 * loading affordance that's been open too long without the dialog
 * resolving (a hung or buggy picker).
 *
 * Deliberately generalized from the origin: there, this heuristic only ran
 * for the directory-browse zone (`directory && onProcessingStart`); here it
 * runs for any zone that supplies `onProcessingStart`, since the heuristic
 * itself has no directory-specific behavior — a large flat file selection
 * benefits from the same loading affordance a large folder selection does.
 */
export function useFileDialogTracking(onProcessingStart?: () => () => void): UseFileDialogTrackingResult {
  const pendingRef = useRef(false);
  const canShowLoadingRef = useRef(false);
  const loadingFinishRef = useRef<(() => void) | undefined>(undefined);
  const focusDelayRef = useRef<number | undefined>(undefined);
  const warmupRef = useRef<number | undefined>(undefined);
  const staleRef = useRef<number | undefined>(undefined);
  const onProcessingStartRef = useRef(onProcessingStart);
  onProcessingStartRef.current = onProcessingStart;

  function clearTimer(ref: { current: number | undefined }) {
    if (ref.current === undefined) return;
    window.clearTimeout(ref.current);
    ref.current = undefined;
  }

  function completeTracking(): (() => void) | undefined {
    clearTimer(focusDelayRef);
    clearTimer(warmupRef);
    clearTimer(staleRef);
    pendingRef.current = false;
    canShowLoadingRef.current = false;
    const finish = loadingFinishRef.current;
    loadingFinishRef.current = undefined;
    return finish;
  }

  function scheduleFinish(finish: (() => void) | undefined) {
    if (!finish) return;
    window.setTimeout(finish, FILE_DROPZONE_PROCESSING_MIN_VISIBLE_MS);
  }

  function handleDialogCancelled() {
    scheduleFinish(completeTracking());
  }

  function beginReturnLoading() {
    if (!pendingRef.current) return;
    if (!canShowLoadingRef.current) return;
    const start = onProcessingStartRef.current;
    if (!start) return;
    if (loadingFinishRef.current) return;
    loadingFinishRef.current = start();
    staleRef.current = window.setTimeout(() => {
      handleDialogCancelled();
    }, FILE_DIALOG_STALE_MS);
  }

  useEffect(() => {
    if (!onProcessingStart) return undefined;
    function handleFocus() {
      beginReturnLoading();
    }
    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
    // `beginReturnLoading` closes only over refs (stable identity semantics) — re-subscribing per render would just churn the listener for no behavioral change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [onProcessingStart]);

  // Clears any pending timers on unmount without invoking a stored `finish`
  // (calling into host state after unmount would be the host's problem, but
  // avoiding it entirely is strictly safer than the origin, which had no
  // unmount cleanup for these timers at all).
  useEffect(() => {
    return () => {
      clearTimer(focusDelayRef);
      clearTimer(warmupRef);
      clearTimer(staleRef);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  function prepareTracking() {
    if (!onProcessingStartRef.current) return;
    const previousFinish = completeTracking();
    previousFinish?.();
    pendingRef.current = true;
    canShowLoadingRef.current = false;
    focusDelayRef.current = window.setTimeout(() => {
      canShowLoadingRef.current = true;
      focusDelayRef.current = undefined;
    }, FILE_DIALOG_FOCUS_DELAY_MS);
    warmupRef.current = window.setTimeout(() => {
      canShowLoadingRef.current = true;
      warmupRef.current = undefined;
      beginReturnLoading();
    }, FILE_DIALOG_WARMUP_MS);
  }

  return { prepareTracking, completeTracking, handleDialogCancelled };
}

import { useEffect, useRef, type ChangeEvent, type DragEvent, type RefObject } from 'react';
import { useFileDropTarget } from '../../../../browser/useFileDropTarget.js';
import { filesFromClipboardData, shouldIgnoreClipboardFilePaste } from '../../../../utils/file-transfer.js';
import { FILE_DROPZONE_PROCESSING_BYTES_THRESHOLD, FILE_DROPZONE_PROCESSING_FILE_COUNT_THRESHOLD, FILE_DROPZONE_PROCESSING_MIN_VISIBLE_MS } from '../../constants.js';
import { fileDropzoneShouldShowProcessing } from '../../rules.js';
import { useFileDialogTracking } from './useFileDialogTracking.js';

export interface UseFileDropzoneParams {
  /** Resolved files ready to stage — always the fully directory-expanded flat list, whether they arrived via drag/drop, click-to-browse, or paste. */
  onFiles: (files: File[]) => void;
  /** Fires on a native click on the zone. Drag/drop and paste don't trigger it. */
  onZoneClick?: (() => void) | undefined;
  /** Surfaces a read error (e.g. a dropped folder failed to enumerate), or clears it (`null`) right before a successful staging. */
  onError?: ((message: string | null) => void) | undefined;
  /**
   * Wraps staging of a large selection (see `FILE_DROPZONE_PROCESSING_FILE_COUNT_THRESHOLD`
   * / `_BYTES_THRESHOLD`) so a host can show a loading affordance while it
   * resolves; returns the "finish" callback. Also drives the file-dialog
   * cancel-vs-still-loading detection heuristic for click-to-browse. Omit
   * for a zone that never needs a loading affordance (small selections
   * stage synchronously regardless).
   */
  onProcessingStart?: (() => () => void) | undefined;
  /** Listens for a page-wide clipboard paste (ignoring one that lands on a text-entry target) and stages any pasted files directly — bypasses the processing-affordance heuristic, matching the origin (a paste is never a directory, so it's never large enough to need one). */
  enablePaste?: boolean | undefined;
}

export interface UseFileDropzoneResult {
  inputRef: RefObject<HTMLInputElement | null>;
  dragOver: boolean;
  dropReadError: string | null;
  openPicker: () => void;
  onZoneDragEnter: (event: DragEvent<Element>) => void;
  onZoneDragOver: (event: DragEvent<Element>) => void;
  onZoneDragLeave: (event: DragEvent<Element>) => void;
  onZoneDrop: (event: DragEvent<Element>) => void;
  onInputChange: (event: ChangeEvent<HTMLInputElement>) => void;
  onInputClick: () => void;
}

function runAfterNextPaint(callback: () => void): void {
  if (typeof window.requestAnimationFrame === 'function') {
    window.requestAnimationFrame(() => window.setTimeout(callback, 0));
    return;
  }
  window.setTimeout(callback, 0);
}

/**
 * Consolidates the two independent OD file-staging zones'
 * behavior into one hook: native drag/drop (directory-aware, via
 * `browser/useFileDropTarget`), click-to-browse (with the file-dialog
 * cancel-vs-still-loading detection heuristic, via `useFileDialogTracking`),
 * an optional page-wide clipboard-paste listener, and the shared
 * large-selection loading-affordance heuristic that gates all of the above
 * except paste. See `packages/ui/archived provenance ledger` for the full consolidation
 * writeup and which origin file contributed which piece.
 */
export function useFileDropzone({
  onFiles,
  onZoneClick,
  onError,
  onProcessingStart,
  enablePaste = false,
}: UseFileDropzoneParams): UseFileDropzoneResult {
  const inputRef = useRef<HTMLInputElement | null>(null);
  const onFilesRef = useRef(onFiles);
  onFilesRef.current = onFiles;
  const onErrorRef = useRef(onError);
  onErrorRef.current = onError;

  const dialogTracking = useFileDialogTracking(onProcessingStart);
  const dialogTrackingRef = useRef(dialogTracking);
  dialogTrackingRef.current = dialogTracking;

  function finishProcessingLater(finish: (() => void) | undefined) {
    if (!finish) return;
    window.setTimeout(finish, FILE_DROPZONE_PROCESSING_MIN_VISIBLE_MS);
  }

  // Every caller (processSelectedFiles' two staging branches, and the paste
  // listener) already guards a non-empty selection before reaching here, so
  // this has no empty-array case to handle.
  function stageFiles(nextFiles: File[]) {
    onErrorRef.current?.(null);
    onFilesRef.current(nextFiles);
  }

  function processSelectedFiles(nextFiles: File[], activeFinish?: () => void) {
    if (nextFiles.length === 0) {
      finishProcessingLater(activeFinish);
      return;
    }
    if (!fileDropzoneShouldShowProcessing(nextFiles, FILE_DROPZONE_PROCESSING_FILE_COUNT_THRESHOLD, FILE_DROPZONE_PROCESSING_BYTES_THRESHOLD) || !onProcessingStart) {
      stageFiles(nextFiles);
      finishProcessingLater(activeFinish);
      return;
    }
    const finish = activeFinish ?? onProcessingStart();
    runAfterNextPaint(() => {
      try {
        stageFiles(nextFiles);
      } finally {
        finishProcessingLater(finish);
      }
    });
  }

  const dragTarget = useFileDropTarget((droppedFiles) => processSelectedFiles(droppedFiles));

  // Mirrors the drag-target's own read-error state into the `onError` prop
  // so a host that already has a single error-display slot (matching the
  // origin `DropZone`'s `onError` contract) doesn't need a second one just
  // for drops; `dragTarget.dropReadError` remains available directly too
  // for a host that prefers to render its own inline banner instead.
  useEffect(() => {
    if (dragTarget.dropReadError) onErrorRef.current?.(dragTarget.dropReadError);
  }, [dragTarget.dropReadError]);

  function openPicker() {
    inputRef.current?.click();
  }

  function onInputClick() {
    onZoneClick?.();
    dialogTrackingRef.current.prepareTracking();
  }

  function onInputChange(event: ChangeEvent<HTMLInputElement>) {
    const picked = Array.from(event.currentTarget.files ?? []);
    event.currentTarget.value = '';
    const finish = dialogTrackingRef.current.completeTracking();
    processSelectedFiles(picked, finish);
  }

  // The native `cancel` event on `<input type=file>` has no React synthetic
  // equivalent, so it's wired imperatively — mirroring the origin, which
  // only attaches this (and the window `focus` listener now owned by
  // `useFileDialogTracking`) while a processing affordance is configured.
  useEffect(() => {
    if (!onProcessingStart) return undefined;
    // Non-null: this effect runs post-mount, and the consumer always
    // renders the ref'd `<input>` unconditionally (see `FileDropzone.tsx`),
    // so `inputRef.current` is never null once an effect body executes.
    const input = inputRef.current!;
    function handleCancel() {
      dialogTrackingRef.current.handleDialogCancelled();
    }
    input.addEventListener('cancel', handleCancel);
    return () => input.removeEventListener('cancel', handleCancel);
  }, [onProcessingStart]);

  useEffect(() => {
    if (!enablePaste) return undefined;
    function onPaste(event: ClipboardEvent) {
      if (shouldIgnoreClipboardFilePaste(event.target) || shouldIgnoreClipboardFilePaste(document.activeElement)) {
        return;
      }
      const pasted = filesFromClipboardData(event.clipboardData);
      if (pasted.length === 0) return;
      event.preventDefault();
      stageFiles(pasted);
    }
    window.addEventListener('paste', onPaste);
    return () => window.removeEventListener('paste', onPaste);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [enablePaste]);

  return {
    inputRef,
    dragOver: dragTarget.draggingFiles,
    dropReadError: dragTarget.dropReadError,
    openPicker,
    onZoneDragEnter: dragTarget.onDragEnter,
    onZoneDragOver: dragTarget.onDragOver,
    onZoneDragLeave: dragTarget.onDragLeave,
    onZoneDrop: dragTarget.onDrop,
    onInputChange,
    onInputClick,
  };
}

import { useCallback, useEffect, useRef, useState } from 'react';
import grapesjs, { type Component, type Editor } from 'grapesjs';
import { applyCanvasContentWrapper } from '../../canvas-content-wrapper.js';
import { applyCanvasEmbedPlaceholders, type CanvasEmbedPlaceholderDescriptor } from '../../canvas-embed-placeholders.js';
import { buildCanvasStyleConfig, CANVAS_STYLES_PENDING_CLASS, type CanvasStyling } from '../../canvas-style.js';
import { serializeEditorSource, type DirtyTextEdit } from '../../editor-serialization.js';
import { prepareEditorSource, type PreparedEditorSource, type RequestEditHtml } from '../../editor-blocks.js';
import { assertPreparedSourceModel, assertProtectedSourceMetadata, EditorSourceError, PROTECTED_ELEMENT_TYPE, protectedCanvasDescriber, protectTextAncestors, registerProtectedElementType } from '../../protected-elements.js';
import { pathKey, type ElementPath } from '../../source-splice.js';

/**
 * @file `InteractiveHtmlEditor`'s GrapesJS lifecycle: construct the editor once per mount against
 * the container ref, wire content-change notifications out, and tear the editor down on unmount.
 * Split from the component the same reason `ConfirmDialog.hooks.tsx` is split from `ConfirmDialog.tsx`
 * in `@jini-ai/admin` — the imperative, non-React lifecycle (`grapesjs.init`/`editor.destroy`) stays
 * out of the render path, and a test can drive it independently of the markup.
 *
 * **Uncontrolled by design.** `html` (and `isProtectedElement`, and `canvasStyling`) are read once,
 * at construction — this hook does not react to later changes in any of them. GrapesJS owns an internal component tree
 * once initialized; feeding an external string back into a live editor on every parent re-render
 * (which is what a naive `useEffect([html])` would do, since this same hook's own `onChange` callback
 * pushes edits back up into whatever state produced the `html` prop) would either fight the operator's
 * cursor or require diffing GrapesJS's tree against a string to detect "did this change come from us",
 * which is real complexity this component's text-editing-only scope does not need. A host that needs a
 * fresh document only mounts this component while it's active and remounts with fresh `html` — see
 * `@jini-ai/admin/react`'s `InteractiveHtmlEditor` adapter and its caller in the host product's `PageEditor.tsx`.
 *
 * **This module has zero knowledge of host embed conventions.** The shared source detector owns
 * native/runtime blocks; the caller owns its embed predicate and descriptions. Both go through
 * `../../protected-elements.ts`'s single raw-source type and the existing canvas card renderer.
 *
 * **`canvasStyling.contentWrapper` is applied on `load`, against the live canvas — never folded into
 * `components` above.** See `../../canvas-content-wrapper.ts`'s own file header for why: GrapesJS's
 * exported HTML/CSS are built from its component model, which `components` seeds and this wrapper
 * never touches, so it cannot leak into a save no matter how the canvas is edited afterward.
 */

/** Bold/italic/link only. GrapesJS's other built-in RTE actions (underline, strikethrough, wrap) are
 *  omitted, not merely unconfigured, by naming exactly these three rather than leaving the default
 *  action list in place. */
const RTE_ACTIONS = ['bold', 'italic', 'link'];


function initInteractiveHtmlEditor(
  container: HTMLElement,
  sourcePlan: PreparedEditorSource,
  canvasStyling: CanvasStyling,
  options: InteractiveEditorOptions,
): Editor {
  return grapesjs.init({
    container,
    height: '100%',
    fromElement: false,
    components: sourcePlan.html,
    storageManager: { type: 'none' },
    panels: { defaults: [] },
    blockManager: { blocks: [] },
    richTextEditor: { actions: RTE_ACTIONS },
    // Both default to `true`: avoidInlineStyle moves styles into ID rules; forceClass converts
    // them to .cNNNN rules even with avoidInlineStyle disabled, including on untouched elements.
    // Keep authored styles inline for structural saves (Bug C in this repo's `pages-redo` plan).
    // serializeCleaned's JSON CSS export is the other half; the splice path already keeps bytes.
    avoidInlineStyle: false,
    forceClass: false,
    canvas: buildCanvasStyleConfig({ ...canvasStyling, css: [canvasStyling.css, sourcePlan.canvasCss].filter(Boolean).join('\n') }),
    // Structural export can only preserve whitespace gaps the parser retained in the model.
    parser: { optionsHtml: { allowScripts: false, keepEmptyTextNodes: true } },
    plugins: [(editor: Editor) => registerProtectedElementType({ editor, sourcePlan }, {
      onRequestEditHtml: options.onRequestEditHtml, editHtmlLabel: options.translate?.('Edit HTML'),
      beforeRequestEditHtml: () => disableActiveTextEditing(editor), onSerializationError: options.onSerializationError,
    })],
  });
}

/** Mirrors `source-splice.ts`'s own `UNINDEXED_TAGS` filter, but for GrapesJS's live component tree
 *  rather than a parsed HTML string: `textnode` and `comment` components never consume a path slot,
 *  matching how `indexElementSourceRanges` numbers the original string. Raw style/script atoms
 *  now stay in the tree, but their original source tag still excludes them from path slots; before
 *  source preservation GrapesJS moved styles into CssComposer and dropped scripts outright. */
function isPathableComponent(component: Component): boolean {
  return !component.is('textnode') && !component.is('comment')
    && !['style', 'script'].includes(component.get?.('sourceTagName') as string);
}

/**
 * `component`'s element-only child path from the editor's wrapper root, in the exact numbering
 * scheme `indexElementSourceRanges` uses for the original HTML string — so a path computed here can
 * be looked up directly against that index. Returns `null` only if `component` (or an ancestor)
 * cannot be found in its own parent's `components()` collection, which is not reachable for a live
 * component an actual GrapesJS event just handed this hook; kept as a defensive guard rather than
 * assumed away, the same convention `canvas-embed-placeholders.ts`'s own "Unreachable ... defensive
 * only" comment uses for its analogous case.
 *
 * @complexity O(d + s) — d = depth from the wrapper, s = total siblings visited across every
 * ancestor level. Editor documents in this product are shallow; not a hot path.
 */
function computeComponentPath(component: Component): ElementPath | null {
  const path: number[] = [];
  let current: Component = component;
  for (;;) {
    const parent = current.parent();
    if (!parent) return path;
    const siblings = parent.components().models;
    const at = siblings.indexOf(current);
    if (at === -1) return null; // Unreachable for a live component; defensive only.
    const elementIndex = siblings.slice(0, at).filter(isPathableComponent).length;
    path.unshift(elementIndex);
    current = parent;
  }
}

/**
 * Records (or overwrites) the latest inner HTML for the nearest `text` component whose content
 * changed, keyed by its element-only path. Silently ignores anything that is not a `text` component
 * — this is the mechanism that keeps a non-text element (a host's embed marker `<div>`, an image, a
 * plain container) from ever becoming a splice target, even if some other GrapesJS event happens to
 * name it as its argument — and anything whose path cannot be resolved from the live tree.
 */
function recordDirtyTextEdit(component: Component | undefined, dirty: Map<string, DirtyTextEdit>): void {
  if (!component || !component.is('text')) return;
  const path = computeComponentPath(component);
  if (!path) return;
  dirty.set(pathKey(path), { path, tagName: component.tagName.toLowerCase(), component });
}

/**
 * True when `component` sits inside a `text` component: the inline and textnode children GrapesJS's
 * `syncContent` removes and re-adds every time an RTE session closes. That churn is part of a text
 * edit, which the splice already covers, not a block edit. A just-removed component has no `parent()`
 * any more, so the walk starts from `prevColl.parent` (the collection it was removed from).
 *
 * @complexity O(d) in the component's depth.
 */
function isInsideTextComponent(component: Component): boolean {
  let current: Component | undefined = component.parent() ?? component.prevColl?.parent;
  while (current) {
    if (current.is('text')) return true;
    current = current.parent();
  }
  return false;
}

/**
 * Ends whatever RTE session is currently open, so its pending edit syncs into the component model
 * before `flush` reads it — GrapesJS only writes an RTE session's edited text into the model when
 * that session closes (`disableEditing`/`syncContent`), never on every keystroke, so a save or
 * unmount that skips this step silently loses the last, still-open edit. A throw from
 * `disableEditing` (e.g. GrapesJS internals mid-teardown) must never block `flush` from still
 * returning whatever was already recorded, so it is swallowed here rather than propagated.
 *
 * @complexity O(1) plus whatever the editor's own `disableEditing` costs.
 */
async function disableActiveTextEditing(editor: Editor): Promise<void> {
  const editing = editor.getEditing();
  if (!editing) return;
  try {
    await (editing.getView() as { disableEditing?: () => Promise<void> } | undefined)?.disableEditing?.();
  } catch {
    // Swallowed intentionally — see this function's doc.
  }
}

/** Hard cap on how long the canvas can stay hidden waiting for its theme stylesheet(s) (Bug B, Slice
 *  B1, this repo's `pages-redo` plan) — a dead URL or a hung dev-server reload must never hide the
 *  editor forever. */
const STYLESHEET_SETTLE_TIMEOUT_MS = 3000;

/**
 * Hides `body` behind {@link CANVAS_STYLES_PENDING_CLASS} until every `<link rel="stylesheet">`
 * GrapesJS's `canvas.styles` config put in the canvas document (`editor.Canvas.getDocument()`) has
 * fired `load` or `error`, or {@link STYLESHEET_SETTLE_TIMEOUT_MS} has elapsed — whichever comes first.
 * Every Interactive mount re-fetches the theme stylesheet (see this repo's `pages-redo` plan, Bug B)
 * with no guaranteed cache short-circuit; GrapesJS's own `FrameView` renders the canvas body without
 * waiting for `<link>`s in `<head>` to resolve, so without this the operator sees raw browser-default
 * styling (Times New Roman, blue links) for however long that fetch takes, or forever if the API is
 * mid-restart. The cap is unconditional, independent of how many stylesheets are still pending.
 *
 * Must be called from `handleLoad`, AFTER the content wrapper and embed placeholder decoration have
 * already run against the same `body` — so even the zero-stylesheet case (this function reveals in the
 * same synchronous call) never shows an undecorated canvas for even one frame.
 *
 * @returns A cleanup callback that cancels the pending timer and detaches any still-registered
 *   `load`/`error` listeners. Idempotent — safe to call again (from effect cleanup) after the canvas
 *   has already revealed; a no-op then.
 * @complexity O(n) in the number of `<link rel="stylesheet">` elements found — one listener pair per
 *   link, no polling.
 */
function revealCanvasWhenStylesheetsSettle(editor: Editor, body: HTMLElement, onSettled: () => void): () => void {
  body.classList.add(CANVAS_STYLES_PENDING_CLASS);

  const canvasDocument = editor.Canvas.getDocument();
  // `getDocument()` returning null is not reachable once `load` has fired on a real editor — defensive
  // only, same convention as this file's other "Unreachable ... defensive only" guards.
  const links = canvasDocument ? Array.from(canvasDocument.querySelectorAll('link[rel="stylesheet"]')) : [];

  let settled = false;
  let timeoutId: ReturnType<typeof setTimeout> | undefined;
  const pending = new Set<Element>();

  const reveal = () => {
    if (settled) return;
    settled = true;
    if (timeoutId !== undefined) clearTimeout(timeoutId);
    for (const link of pending) {
      link.removeEventListener('load', handleSettle);
      link.removeEventListener('error', handleSettle);
    }
    pending.clear();
    if (links.length > 0) onSettled();
    body.classList.remove(CANVAS_STYLES_PENDING_CLASS);
  };

  function handleSettle(event: Event): void {
    pending.delete(event.currentTarget as Element);
    if (pending.size === 0) reveal();
  }

  for (const link of links) {
    pending.add(link);
    link.addEventListener('load', handleSettle);
    link.addEventListener('error', handleSettle);
  }

  if (pending.size === 0) reveal();
  else timeoutId = setTimeout(reveal, STYLESHEET_SETTLE_TIMEOUT_MS);

  return reveal;
}

/**
 * Owns one GrapesJS `Editor` instance for the lifetime of the calling component's mount. `onChange`
 * fires with the editor's current serialized content (see `serializeWithSplice`) on every content
 * mutation (GrapesJS's `update` event — components, styles, or attributes changing); it is not
 * debounced, so a caller replacing an existing uncontrolled `<textarea>` (which already pushes a full
 * value on every keystroke) sees matching behavior.
 *
 * **Mounts into a dedicated child node, not the wrapper div `containerRef` itself, and removes that
 * child node (not just its content) on cleanup.** Defensive, for React StrictMode's dev-time
 * double-invoke (mount -> cleanup -> mount again, synchronously): if a destroyed instance's canvas
 * were still mid-render when cleanup ran, clearing the container's *current* content at that moment
 * cannot remove DOM that does not exist yet, and a later async write from the discarded instance
 * would land after the fact. Detaching the whole per-instance node sidesteps that class of ordering
 * problem entirely — whatever a destroyed instance's async work later does, it mutates a node no
 * longer connected to `document`, so it can never become visible or queryable in the live page no
 * matter when it runs. (Investigated live via Playwright while chasing an unrelated symptom — two
 * canvas iframes coexisting after one mount — which turned out to be a separate, harmless GrapesJS
 * quirk unrelated to StrictMode: `Canvas`'s `FramesView` always constructs one `FrameView` that never
 * proceeds past construction to `render()`, alongside the real one; it keeps Backbone's default
 * `class="frame"` forever, inert and unrendered. `.gjs-frame` — the class `FrameView.render()`
 * assigns — is what callers should select on, never a bare `iframe` under the wrapper.)
 *
 * **`flush()` exists because GrapesJS's RTE only syncs on `disableEditing`, and `update` is
 * double-debounced and never fires after `off()`.** A host that calls `onChange` on every keystroke
 * (like an uncontrolled `<textarea>`) still misses the operator's last edit if they click Save or
 * navigate away while an RTE session is still open: GrapesJS writes that session's text into the
 * component model only when it closes, and by the time a host's save handler runs, this hook has
 * already stopped listening (or the debounce hasn't fired yet). `flush` closes any open RTE session,
 * computes and emits the current content the same way `handleUpdate` does, and hands the result back
 * directly — see its own doc below for exactly what it returns and when.
 *
 * @complexity O(1) setup/teardown. Steady-state cost is GrapesJS's own serialization per edit,
 * proportional to document size — not something this hook controls or should hide a note about
 * beyond that.
 * @overallScore 100
 */
export interface InteractiveEditorOptions {
  onRequestEditHtml?: RequestEditHtml | undefined;
  translate?: ((key: string) => string) | undefined;
  onSerializationError?: ((error: EditorSourceError) => void) | undefined;
}

export function useInteractiveHtmlEditor(
  html: string,
  onChange: (html: string) => void,
  isProtectedElement?: (el: Element) => boolean,
  canvasStyling: CanvasStyling = {},
  describeEmbedPlaceholder?: (el: Element) => CanvasEmbedPlaceholderDescriptor | undefined,
  options: InteractiveEditorOptions = {},
) {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const [sourceError, setSourceError] = useState<string>();
  const onChangeRef = useRef(onChange);
  onChangeRef.current = onChange;
  // Delegated to by the stable `flush` callback returned below. Reset to a no-op on cleanup, before
  // `destroy()` — see the effect's cleanup for why the order matters.
  const flushRef = useRef<() => Promise<string | undefined>>(async () => undefined);

  useEffect(() => {
    const wrapper = wrapperRef.current;
    if (!wrapper) return undefined;
    const sourcePlan = prepareEditorSource({ html }, { isProtectedElement, describeHostElement: describeEmbedPlaceholder, translate: options.translate });
    let integrityFailure: EditorSourceError | undefined;
    const reportSourceError = (error: EditorSourceError) => {
      integrityFailure = error;
      setSourceError(options.translate?.(error.message) ?? error.message);
      options.onSerializationError?.(error);
    };
    if (!sourcePlan.ok) {
      reportSourceError(new EditorSourceError({ message: sourcePlan.problem }, {}));
      return undefined;
    }
    const mountEl = document.createElement('div');
    mountEl.style.height = '100%';
    wrapper.appendChild(mountEl);
    let editor: Editor;
    try { editor = initInteractiveHtmlEditor(mountEl, sourcePlan, canvasStyling, { ...options, onSerializationError: reportSourceError }); }
    catch { reportSourceError(new EditorSourceError()); mountEl.remove(); return undefined; }
    const decorate = () => {
      protectTextAncestors({ editor }, {});
      const describe = sourcePlan.instances.length ? protectedCanvasDescriber({ editor }, {}) : describeEmbedPlaceholder;
      if (describe) applyCanvasEmbedPlaceholders(editor.Canvas.getBody(), describe);
    };
    const serialize = () => {
      try {
        // No separate marker-leak check here: `serializeEditorSource` already throws an
        // `EditorSourceError` when its result carries `sourcePlan.markerAttribute`, so a second
        // identical check on the same result could never fire.
        return serializeEditorSource({ editor, html, edits: dirty, sourcePlan }, { structuralChange });
      } catch (error) {
        const failure = error instanceof EditorSourceError ? error : new EditorSourceError();
        reportSourceError(failure);
        throw failure;
      }
    };

    // Splice bookkeeping — see `serializeWithSplice`'s own doc for how these two are used. Plain
    // closure state scoped to this one mount-only effect run (like `editor`/`mountEl` above), not
    // `useRef`: nothing outside this effect ever reads them.
    const dirty = new Map<string, DirtyTextEdit>();
    let structuralChange: string | undefined;
    // True once `update` has fired at least once this mount — see `flush`'s "nothing to flush" guard
    // below for why this is tracked separately from `dirty`/`structuralChange` (a style/attribute-only
    // edit fires `update` with neither of those set, and still must not be silently dropped).
    let changed = false;
    // Set inside `handleLoad`, once the canvas body exists — see `revealCanvasWhenStylesheetsSettle`.
    // `undefined` until then (or if `load` never fires before unmount), so cleanup below guards it.
    let cancelStylesheetWait: (() => void) | undefined;
    let canvasWindow: Window | null | undefined;
    // Embed placeholder cards live only in the canvas DOM, so a structural edit (delete, move, clone,
    // undo) can leave one stale. Repaired on the tick after the edit, once GrapesJS has rendered it;
    // see `applyCanvasEmbedPlaceholders`. Only after `load`: before it, adds are the initial parse.
    let loaded = false;
    let cardRepair: ReturnType<typeof setTimeout> | undefined;
    const scheduleCardRepair = () => {
      if (!loaded || cardRepair !== undefined) return;
      cardRepair = setTimeout(() => {
        cardRepair = undefined;
        decorate();
      }, 0);
    };

    const handleUpdate = () => {
      changed = true;
      try { onChangeRef.current(serialize()); } catch { /* Source error is already visible; retain the last intact working copy. */ }
    };
    // `component:update:content` fires with the changed component itself as its argument (GrapesJS's
    // general `component:update:{propertyName}` pattern); `rte:disable` fires with `(view, rte)` —
    // the view whose RTE session just closed, `view.model` being the component it edited. Both name
    // the SAME kind of thing (a text component whose content just changed) through two different
    // GrapesJS code paths (a direct model update vs. the RTE toolbar's close), so both feed the one
    // `recordDirtyTextEdit` sink rather than each growing their own tracking.
    const handleContentUpdate = (component: Component) => recordDirtyTextEdit(component, dirty);
    const handleRteDisable = (view: { model?: Component }) => recordDirtyTextEdit(view?.model, dirty);
    // A block move, copy or delete (the Interactive tab keeps all three, owner decision 2026-09-23)
    // fires `component:add`/`component:remove` on the live tree. Once one fires outside a text
    // component, `serializeWithSplice` stops trusting any offset computed against the original string
    // for the rest of this mount; see its own doc for why this never resets.
    const handleStructuralChange = (event: 'component:add' | 'component:remove') => (component?: Component) => {
      scheduleCardRepair();
      if (structuralChange || (component && !component.is(PROTECTED_ELEMENT_TYPE) && isInsideTextComponent(component))) return;
      structuralChange = `${event} <${component?.tagName?.toLowerCase() || 'unknown'}>`;
    };
    const handleAdd = handleStructuralChange('component:add');
    const handleRemove = handleStructuralChange('component:remove');
    editor.on('update', handleUpdate);
    editor.on('component:update:content', handleContentUpdate);
    editor.on('rte:disable', handleRteDisable);
    editor.on('component:add', handleAdd);
    editor.on('component:remove', handleRemove);

    // See `flush`'s own doc for why this exists. Closes any open RTE session first (so its pending
    // edit syncs into the model), then emits and returns the current content the same way
    // `handleUpdate` does — except when nothing has changed since mount, matching `serializeWithSplice`'s
    // own "nothing to flush" case: no `update` was ever seen, no text edit was recorded, and no
    // structural change happened either.
    flushRef.current = async () => {
      await disableActiveTextEditing(editor);
      if (integrityFailure) throw integrityFailure;
      try { assertProtectedSourceMetadata({ editor }, {}); }
      catch { const failure = new EditorSourceError(); reportSourceError(failure); throw failure; }
      if (!changed && dirty.size === 0 && !structuralChange) return undefined;
      const next = serialize();
      onChangeRef.current(next);
      return next;
    };

    // `load` fires once the canvas's initial component render is done (`editor.Canvas.getBody()` is
    // populated) — see `applyCanvasContentWrapper`'s own file header for why the wrap has to happen
    // here, against the live canvas, rather than folded into `components` above. Embed placeholders
    // piggyback on this SAME handler/event rather than a second `editor.on('load', ...)` registration
    // — see `applyCanvasEmbedPlaceholders`'s own file header for its matching export-safety argument.
    // Applied AFTER the content wrapper so a placeholder can sit correctly however deep the wrapper
    // chain nests its marker, though nothing about either function actually depends on this order.
    const handleLoad = () => {
      if (sourcePlan.instances.length) {
        try { assertPreparedSourceModel({ editor, sourcePlan }, {}); }
        catch { reportSourceError(new EditorSourceError()); return; }
      }
      const body = editor.Canvas.getBody();
      applyCanvasContentWrapper(body, canvasStyling.contentWrapper);
      decorate();
      // Runs LAST, after both decorations above — see `revealCanvasWhenStylesheetsSettle`'s own doc
      // for why that order matters even in the zero-stylesheet case.
      cancelStylesheetWait = revealCanvasWhenStylesheetsSettle(editor, body, decorate);
      loaded = true;
      // An iframe window's native resize event already covers canvas-width changes. Reuse it
      // instead of maintaining a second ResizeObserver lifecycle for the same view geometry.
      canvasWindow = editor.Canvas.getDocument()?.defaultView;
      canvasWindow?.addEventListener('resize', scheduleCardRepair);
    };
    editor.on('load', handleLoad);
    return () => {
      // FIRST, before `destroy()` — a `flush()` call racing (or arriving after) unmount must resolve
      // `undefined` without ever touching the about-to-be-destroyed `editor`.
      flushRef.current = async () => undefined;
      editor.off('update', handleUpdate);
      editor.off('component:update:content', handleContentUpdate);
      editor.off('rte:disable', handleRteDisable);
      editor.off('component:add', handleAdd);
      editor.off('component:remove', handleRemove);
      editor.off('load', handleLoad);
      cancelStylesheetWait?.();
      canvasWindow?.removeEventListener('resize', scheduleCardRepair);
      clearTimeout(cardRepair);
      editor.destroy();
      mountEl.remove();
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps -- intentionally mount-only, see file header
  }, []);

  // Stable across renders (the effect above mutates `flushRef.current`, not this callback's identity)
  // so a caller can safely pass `flush` into a `useCallback`/`useImperativeHandle` dependency array.
  const flush = useCallback(() => flushRef.current(), []);

  return { containerRef: wrapperRef, flush, sourceError };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { createFakeMcpIntegrationsPort } from '../../dependencies.js';
import type { McpIntegrationsPort } from '../../ports.js';

export interface CodexInstallToggleController {
  /** `null` while the initial status fetch is in flight; `false` once
   *  resolved with no port support or the fetch failed. */
  available: boolean | null;
  installed: boolean;
  busy: boolean;
  error: string | null;
  /**
   * Set once, right after a successful install/uninstall — origin:
   * `CodexInstallToggle`'s `message` state (`{ kind: 'success', text:
   * t('settings.mcpCodex{Install,Uninstall}Success') }`), shown next to the
   * button until the next toggle. Cleared at the start of every `toggle()`
   * call, same as `error`.
   */
  successKind: 'installed' | 'uninstalled' | null;
  toggle: () => void;
}

/**
 * One-click Codex MCP install/uninstall: queries whether the host's daemon
 * exposes Codex install support at all (`available`), and if so, whether
 * this server is currently registered (`installed`). Origin:
 * `CodexInstallToggle` in `SettingsDialog.tsx` — the daemon-transport calls
 * (`fetch('/api/mcp/install/codex...')`) are now routed through the
 * injected `McpIntegrationsPort`'s optional Codex methods.
 */
export function useCodexInstallToggle(
  port: Pick<McpIntegrationsPort, 'fetchCodexInstallStatus' | 'installCodexMcp' | 'uninstallCodexMcp'>,
): CodexInstallToggleController {
  const [available, setAvailable] = useState<boolean | null>(null);
  const [installed, setInstalled] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [successKind, setSuccessKind] = useState<'installed' | 'uninstalled' | null>(null);

  const refresh = useCallback(async () => {
    if (!port.fetchCodexInstallStatus) {
      setAvailable(false);
      setInstalled(false);
      return;
    }
    try {
      const status = await port.fetchCodexInstallStatus();
      setAvailable(status.available);
      setInstalled(status.installed);
    } catch {
      // Daemon unreachable or endpoint missing — hide the toggle entirely
      // rather than surface a permanent error for an optional feature.
      setAvailable(false);
      setInstalled(false);
    }
    // `port` is host-supplied once; re-creating this callback per render
    // would refetch on every parent re-render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const toggle = useCallback(() => {
    void (async () => {
      setBusy(true);
      setError(null);
      setSuccessKind(null);
      const wasInstalled = installed;
      try {
        if (wasInstalled) {
          await port.uninstallCodexMcp?.();
        } else {
          await port.installCodexMcp?.();
        }
        await refresh();
        setSuccessKind(wasInstalled ? 'uninstalled' : 'installed');
      } catch (err) {
        setError(err instanceof Error ? err.message : String(err));
      } finally {
        setBusy(false);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [installed, refresh]);

  return { available, installed, busy, error, successKind, toggle };
}

/**
 * Zero-arg wirer: `useCodexInstallToggle` bound to this feature's own
 * `dependencies.ts` concrete port. Per this repo's `useX`/`useWiredX`
 * convention, this is the only export in this file allowed to import
 * `dependencies.ts` — a host with its own daemon should call
 * `useCodexInstallToggle` directly with its own `McpIntegrationsPort`
 * instead. Since this feature ships no real transport (see `ports.ts`), the
 * "concrete" port wired here is the same in-memory fake `useWiredMcpInstallInfo`
 * wires in.
 */
export function useWiredCodexInstallToggle(): CodexInstallToggleController {
  const port = useMemo(() => createFakeMcpIntegrationsPort(), []);
  return useCodexInstallToggle(port);
}

import { useEffect, useMemo, useState } from 'react';
import { createFakeMcpIntegrationsPort } from '../../dependencies.js';
import type { McpIntegrationsPort } from '../../ports.js';
import type { McpInstallInfo } from '../../types.js';

export interface McpInstallInfoController {
  info: McpInstallInfo | null;
  error: string | null;
  loading: boolean;
}

/**
 * Fetches `McpInstallInfo` once on mount via the injected port. Errors
 * surface as a plain message string (not thrown) so the tab can render a
 * clear inline error instead of a half-built snippet that would silently
 * fail when pasted.
 */
export function useMcpInstallInfo(port: Pick<McpIntegrationsPort, 'fetchInstallInfo'>): McpInstallInfoController {
  const [info, setInfo] = useState<McpInstallInfo | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    port
      .fetchInstallInfo()
      .then((data) => {
        if (cancelled) return;
        setInfo(data);
        setError(null);
      })
      .catch((err: unknown) => {
        if (cancelled) return;
        setError(err instanceof Error ? err.message : String(err));
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
    // `port` is expected to be a stable dependency (host-supplied once);
    // re-running on every render would refetch on every parent re-render.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return { info, error, loading };
}

/**
 * Zero-arg wirer: `useMcpInstallInfo` bound to this feature's own
 * `dependencies.ts` concrete port. Per this repo's `useX`/`useWiredX`
 * convention, this is the only export in this file allowed to import
 * `dependencies.ts` — a host with its own daemon should call `useMcpInstallInfo`
 * directly with its own `McpIntegrationsPort` instead. Since this feature
 * ships no real transport (the origin's `/api/mcp/install-info` endpoint is
 * genuinely host-specific — see `ports.ts`), the "concrete" port wired here
 * is the in-memory fake also used for this package's own tests/demos.
 */
export function useWiredMcpInstallInfo(): McpInstallInfoController {
  const port = useMemo(() => createFakeMcpIntegrationsPort(), []);
  return useMcpInstallInfo(port);
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { MediaProviderCatalogPolicy, MediaProvidersPort } from '../../ports.js';
import {
  hasAnyConfiguredProvider,
  isEntryEmpty,
  mergeDaemonProviders,
  shouldSyncLocalProvidersToDaemon,
} from '../../rules.js';
import type {
  MediaProviderCredentials,
  MediaProviderMap,
  MediaProvidersLoadState,
  MediaProvidersSaveState,
} from '../../types.js';

/** The operator-editable fields of a provider entry. Server markers
 *  (`apiKeyConfigured`/`apiKeyTail`) are deliberately excluded — they only
 *  ever arrive FROM the daemon, never typed by the operator; see
 *  `MediaProviderCredentials`'s own doc comment for the recoverable-vs-marker
 *  distinction this narrows around. */
export type MediaProviderEditPatch = Pick<MediaProviderCredentials, 'apiKey' | 'baseUrl' | 'model'>;

export interface UseMediaProvidersTabOptions {
  port: MediaProvidersPort;
  /** Identity rules shared by catalog rows, local edits and daemon responses. Stable while mounted. */
  catalogPolicy: MediaProviderCatalogPolicy;
  /** Host-persisted local edits from before this tab mounted (e.g. the
   *  host's own locally-cached config, read before the daemon round-trip
   *  completes). Defaults to none. Threaded into the initial
   *  daemon-reconciliation merge unchanged, so a first-run migration
   *  (`shouldSyncLocalProvidersToDaemon`) has real local data to detect. */
  initialProviders?: MediaProviderMap | undefined;
}

export interface UseMediaProvidersTabResult {
  /** The full working set: local edits layered over whatever the daemon last
   *  reported. Reflects `initialProviders` until the first load settles. */
  providers: MediaProviderMap;
  load: MediaProvidersLoadState;
  save: MediaProvidersSaveState;
  hasAnyConfigured: boolean;
  /** Provider ids with an edit not yet flushed to the daemon. A `reload()`
   *  preserves exactly these over whatever the server reports for them — see
   *  `mergeDaemonProviders`'s `preserveLocalProviderIds`. */
  pendingProviderIds: ReadonlySet<string>;
  updateProvider: (providerId: string, patch: MediaProviderEditPatch) => void;
  /** Drops the provider entirely (recoverable fields AND server markers) and
   *  immediately persists the removal. Clear is treated as a decisive action
   *  — same as the origin's confirm-then-clear flow — not a pending edit an
   *  operator might still back out of via `reload()`. */
  clearProvider: (providerId: string) => void;
  /** Flushes every current provider to the daemon. */
  saveChanges: () => void;
  /** Re-reads the daemon's copy and reconciles it against local state. */
  reload: () => void;
}

/**
 * Releases the tombstones a successful write carried. The server has now accepted a map without
 * these, so the local absence is no longer a claim waiting to be defended — the daemon agrees.
 * Re-touched ids keep their tombstone: the operator changed their mind mid-flight and this
 * response does not describe that decision.
 */
function releaseAcknowledgedClears({
  cleared,
  clearsInFlight,
  touched,
}: {
  cleared: Set<string>;
  clearsInFlight: readonly string[];
  touched: ReadonlySet<string>;
}): void {
  for (const providerId of clearsInFlight) {
    if (!touched.has(providerId)) cleared.delete(providerId);
  }
}

/** The server's saved map with every provider touched during the flight reset to local truth —
 *  including local deletion (see `flushNow`'s doc comment). Mutates and returns `saved`. */
function overlayTouchedProviders({
  saved,
  local,
  touched,
}: {
  saved: MediaProviderMap;
  local: MediaProviderMap;
  touched: ReadonlySet<string>;
}): MediaProviderMap {
  for (const providerId of touched) {
    const entry = local[providerId];
    if (entry === undefined) delete saved[providerId];
    else saved[providerId] = entry;
  }
  return saved;
}

/** A save rejection as display text; a non-`Error` rejection is stringified rather than read as `.message`. */
function saveErrorMessage({ error }: { error: unknown }): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Owns the tab's async edges: the initial daemon fetch (plus the one-time
 * first-upload migration `shouldSyncLocalProvidersToDaemon` guards), manual
 * reload, per-field edits, clear, and save. Origin: `MediaProvidersSection`'s
 * own `useState`/`useEffect` block in `SettingsDialog.tsx`, split from the
 * App.tsx-level boot migration it used to depend on — ported as a
 * self-contained hook (matches `useProjectLocationsTab`'s convention) so this
 * tab does not need a host-level daemon-config bootstrap to behave correctly.
 *
 * The `null` vs `{}` distinction `mergeDaemonProviders` turns on is preserved
 * end-to-end here: a `null` fetch result renders as `'unreachable'` and never
 * reaches `mergeDaemonProviders` at all (local state is left exactly as it
 * was), while a reached-but-empty `{}` result merges normally and can drop
 * stale local markers. Collapsing the two — e.g. defaulting a `null` result to
 * `{}` before merging — would make a transient daemon blip read as "the
 * server manages nothing" and silently wipe local edits.
 */
export function useMediaProvidersTab({ port, catalogPolicy, initialProviders }: UseMediaProvidersTabOptions): UseMediaProvidersTabResult {
  const { normalizeMediaProviderMap, canonicalMediaProviderId } = catalogPolicy;
  const [providers, setProviders] = useState<MediaProviderMap>(() => normalizeMediaProviderMap({ providers: initialProviders ?? {} }));
  const [pendingProviderIds, setPendingProviderIds] = useState<ReadonlySet<string>>(() => new Set());
  const [load, setLoad] = useState<MediaProvidersLoadState>({ status: 'loading' });
  const [save, setSave] = useState<MediaProvidersSaveState>({ status: 'idle' });

  /** Volatile values async callbacks need at RUN time, not at schedule time —
   *  same convention as `useProjectLocationsTab`'s refs. */
  const portRef = useRef(port);
  portRef.current = port;

  /**
   * The working set, mirrored into refs that update SYNCHRONOUSLY with each
   * mutation rather than at the next render.
   *
   * These are not a render-time convenience here, they are the send-time
   * source of truth: a queued whole-map write builds its payload from
   * `providersRef.current` at the moment it reaches the port (see `flushNow`).
   * Assigning them during render instead would leave a write that is issued in
   * the same tick as an edit sending the map from BEFORE that edit. Every
   * mutation therefore goes through `applyProviders`/`applyPending` — nothing
   * in this hook may call `setProviders`/`setPendingProviderIds` directly.
   */
  const providersRef = useRef(providers);
  const pendingRef = useRef(pendingProviderIds);

  const applyProviders = useCallback((next: MediaProviderMap) => {
    providersRef.current = next;
    setProviders(next);
  }, []);

  const applyPending = useCallback((next: ReadonlySet<string>) => {
    pendingRef.current = next;
    setPendingProviderIds(next);
  }, []);

  /**
   * Provider ids mutated locally since the in-flight write took its payload.
   * Reset at send time by `flushNow`, which then treats exactly these ids as
   * "the server's answer does not describe this one" — see its doc comment.
   */
  const mutatedSinceSend = useRef<Set<string>>(new Set());

  /**
   * Providers cleared locally whose removal the daemon has not confirmed yet.
   *
   * `mutatedSinceSend` protects a clear from the SAVE response. Nothing protected it from the LOAD
   * response, and the two need different mechanisms: a clear is deliberately not a pending edit
   * (see `clearProvider`), so it is absent from `preserveLocalProviderIds`, and `mergeDaemonProviders`
   * cannot preserve an entry that no longer exists locally anyway. The daemon still holds the
   * credential until the write lands, so any reload in that window re-created it from the server's
   * copy and put a cleared credential back on screen. These ids are tombstones: the merge drops
   * them outright, and they are released only when a write that carried the deletion succeeds, or
   * when the clear is rolled back.
   */
  const clearedProviderIds = useRef<Set<string>>(new Set());

  const alive = useRef(true);
  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  /** One monotonic ticket for the load edge: a manual `reload()` can be
   *  triggered again before a previous fetch settles, and responses are not
   *  guaranteed to land in send order — only the newest ticket may write
   *  state (same guard as `useExecutionTab`'s detection ticket). */
  const loadTicket = useRef(0);

  /**
   * `'abandoned'` is deliberately distinct from `'failed'`, not folded into it.
   * `clearProvider` rolls its optimistic delete back when a save does not
   * succeed — but a write whose component unmounted mid-flight has no state
   * left to roll back, and treating it as a failure would touch a dead tree.
   * An abandoned write must produce no state change at all.
   */
  type PersistOutcome =
    | { readonly status: 'saved' }
    | { readonly status: 'failed' }
    | { readonly status: 'abandoned' };

  /**
   * Issues ONE whole-map write and reconciles the server's answer.
   *
   * The payload is read from `providersRef` HERE, not passed in by the caller,
   * because this function may run long after the caller asked for it (see
   * `persist`'s serialization). Building it at send time is what makes waiting
   * safe: a queued write always carries the live working set, never the
   * snapshot that was current when it was requested.
   *
   * On success the server's copy is authoritative for everything this request
   * sent — but NOT for a provider the operator touched while it was in flight.
   * That entry was never in `sent`, so taking the server's value for it would
   * eat the edit, and for a clear would put the credential back on screen. Those
   * ids (`mutatedSinceSend`) keep local truth, including local deletion.
   */
  const flushNow = useCallback(async (): Promise<PersistOutcome> => {
    const sent = providersRef.current;
    mutatedSinceSend.current = new Set();
    // Snapshotted with the payload: exactly the tombstones this write is carrying to the daemon.
    // A clear issued while it is in flight is NOT in here and keeps its tombstone, because this
    // request never told the server about it.
    const clearsInFlight = [...clearedProviderIds.current].filter((providerId) => sent[providerId] === undefined);
    try {
      const saved = await portRef.current.saveMediaProviders(sent);
      if (!alive.current) return { status: 'abandoned' };
      const touched = mutatedSinceSend.current;
      releaseAcknowledgedClears({ cleared: clearedProviderIds.current, clearsInFlight, touched });
      applyProviders(
        overlayTouchedProviders({ saved: normalizeMediaProviderMap({ providers: saved }), local: providersRef.current, touched }),
      );
      // Everything this write sent is now persisted; only edits made during
      // the flight are still unflushed.
      applyPending(new Set([...pendingRef.current].filter((providerId) => touched.has(providerId))));
      setSave({ status: 'saved' });
      return { status: 'saved' };
    } catch (error: unknown) {
      if (!alive.current) return { status: 'abandoned' };
      setSave({ status: 'save-error', message: saveErrorMessage({ error }) });
      return { status: 'failed' };
    }
  }, [applyProviders, applyPending, normalizeMediaProviderMap]);

  /** True while a write is at the port. */
  const writing = useRef(false);
  /** The single coalesced follow-up write requested during that one. */
  const queued = useRef<{ readonly promise: Promise<PersistOutcome>; readonly settle: (outcome: PersistOutcome) => void } | null>(null);

  /**
   * The whole-map contract makes concurrent writes unorderable, so this hook
   * issues at most ONE at a time.
   *
   * `saveMediaProviders` replaces the ENTIRE map and carries no
   * expected-revision (`ports.ts`), so when two writes overlap the daemon keeps
   * whichever it happens to handle LAST — not whichever the operator issued
   * last. A response-side ticket cannot fix that: it only decides which
   * RESPONSE may write UI state, while the losing REQUEST has already rewritten
   * the server. Save-then-Clear could therefore show a cleared credential,
   * report success, and leave the credential intact on the daemon.
   *
   * Serializing removes the precondition instead of guarding the symptom — with
   * one write in flight, request order IS commit order. A second request
   * arriving while one is already queued coalesces into it rather than adding a
   * third round trip, because both would send the same send-time map anyway.
   */
  const persist = useCallback((): Promise<PersistOutcome> => {
    setSave({ status: 'saving' });

    if (writing.current) {
      if (queued.current === null) {
        let settle!: (outcome: PersistOutcome) => void;
        const promise = new Promise<PersistOutcome>((resolve) => {
          settle = resolve;
        });
        queued.current = { promise, settle };
      }
      return queued.current.promise;
    }

    writing.current = true;
    return (async () => {
      try {
        let outcome = await flushNow();
        while (queued.current !== null) {
          const waiter = queued.current;
          queued.current = null;
          outcome = await flushNow();
          waiter.settle(outcome);
        }
        return outcome;
      } finally {
        writing.current = false;
      }
    })();
  }, [flushNow]);

  const fetchAndReconcile = useCallback(
    (migrateOnFirstUpload: boolean) => {
      loadTicket.current += 1;
      const ticket = loadTicket.current;
      const isCurrent = () => alive.current && loadTicket.current === ticket;
      // Captured for the MIGRATION decision only — `shouldSyncLocalProvidersToDaemon` asks "did the
      // operator already have local data before this fetch answered", which is a question about the
      // pre-fetch state by definition. The MERGE deliberately does not use it: merging a response
      // against a snapshot taken before the request was sent discards every edit made while it was
      // in flight, which is the load-path twin of the whole-map overwrite `persist` serializes to
      // avoid. The merge reads `providersRef.current` at response time instead.
      const localBeforeMerge = providersRef.current;
      setLoad({ status: 'loading' });
      portRef.current.fetchMediaProviders().then((daemonResult) => {
        if (!isCurrent()) return;
        if (daemonResult == null) {
          // Unreachable is a value, not a failure (see this port's doc) —
          // local state is left exactly as it was, never defaulted to {}.
          setLoad({ status: 'unreachable' });
          return;
        }
        const merged = mergeDaemonProviders(providersRef.current, normalizeMediaProviderMap({ providers: daemonResult }), {
          preserveLocalProviderIds: pendingRef.current,
          dropProviderIds: clearedProviderIds.current,
        });
        applyProviders(merged);
        setLoad({ status: 'ok' });
        if (migrateOnFirstUpload && shouldSyncLocalProvidersToDaemon(localBeforeMerge, daemonResult)) {
          void persist();
        }
      });
    },
    [persist, applyProviders, normalizeMediaProviderMap],
  );

  useEffect(() => {
    // Mount (or host-supplied port swap): migration is a one-time boot
    // check, matching the origin's App.tsx boot sequence — a manual
    // `reload()` below must not re-trigger it on every click.
    fetchAndReconcile(true);
  }, [port, fetchAndReconcile]);

  const reload = useCallback(() => {
    fetchAndReconcile(false);
  }, [fetchAndReconcile]);

  const updateProvider = useCallback(
    (providerId: string, patch: MediaProviderEditPatch) => {
      providerId = canonicalMediaProviderId({ id: providerId });
      const current = providersRef.current;
      const nextEntry: MediaProviderCredentials = { ...(current[providerId] ?? {}), ...patch };
      const nextMap = { ...current };
      if (isEntryEmpty(nextEntry)) {
        delete nextMap[providerId];
      } else {
        nextMap[providerId] = nextEntry;
      }
      applyProviders(nextMap);
      const currentPending = pendingRef.current;
      if (!currentPending.has(providerId)) applyPending(new Set(currentPending).add(providerId));
      mutatedSinceSend.current.add(providerId);
    },
    [applyProviders, applyPending, canonicalMediaProviderId],
  );

  const clearProvider = useCallback(
    (providerId: string) => {
      providerId = canonicalMediaProviderId({ id: providerId });
      void (async () => {
        const previousEntry = providersRef.current[providerId];
        const next = { ...providersRef.current };
        delete next[providerId];
        applyProviders(next);
        mutatedSinceSend.current.add(providerId);
        clearedProviderIds.current.add(providerId);
        const outcome = await persist();
        // A FAILED save rolls the optimistic clear back so the operator does
        // not lose a credential the daemon never actually dropped — same
        // rollback shape as `useProjectLocationsTab.removeDraft`.
        //
        // The tombstone goes with it. It exists to defend a clear the daemon has not caught up to
        // yet; once the clear is being abandoned there is nothing left to defend, and a tombstone
        // outliving its clear would suppress the provider on every future reload — a resurrection
        // bug traded for a disappearance bug. Released on `abandoned` too: an unmounted tree has no
        // state to reconcile, and this ref does not survive the remount that would need it.
        if (outcome.status !== 'saved') clearedProviderIds.current.delete(providerId);
        if (outcome.status !== 'failed' || !alive.current) return;
        if (previousEntry === undefined) return;
        // Restore ONLY this provider, into whatever the map is NOW. Restoring
        // the whole pre-clear snapshot (as this used to) would silently discard
        // an edit made to a DIFFERENT provider while the save was in flight —
        // the same whole-map-replacement mistake the port makes, repeated
        // locally. And if the operator has since re-entered this provider by
        // hand, their value wins over the rollback.
        if (providersRef.current[providerId] !== undefined) return;
        applyProviders({ ...providersRef.current, [providerId]: previousEntry });
      })();
    },
    [persist, applyProviders, canonicalMediaProviderId],
  );

  const saveChanges = useCallback(() => {
    void persist();
  }, [persist]);

  return {
    providers,
    load,
    save,
    hasAnyConfigured: hasAnyConfiguredProvider(providers),
    pendingProviderIds,
    updateProvider,
    clearProvider,
    saveChanges,
    reload,
  };
}

// Minimal Markdown → safe HTML renderer for a saved memory entry's preview
// body. OD's real `runtime/markdown.tsx` (2,881 lines) is chat/artifact
// rendering territory, explicitly deferred to `@jini-ai/chat`'s `./react` subpath (formerly
// this package's own `./chat` export, extracted 2026-08-03)/this package's own `./renderers`
// subpath (see `packages/ui/source-map.md`) — this is a
// scoped-down local reimplementation covering just this slice's one need:
// render a memory body's GFM Markdown as read-only preview text. Built on
// `micromark`, already a real dependency of this package (see
// `src/utils/markdown-scroll-sync.ts`). `micromark` escapes raw HTML in the
// input by default (no `allowDangerousHtml`), so this is XSS-safe without
// an extra sanitizer pass.
import { micromark } from 'micromark';
import { gfm, gfmHtml } from 'micromark-extension-gfm';

export function renderMarkdown(body: string) {
  const html = micromark(body, {
    extensions: [gfm()],
    htmlExtensions: [gfmHtml()],
  });
  // eslint-disable-next-line react/no-danger -- `html` is micromark's own
  // escaped output (raw HTML in the source is neutralized, not passed
  // through), so this is not an unsanitized-input XSS risk.
  return <div className="memory-markdown-body" dangerouslySetInnerHTML={{ __html: html }} />;
}

import type {
  StandingDraftAutosaveInput,
  StandingDraftAutosaveSnapshot,
} from "../hooks/use-standing-draft-autosave.hooks.js";

/**
 * @file Last-resort per-tab mirror for a standing draft the SERVER REFUSED (2026-09-06 stale-basis
 * fix). Deliberately NOT a general autosave backend — browser storage was explicitly rejected for
 * that (see `use-standing-draft-autosave.hooks.ts`'s header); this holds exactly one thing: the
 * text the server answered `applied: false` or HTTP 401 to, which it will keep refusing until the
 * editor reloads the row or the operator signs in again. Server-side parking is impossible for that text, so without this the
 * operator's only copy lives in a tab they may close at any moment.
 *
 * Written only on a refusal, read only as the mount-time fallback when the server has nothing
 * parked, and dropped the moment the server accepts a write again, the operator discards, or a real
 * Save lands. Every access is wrapped: `localStorage` throws outright in some privacy modes and on
 * quota exhaustion, and a failed backup must never break the editor it is protecting.
 *
 * Type-only import from the hook module — no runtime edge, and the hook keeps owning the shapes
 * both editors already import from it.
 */

/** Namespaced so one entry's backup can never collide with another's, or with unrelated app keys. */


/** Legacy marker for injected ports with no identity metadata — a recovered backup is identifiably
 *  local rather than pretending the server parked it. Production now uses the actual principal id
 *  captured by the session adapter. The legacy marker still keeps old fakes honest because
 *  {@link StandingDraftAutosaveSnapshot} requires the field; inventing a server principal would be
 *  the same class of defect this whole fix is about. */
export const LOCAL_BACKUP_PRINCIPAL_ID = "local-tab-backup";

/** Bind a profile-local refusal mirror without choosing the host's storage namespace.
 * Storage is obtained lazily inside guarded operations, so privacy-mode getters cannot break mount.
 * @complexity O(draft size) for reads/writes; O(1) for clears.
 */
export function createStandingDraftLocalBackup(
  { keyPrefix: KEY_PREFIX, getStorage }: { keyPrefix: string; getStorage: (required: Record<string, never>, optional?: Record<string, never>) => Pick<Storage, "getItem" | "setItem" | "removeItem"> },
  _options: Record<string, never> = {},
) {
  // Never sees a `null` principal: write/read/clear each return before reaching storage for one, so
  // the old `principalId ?? ""` fallback here could not run.
  function keyFor(entryId: string, principalId: string | undefined): string {
    return principalId === undefined ? `${KEY_PREFIX}${entryId}` : `${KEY_PREFIX}${encodeURIComponent(principalId)}.${encodeURIComponent(entryId)}`;
  }

  /** Mirrors a refused draft for this browser profile. Silent no-op on any storage failure.
   *  @complexity Time/space: O(size of the draft) for the one `JSON.stringify`. */
  function writeStandingDraftLocalBackup({ entryId, draft, savedAt }: { entryId: string; draft: StandingDraftAutosaveInput; savedAt: string }, options: { principalId?: string | null | undefined } = {}): void {
    if (options.principalId === null) return;
    const snapshot: StandingDraftAutosaveSnapshot = { ...draft, savedAt, savedByPrincipalId: options.principalId ?? LOCAL_BACKUP_PRINCIPAL_ID };
    try {
      const storage = getStorage({}, {});
      storage.setItem(keyFor(entryId, options.principalId), JSON.stringify(snapshot));
    } catch {
      // eslint-disable-next-line no-console -- best-effort; the operator's text is still in the tab.
      console.warn("standing-draft local backup: could not write");
    }
  }

  /** The mirrored draft, or `null` when there is none (or storage is unreadable/corrupt).
   *  @complexity Time/space: O(size of the stored draft). */
  function readStandingDraftLocalBackup({ entryId }: { entryId: string }, options: { principalId?: string | null | undefined } = {}): StandingDraftAutosaveSnapshot | null {
    if (options.principalId === null) return null;
    try {
      const storage = getStorage({}, {});
      const raw = storage.getItem(keyFor(entryId, options.principalId));
      return raw ? (JSON.parse(raw) as StandingDraftAutosaveSnapshot) : null;
    } catch {
      return null;
    }
  }

  /** Drops the mirror. Called on an accepted write, an explicit discard, and a real Save.
   *  @complexity Time/space: O(1). */
  function clearStandingDraftLocalBackup({ entryId }: { entryId: string }, options: { principalId?: string | null | undefined } = {}): void {
    if (options.principalId === null) return;
    try {
      const storage = getStorage({}, {});
      storage.removeItem(keyFor(entryId, options.principalId));
    } catch {
      // Nothing to do and nothing to tell the operator — a backup that cannot be removed is
      // superseded by the next write anyway, and is never auto-applied.
    }
  }

  return { write: writeStandingDraftLocalBackup, read: readStandingDraftLocalBackup, clear: clearStandingDraftLocalBackup };
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";

import { useSerialWrites } from "./use-serial-writes.hooks.js";
import type { createStandingDraftLocalBackup } from "../helpers/standing-draft-local-backup.js";
/**
 * @file Standing-draft autosave (2026-09-06 dispatch, owner's own words: "even if they haven't
 * saved it, temp save it whenever they make a draft... it's just saving to... the database. It
 * should be a standing draft anytime something is updated"). Persists to the server
 * (`server/inbound/admin-http/routes/posts/autosave.ts`, `posts.autosave_json`) so a reload or an
 * accidental exit never loses unsaved edits — browser storage alone was rejected.
 *
 * Feature-agnostic on purpose, matching `use-dirty-guard.hooks.ts`'s own precedent: nothing here
 * imports `features/posts` or `features/pages`, so `PostEditorPort`/`PageEditorPort` each satisfy
 * {@link StandingDraftAutosavePort} structurally (same three method shapes, declared independently
 * per that DI-seam convention) with zero cross-feature import. This is the mechanism that lets one
 * implementation serve both editors with no branch between them.
 *
 * Two things this hook does NOT do, deliberately:
 * - Never auto-applies a recovered draft. {@link StandingDraftAutosaveController.recoverableDraft}
 *   is exposed for the caller to render an explicit "restore or discard" banner; silently splicing
 *   in a recovered draft is dangerous with two tabs or two operators open on the same entry.
 * - Never compares `recoverableDraft.baseVersion` against the entry's current version itself — the
 *   caller (which already has the freshly-loaded record) decides whether to label a recovered draft
 *   "outdated" because a real save happened since it was captured.
 *
 * STALE BASIS (added 2026-09-06, fixing silent data loss). `putAutosave` answers `{ applied }`, and
 * `applied: false` means the row's `version` moved under this tab — another tab or operator saved,
 * so every further write against this basis will be refused too (the guard is
 * `host features/post/repo.sqlite.ts`'s `writeAutosave`). That flag used to be thrown
 * away: the hook kept firing refused ticks forever, nothing was ever parked, and a reload produced
 * no recovery banner because there was nothing to recover — an hour of typing could vanish with the
 * operator never told anything. Now a refusal:
 * 1. records {@link StandingDraftStaleBasis} (exposed so the editor can say something true),
 * 2. stops scheduling further writes until the caller supplies a draft on a DIFFERENT `baseVersion`
 *    — i.e. until the editor reloads the row; no manual reset call is needed,
 * 3. mirrors the refused text into `lib/standing-draft-local-backup.ts`, the only place it can
 *    survive a tab close while the server refuses it, and offers it back through the existing
 *    `recoverableDraft` banner on the next mount when the server has nothing parked.
 * The operator's in-memory text is never touched by any of this.
 *
 * The gate and the mirror have DIFFERENT lifetimes on purpose. The gate lifts the instant the
 * caller edits on a fresh basis; the mirror survives until the server has actually accepted a write
 * (or a real Save/discard superseded it), because between those two moments nothing has been
 * persisted anywhere and the mirror is still the only copy of the refused text that outlives the
 * tab. Collapsing the two back into one "clear it all" step reintroduces a window in which a failed
 * request loses the work.
 */

/** The fields a standing draft carries — see `PostAutosaveSnapshot`'s own server-side doc for why
 *  `status` is deliberately absent (a draft must never change whether a row is live). */
export type StandingDraftAutosaveInput =
  | { bodyFormat: "doc"; bodyJson: Record<string, unknown>; title: string; slug: string; baseVersion: number }
  | { bodyFormat: "html"; bodyHtml: string; title: string; slug: string; baseVersion: number };

export interface StandingDraftAutosaveSnapshot {
  bodyFormat: "doc" | "html";
  bodyJson?: Record<string, unknown>;
  bodyHtml?: string;
  title: string;
  slug: string;
  baseVersion: number;
  savedAt: string;
  savedByPrincipalId: string;
  /** Fresh server timestamp used only for the explicit recovery comparison. */
  serverUpdatedAt?: string | undefined;
}

/** What this hook needs from the outside world — see this file's header for why it is declared
 *  here rather than imported from either feature's own port. */
export interface StandingDraftAutosavePort {
  /** Captured before expiry so late failures cannot borrow the next operator's identity. */
  getBackupPrincipalId?: (requiredArgs: Record<string, never>, optionalArgs?: Record<string, never>) => string | null;
  /**
   * `options.keepalive` (2026-09-07) asks for an UNLOAD-SAFE transport, and is set only by the exit
   * flush below. An ordinary `fetch` started from `pagehide` or `visibilitychange`→hidden is
   * cancelled when the browser tears the document down — so the newest edit, the one still sitting
   * in the debounce window, was precisely the one those listeners could not actually rescue.
   *
   * Opt-in rather than always-on because `keepalive` carries a 64 KiB body ceiling an ordinary
   * request does not; an implementation that cannot honour it may ignore it (the parameter is
   * optional), which is exactly the behavior this path had before.
   */
  putAutosave(
    required: { id: string; draft: StandingDraftAutosaveInput },
    options?: { keepalive?: boolean }
  ): Promise<{ applied: boolean }>;
  getAutosave(required: { id: string }, optional?: Record<string, never>): Promise<{ autosave: StandingDraftAutosaveSnapshot | null }>;
  discardAutosave(required: { id: string }, optional?: Record<string, never>): Promise<{ ok: boolean }>;
}

/** A write the server refused because the row moved on — see this file's header. Carries the
 *  operator's refused text itself, not just a flag: it is the copy nothing else on the client has
 *  a claim to, and a conflict notice that drops the work would be worse than the silent drop. */
export interface StandingDraftStaleBasis {
  /** The `baseVersion` the refused draft was built on. The gate lifts when a later
   *  `scheduleAutosave` arrives on a different one. */
  baseVersion: number;
  /** Exactly what was refused. */
  draft: StandingDraftAutosaveInput;
}

export interface StandingDraftAutosaveController {
  /** Non-null once the mount-time recovery check resolves and finds a parked draft. Stays exactly
   *  as read until {@link dismissRecoverable}/{@link clearStandingDraft} clears it — never
   *  overwritten by a later `scheduleAutosave` tick from THIS session, since a session that is
   *  actively autosaving has, by definition, already accounted for whatever it found on mount. */
  recoverableDraft: StandingDraftAutosaveSnapshot | null;
  /** Non-null once the server has refused a write for this entry, and until the caller edits on a
   *  fresh basis (or a real Save/discard runs). While it is set, `scheduleAutosave` deliberately
   *  sends nothing — every such write would be refused. The editor should tell the operator that
   *  another save happened, that reloading is what resumes autosaving, and that their text is kept.
   *  Purely additive: a caller that ignores it behaves exactly as before EXCEPT that refused writes
   *  are no longer retried forever. */
  staleBasis: StandingDraftStaleBasis | null;
  /** Clears `recoverableDraft` locally only (no server call) — the "Discard" affordance calls
   *  {@link clearStandingDraft} instead, which also tells the server; this is for a caller that
   *  wants to stop showing the banner without discarding anything (e.g. "Restore" applied it into
   *  the editor, and a real Save moments later will clear the server-side draft on its own). */
  dismissRecoverable: () => void;
  /** Call on every content change the caller wants protected — cheap, debounced internally
   *  (idle 3s / 15s hard ceiling while continuously typing), safe to call on every keystroke.
   *  Whatever is still sitting in the debounce window when the editor goes away is written by the
   *  flush this hook wires up itself — see the `flushPendingAutosave` effects below. */
  scheduleAutosave: (draft: StandingDraftAutosaveInput) => void;
  /**
   * Clears the server-side standing draft — call after a real Save/Publish succeeds, or when the
   * operator explicitly discards a recovered draft. Cancels any pending (not yet fired) debounce
   * timer FIRST, then enqueues the discard onto the same serial request chain every
   * `scheduleAutosave` tick uses, so a still-in-flight (already fired) autosave write is guaranteed
   * to reach the server before this discard does, and no new one can be queued after it — the
   * ordering guarantee that keeps a late autosave from resurrecting content a real save (or an
   * explicit discard) just superseded.
   */
  clearStandingDraft: () => Promise<void>;
  /**
   * The caller replaced its basis with a newer saved row it did not write itself (an assistant
   * write applied by `use-external-entry-refresh.hooks.ts`, silently or through Load latest). Every
   * write built on an OLDER `baseVersion` is superseded from here on: a pending one is cancelled, a
   * later `scheduleAutosave` on one is dropped (a render that committed before the replacement can
   * still run its autosave effect after this call), and the refusal of one already in flight is
   * ignored. Without this, that write reached the server, was refused, paused autosaving and
   * mirrored text for a version the editor had already left (reviewer finding 2, 2026-09-16).
   *
   * A gate recorded on an older basis lifts, because the editor is no longer on it. That refusal's
   * mirror is kept: nothing has accepted its text anywhere (see this file's header). Does not touch
   * the server-side draft — Load latest also calls {@link clearStandingDraft} for that.
   */
  supersedeBasis: (baseVersion: number) => void;
  preserveFailedSave: (requiredArgs: { error: unknown; draft: StandingDraftAutosaveInput }, optionalArgs?: Record<string, never>) => void;
}

/** Idle debounce: fires this long after the LAST `scheduleAutosave` call with no further calls. */
const IDLE_DEBOUNCE_MS = 3000;
/** Hard ceiling while continuously typing: once this much time has passed since the first
 *  unflushed edit, the next tick fires immediately instead of resetting the idle window again. */
const MAX_WAIT_MS = 15000;

export interface StandingDraftAutosaveOptions {
  port: StandingDraftAutosavePort;
  backup: ReturnType<typeof createStandingDraftLocalBackup>;
  /** `null` before the entry has loaded (or for a not-yet-created entry) — every operation no-ops. */
  entryId: string | null;
  /** Gate for "this editor is in a state where autosave should run at all" (e.g. not while a save
   *  or delete is already in flight). Recovery-check and scheduling both respect it. */
  enabled: boolean;
  serverUpdatedAt?: string | undefined;
}

export function useStandingDraftAutosave(deps: StandingDraftAutosaveOptions, _options: Record<string, never> = {}): StandingDraftAutosaveController {
  const { port, backup, entryId, enabled, serverUpdatedAt } = deps;
  const [backupPrincipalId] = useState(() => port.getBackupPrincipalId?.({}, {}));
  const latestDraftRef = useRef<StandingDraftAutosaveInput | null>(null);
  const backupGenerationRef = useRef(0);
  const [recoverableDraft, setRecoverableDraft] = useState<StandingDraftAutosaveSnapshot | null>(null);
  const [staleBasis, setStaleBasis] = useState<StandingDraftStaleBasis | null>(null);
  // Mirrors `staleBasis` for the SYNCHRONOUS gate in `scheduleAutosave`: the refusal is discovered
  // inside the request chain, and a React state read there would be a render behind — the window in
  // which the very ticks this gate exists to stop would still be scheduled.
  const staleBasisRef = useRef<StandingDraftStaleBasis | null>(null);
  // Which entry's refused text is currently mirrored in browser storage, or `null`. Deliberately
  // NOT the same lifetime as the gate above (see this file's header), and deliberately an entry id
  // rather than a boolean: it is the proof that a mirror this hook may drop belongs to the entry
  // being edited right now, so switching entries can never delete another entry's surviving copy.
  const backupEntryIdRef = useRef<string | null>(null);
  // Every network op (each autosave PUT, and the eventual discard) is appended here, never fired
  // standalone — this IS the ordering guarantee `clearStandingDraft`'s own doc describes. Caught
  // internally (see `enqueue`) so one failed request can never permanently wedge the lane.
  const writes = useSerialWrites();
  const idleTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const firstPendingAtRef = useRef<number | null>(null);
  // The newest draft handed to `scheduleAutosave` that has NOT yet been written — what a flush
  // sends. A ref, not the timer's own closure, precisely so an exit event can reach it: the
  // closure is unreachable from outside the `setTimeout` callback, which is why cancelling the
  // timer used to be indistinguishable from losing the edit.
  const pendingDraftRef = useRef<StandingDraftAutosaveInput | null>(null);
  // The lowest `baseVersion` a write may still carry for the current entry — see `supersedeBasis`.
  // `null` until the caller supersedes a basis; reset on an entry change, because another entry's
  // version numbers are unrelated.
  const minBaseVersionRef = useRef<number | null>(null);

  const clearPendingTimer = useCallback(() => {
    if (idleTimerRef.current !== null) clearTimeout(idleTimerRef.current);
    idleTimerRef.current = null;
    firstPendingAtRef.current = null;
    pendingDraftRef.current = null;
  }, []);

  /** The server refused this draft. Records the basis, and mirrors the text locally — the ONLY
   *  place it can survive a tab close while the server keeps refusing it. @complexity O(1). */
  const markStaleBasis = useCallback((id: string, draft: StandingDraftAutosaveInput) => {
    const next: StandingDraftStaleBasis = { baseVersion: draft.baseVersion, draft };
    staleBasisRef.current = next;
    setStaleBasis(next);
    backup.write({ entryId: id, draft, savedAt: new Date().toISOString() }, { principalId: backupPrincipalId });
    backupEntryIdRef.current = id;
  }, [backupPrincipalId, backup]);

  /** Lifts the gate so scheduling resumes. Does NOT touch the mirror — see this file's header for
   *  why those two are separate. No-op when nothing is stale, so the common path never re-renders.
   *  @complexity O(1). */
  const liftStaleGate = useCallback(() => {
    if (staleBasisRef.current === null) return;
    staleBasisRef.current = null;
    setStaleBasis(null);
  }, []);

  /** Drops the browser-storage mirror for the entry being edited, if it has one. Called only where
   *  the operator's text provably survives somewhere else — the server just accepted a write (so it
   *  is parked server-side), or a real Save/discard superseded it. @complexity O(1). */
  const dropLocalBackup = useCallback(() => {
    const id = backupEntryIdRef.current;
    if (id === null) return;
    backupEntryIdRef.current = null;
    backup.clear({ entryId: id }, { principalId: backupPrincipalId });
  }, [backupPrincipalId, backup]);

  // Mount-time (and entry-change) recovery check — one read, never repeated while this entryId
  // stays mounted. A stale in-flight response from a PREVIOUS entryId is dropped via `cancelled`.
  useEffect(() => {
    setRecoverableDraft(null);
    // A different entry is a different basis. A gate recorded for the PREVIOUS entryId must never
    // silence autosave for this one — their `version` numbers are very often both 1, so leaving it
    // set would silently stop autosaving an entry nobody has a conflict on. In-memory only: the
    // previous entry's local mirror is keyed under ITS id and stays recoverable there.
    staleBasisRef.current = null;
    setStaleBasis(null);
    // Same reasoning for the mirror pointer, one step further: the previous entry's mirror stays in
    // storage under ITS OWN key and stays recoverable there — only this hook's permission to drop a
    // mirror is reset, so a later accepted write for THIS entry cannot delete that other copy.
    backupEntryIdRef.current = null;
    minBaseVersionRef.current = null;
    latestDraftRef.current = null;
    if (!enabled || !entryId) return undefined;
    let cancelled = false;
    port
      .getAutosave({ id: entryId }, {})
      .then((result) => {
        if (cancelled) return;
        const localBackup = backup.read({ entryId }, { principalId: backupPrincipalId });
        // Recorded whether or not it is the copy shown below: it exists, so a real Save or an
        // explicit discard on this entry has to be able to drop it. Without this the mirror written
        // before a reload would outlive every discard and re-offer itself on every later mount.
        if (localBackup !== null) backupEntryIdRef.current = entryId;
        // Historically server first — a parked draft is shared across tabs. For expiry recovery,
        // compare capture times instead: a 401 mirror may contain edits newer than that parked copy. The local
        // mirror is the fallback for exactly the case that produced it: the other tab's real save
        // cleared the server-side draft, so this tab reloads into "nothing to recover" while its
        // own refused text is the thing the operator actually wants back.
        const server = result.autosave;
        // A 401 mirror can be newer than the last accepted server autosave. Keep the newest copy.
        const newest = localBackup && (!server || localBackup.savedAt > server.savedAt) ? localBackup : server;
        setRecoverableDraft(newest);
      })
      .catch(() => {
        // A failed server recovery read must not hide the local copy rescued from an expired session.
        if (cancelled) return;
        const localBackup = backup.read({ entryId }, { principalId: backupPrincipalId });
        if (localBackup !== null) backupEntryIdRef.current = entryId;
        setRecoverableDraft(localBackup);
      });
    return () => {
      cancelled = true;
    };
  }, [enabled, entryId, port, backupPrincipalId, backup]);

  const enqueue = useCallback(
    (op: () => Promise<void>): Promise<void> =>
      writes.run({ task: op }).catch(() => {
        // eslint-disable-next-line no-console -- best-effort background persistence; surfaced to
        // the console rather than the operator, who has nothing actionable to do about one dropped
        // autosave tick, and rather than thrown, which would wedge every later tick on this chain.
        console.error("standing-draft autosave: request failed");
      }),
    [writes]
  );

  const preserveFailedSave = useCallback(({ error, draft }: { error: unknown; draft: StandingDraftAutosaveInput }, _options: Record<string, never> = {}) => {
    if (!entryId || !isUnauthorizedDraftWrite(error)) return;
    backup.write({ entryId, draft, savedAt: new Date().toISOString() }, { principalId: backupPrincipalId });
    backupEntryIdRef.current = entryId;
  }, [entryId, backupPrincipalId, backup]);

  /** The one place `putAutosave` is called. Its `{ applied }` answer is acted on here rather than
   *  discarded — see this file's STALE BASIS note. @complexity Time/space: O(1) plus the request. */
  const writeAutosave = useCallback(
    (id: string, draft: StandingDraftAutosaveInput, keepalive: boolean) => {
      const generation = backupGenerationRef.current;
      return enqueue(async () => {
        let result: { applied: boolean };
        try {
          result = await port.putAutosave({ id, draft }, { keepalive });
        } catch (error) {
          // A 401 can unmount the editor before this settles; the captured identity still owns it.
          // Use the newest scheduled text, since an older request may fail while typing continues.
          if (generation === backupGenerationRef.current) preserveFailedSave({ error, draft: latestDraftRef.current ?? draft });
          throw error;
        }
        if (generation !== backupGenerationRef.current) return;
        if (!result.applied) {
          // Refused because the caller already moved past this basis — nothing to pause or mirror.
          if (isSupersededBasis(draft.baseVersion, minBaseVersionRef.current)) return;
          markStaleBasis(id, draft);
          return;
        }
        // Accepted — the text is parked server-side now, which is the ONLY point at which the
        // mirror is redundant and may go.
        liftStaleGate();
        dropLocalBackup();
      });
    },
    [dropLocalBackup, enqueue, liftStaleGate, markStaleBasis, port, preserveFailedSave]
  );

  const scheduleAutosave = useCallback(
    (draft: StandingDraftAutosaveInput) => {
      if (!enabled || !entryId) return;
      latestDraftRef.current = draft;
      if (isSupersededBasis(draft.baseVersion, minBaseVersionRef.current)) return;
      // The gate. Same basis as the one the server already refused => this write would be refused
      // too, so it is not scheduled at all; a DIFFERENT basis means the editor reloaded the row, so
      // the gate lifts by itself and no caller has to remember to reset anything.
      const stale = staleBasisRef.current;
      if (stale !== null && stale.baseVersion === draft.baseVersion) return;
      // The mirror is deliberately left in place here: nothing has been written yet, so until the
      // server accepts, that mirror is still the only copy of the refused text that outlives the tab.
      liftStaleGate();
      const now = Date.now();
      if (firstPendingAtRef.current === null) firstPendingAtRef.current = now;
      const waitedSoFar = now - firstPendingAtRef.current;
      // Clamped, not a plain "already past the ceiling?" check: without the clamp, a call arriving
      // just before the ceiling would still schedule a FULL fresh `IDLE_DEBOUNCE_MS`, pushing the
      // actual fire time past `MAX_WAIT_MS` under continuous typing (verified by the ceiling test —
      // an unclamped version never fires within the window it claims to bound).
      const delay = Math.max(0, Math.min(IDLE_DEBOUNCE_MS, MAX_WAIT_MS - waitedSoFar));

      pendingDraftRef.current = draft;
      if (idleTimerRef.current !== null) clearTimeout(idleTimerRef.current);
      idleTimerRef.current = setTimeout(() => {
        idleTimerRef.current = null;
        firstPendingAtRef.current = null;
        pendingDraftRef.current = null;
        // Not an exit: the page is still here, so an ordinary fetch (no 64 KiB ceiling) is right.
        writeAutosave(entryId, draft, false);
      }, delay);
    },
    [enabled, entryId, liftStaleGate, writeAutosave]
  );

  /**
   * Writes a pending (not yet fired) autosave immediately instead of waiting the debounce out —
   * the half of the cadence that makes the owner's actual requirement true ("what if they reload
   * the page on accident or exit out of the page? I don't want them to lose their work"). The
   * debounce always leaves a window of up to {@link IDLE_DEBOUNCE_MS} in which the newest edit
   * exists only in React state; without this, every exit inside that window discards it.
   *
   * Goes onto the same serial chain every other write uses, so it can never overtake an in-flight
   * PUT or a discard already queued by {@link clearStandingDraft} — and because that function
   * nulls `pendingDraftRef`, a flush after a real Save is a no-op rather than a resurrection.
   *
   * @complexity Time/space: O(1) — one ref read and at most one enqueued request.
   */
  const flushPendingAutosave = useCallback(
    (keepalive: boolean) => {
      const draft = pendingDraftRef.current;
      if (draft === null || !entryId) return;
      clearPendingTimer();
      writeAutosave(entryId, draft, keepalive);
    },
    [clearPendingTimer, entryId, writeAutosave]
  );

  // Flush, do not cancel, when this editor goes away. An in-app navigation (the "Posts"/"Pages"
  // back link, or any router move) unmounts the hook while a debounced tick is still pending, and
  // the previous cancel-on-unmount is exactly how the last seconds of typing were lost — verified
  // in a real browser on 2026-09-06: typed into the Pages editor, followed the in-app link one
  // second later, and no PUT was ever issued. The SPA outlives the unmount, so the request started
  // here completes normally. Re-running on an `entryId` change is correct too: the cleanup closes
  // over the OUTGOING entry, so switching entries parks the one being left behind.
  // `keepalive: false` — an unmount is an in-app navigation, not a page teardown. The SPA outlives
  // it, so the request started here completes normally and must not pay keepalive's body ceiling.
  useEffect(() => () => flushPendingAutosave(false), [flushPendingAutosave]);

  // The exits React never sees. `pagehide` covers a tab close, a reload and a same-tab navigation;
  // `visibilitychange` covers a tab switch or the OS backgrounding the browser, where `pagehide`
  // may never fire; `blur` covers switching to another desktop app with the tab still visible.
  // `beforeunload` is deliberately NOT one of them — `use-dirty-guard.hooks.ts` already registers
  // it, and it is a PROMPT, not a persistence hook: answering "Leave" still discards whatever the
  // debounce had not written. Each handler is a no-op when nothing is pending, so overlapping
  // events (a close fires blur AND pagehide) cost one write, not three.
  useEffect(() => {
    if (!enabled || !entryId) return undefined;
    // Wrapped rather than passed straight to `addEventListener`: a listener is called WITH the
    // Event, which would arrive as `flushPendingAutosave`'s `keepalive` argument — a truthy object,
    // so every flush would silently request keepalive whether or not it is an exit.
    const onExit = () => flushPendingAutosave(true);
    const onVisibilityChange = () => {
      if (document.visibilityState === "hidden") flushPendingAutosave(true);
    };
    window.addEventListener("pagehide", onExit);
    window.addEventListener("blur", onExit);
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => {
      window.removeEventListener("pagehide", onExit);
      window.removeEventListener("blur", onExit);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, [enabled, entryId, flushPendingAutosave]);

  const clearStandingDraft = useCallback(async () => {
    // A late 401/refusal must not resurrect a draft a successful Save or Discard superseded.
    backupGenerationRef.current++;
    clearPendingTimer();
    setRecoverableDraft(null);
    // A real Save landed (or the operator discarded): whatever was refused is superseded, so the
    // gate lifts and the mirror goes with it — otherwise the next mount would offer a ghost. This
    // is also the ONLY thing that clears a mirror the operator has already been shown and chose to
    // discard, since by then the gate that wrote it belongs to a previous mount.
    liftStaleGate();
    dropLocalBackup();
    if (!entryId) return;
    await enqueue(async () => {
      await port.discardAutosave({ id: entryId }, {});
    });
  }, [clearPendingTimer, dropLocalBackup, enqueue, entryId, liftStaleGate, port]);

  const dismissRecoverable = useCallback(() => setRecoverableDraft(null), []);

  const supersedeBasis = useCallback(
    (baseVersion: number) => {
      minBaseVersionRef.current = baseVersion;
      const pending = pendingDraftRef.current;
      if (pending !== null && isSupersededBasis(pending.baseVersion, baseVersion)) clearPendingTimer();
      const stale = staleBasisRef.current;
      if (stale !== null && isSupersededBasis(stale.baseVersion, baseVersion)) liftStaleGate();
    },
    [clearPendingTimer, liftStaleGate]
  );

  const comparedDraft = useMemo(() => recoverableDraft ? { ...recoverableDraft, serverUpdatedAt } : null, [recoverableDraft, serverUpdatedAt]);
  return { recoverableDraft: comparedDraft, staleBasis, dismissRecoverable, scheduleAutosave, clearStandingDraft, supersedeBasis, preserveFailedSave };
}

/** Whether a write built on `baseVersion` belongs to a basis the caller has left (see
 *  `supersedeBasis`). @complexity O(1). */
function isSupersededBasis(baseVersion: number, minBaseVersion: number | null): boolean {
  return minBaseVersion !== null && baseVersion < minBaseVersion;
}

function isUnauthorizedDraftWrite(error: unknown): boolean {
  return typeof error === "object" && error !== null && "status" in error && error.status === 401;
}

import { useCallback, useEffect, useRef, useState } from 'react';
import type { ProjectLocationsPort } from '../../ports.js';
import {
  DEFAULT_LOCATION_ID,
  externalLocations,
  isDuplicatePath,
  resolveDefaultLocationId,
  saveableDrafts,
} from '../../rules.js';
import type {
  ProjectLocation,
  ProjectLocationDraft,
  ProjectLocationsActionResult,
} from '../../types.js';

export interface UseProjectLocationsTabOptions {
  port: ProjectLocationsPort;
  /** Host-configured default location id. May be stale (name a location the
   *  operator has since removed) — the hook corrects it after any save that
   *  makes it dangling; see `resolveDefaultLocationId`. */
  defaultLocationId?: string | null | undefined;
  /** Fires when the effective default changes — either the operator picked a
   *  new one via `setDefaultLocationId`, or a stale configured default was
   *  corrected after a save. */
  onDefaultLocationIdChange?: ((id: string) => void) | undefined;
}

export interface UseProjectLocationsTabResult {
  /** The full list, built-in root included. Empty until the initial load
   *  settles. */
  locations: readonly ProjectLocation[];
  /** The editable (non-built-in) rows. */
  drafts: readonly ProjectLocationDraft[];
  builtIn: ProjectLocation | undefined;
  effectiveDefaultLocationId: string;
  loading: boolean;
  saving: boolean;
  result: ProjectLocationsActionResult;
  addFolder: () => void;
  removeDraft: (index: number) => void;
  setDefaultLocationId: (id: string) => void;
}

/** Scan a saved location; disposed callers cannot publish success or failure. */
export async function scanAddedLocation(
  { port, alive, setResult }: {
    port: ProjectLocationsPort;
    alive: { readonly current: boolean };
    setResult: (result: ProjectLocationsActionResult) => void;
  },
  _options = {},
): Promise<void> {
  const scan = port.scanLocations;
  if (!scan) return;
  try {
    const scanResult = await scan.call(port);
    if (!alive.current) return;
    setResult({ status: 'scan-complete', imported: scanResult.imported.length, existing: scanResult.existing.length });
  } catch (error: unknown) {
    if (!alive.current) return;
    setResult({ status: 'scan-error', message: error instanceof Error ? error.message : String(error) });
  }
}

/**
 * Owns the tab's async edges: the initial locations fetch, the add-folder ->
 * duplicate-check -> save -> (optional) scan sequence, and removal. Origin:
 * `ProjectLocationsSection`'s own `useState`/`useEffect` block — ported as a
 * hook rather than inline so a host can drive the same lifecycle from its own
 * tree if it ever needs to (matches `useExecutionTab`'s convention).
 *
 * The default-location id itself stays host-controlled (`defaultLocationId`/
 * `onDefaultLocationIdChange`), same "tab owns its async edges, host owns
 * cross-cutting config" split as `useExecutionTab`'s `ByokConfig`.
 */
export function useProjectLocationsTab({
  port,
  defaultLocationId,
  onDefaultLocationIdChange,
}: UseProjectLocationsTabOptions): UseProjectLocationsTabResult {
  const [locations, setLocations] = useState<readonly ProjectLocation[]>([]);
  const [drafts, setDrafts] = useState<readonly ProjectLocationDraft[]>([]);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [result, setResult] = useState<ProjectLocationsActionResult>({ status: 'idle' });

  /** Volatile values async callbacks need at RUN time, not at schedule time —
   *  same convention as `useSettingsSlice`'s `io.current`. */
  const portRef = useRef(port);
  portRef.current = port;
  const locationsRef = useRef(locations);
  locationsRef.current = locations;
  const draftsRef = useRef(drafts);
  draftsRef.current = drafts;
  const defaultLocationIdRef = useRef(defaultLocationId);
  defaultLocationIdRef.current = defaultLocationId;
  const onDefaultLocationIdChangeRef = useRef(onDefaultLocationIdChange);
  onDefaultLocationIdChangeRef.current = onDefaultLocationIdChange;

  const alive = useRef(true);
  useEffect(() => {
    alive.current = true;
    return () => {
      alive.current = false;
    };
  }, []);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    portRef.current
      .fetchLocations()
      .then((next) => {
        if (cancelled || !alive.current) return;
        setLocations(next);
        setDrafts(externalLocations(next));
      })
      .finally(() => {
        if (!cancelled && alive.current) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [port]);

  const persist = useCallback(async (nextDrafts: readonly ProjectLocationDraft[]): Promise<readonly ProjectLocation[] | null> => {
    const applySaved = (saved: readonly ProjectLocation[]): readonly ProjectLocation[] => {
      setLocations(saved);
      setDrafts(externalLocations(saved));
      setResult({ status: 'saved' });
      // A save can remove the very location the configured default names —
      // fall back it to the host's own root rather than leaving a dangling
      // id, same correction the origin makes inline in its own `setCfg`.
      const configured = defaultLocationIdRef.current ?? DEFAULT_LOCATION_ID;
      const effective = resolveDefaultLocationId(configured, saved);
      if (effective !== configured) onDefaultLocationIdChangeRef.current?.(effective);
      return saved;
    };
    setSaving(true);
    // One return after the try statement (null unless a still-mounted save succeeded), so no
    // unreachable continuation follows a try and a catch that both return.
    let persisted: readonly ProjectLocation[] | null = null;
    try {
      const saved = await portRef.current.saveLocations(saveableDrafts(nextDrafts));
      if (alive.current) persisted = applySaved(saved);
    } catch (error: unknown) {
      if (alive.current) setResult({ status: 'save-error', message: error instanceof Error ? error.message : String(error) });
    } finally {
      if (alive.current) setSaving(false);
    }
    return persisted;
  }, []);

  const addFolder = useCallback(() => {
    void (async () => {
      setResult({ status: 'idle' });
      const selected = await portRef.current.openFolderDialog();
      if (!alive.current) return;
      if (!selected) {
        setResult({ status: 'no-folder-selected' });
        return;
      }
      // Checked against every current location (built-in root included), not
      // just the editable drafts — a deliberate widening of the origin's
      // drafts-only check, using the same trailing-separator-insensitive
      // comparison `isDuplicatePath` already applies everywhere else.
      if (isDuplicatePath(selected, locationsRef.current)) {
        setResult({ status: 'duplicate' });
        return;
      }
      const previous = draftsRef.current;
      const next = [...previous, { path: selected }];
      setDrafts(next);
      const saved = await persist(next);
      if (!saved) {
        if (alive.current) setDrafts(previous);
        return;
      }
      await scanAddedLocation({ port: portRef.current, alive, setResult });
    })();
  }, [persist]);

  const removeDraft = useCallback(
    (index: number) => {
      void (async () => {
        const previous = draftsRef.current;
        const next = previous.filter((_, i) => i !== index);
        setDrafts(next);
        const saved = await persist(next);
        if (!saved && alive.current) setDrafts(previous);
      })();
    },
    [persist],
  );

  const setDefaultLocationId = useCallback((id: string) => {
    setResult({ status: 'default-saved' });
    onDefaultLocationIdChangeRef.current?.(id);
  }, []);

  return {
    locations,
    drafts,
    builtIn: locations.find((location) => location.builtIn),
    effectiveDefaultLocationId: resolveDefaultLocationId(defaultLocationId ?? null, locations),
    loading,
    saving,
    result,
    addFolder,
    removeDraft,
    setDefaultLocationId,
  };
}

import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from 'react';
import {
  filterBoardItemsByQuery,
  groupItemsByStatus,
  isActionPending,
  pruneSelectedIds,
  sortBoardItems,
  toggleSelectedId,
  withoutPendingAction,
  withPendingAction,
} from '../../rules.js';
import { createLocalStorageViewModeStorage } from '../../dependencies.js';
import type { ResourceBoardDependencies, ResourceBoardPort } from '../../ports.js';
import type { ResourceBoardItem, ResourceBoardViewMode } from '../../types.js';

const ITEM_ACTION_KIND = 'item-action';
const BULK_DELETE_KIND = 'bulk-delete';
const BULK_DELETE_SCOPE = '__bulk__';
const LOAD_FAILED_MESSAGE = 'Failed to load items.';
const REMOVE_FAILED_MESSAGE = 'Failed to delete item.';
const DUPLICATE_FAILED_MESSAGE = 'Failed to duplicate item.';

export interface UseResourceBoardParams<TItem extends ResourceBoardItem> {
  port: ResourceBoardPort<TItem>;
  viewModeStorage?: import('../../ports.js').ResourceViewModeStoragePort;
  /** Scopes the persisted view-mode preference — never a hardcoded storage key (see `ports.ts`). */
  storageScopeKey?: string;
  defaultViewMode?: ResourceBoardViewMode;
  statusOrder?: readonly string[];
  defaultStatus?: string;
  normalizeStatus?: (status: string) => string;
  initialSort?: string;
  /** Bumping this value re-fetches (mirrors TasksView's own `historyTick`-shaped controlled-invalidation pattern) — a host UI that mutated data outside this hook (e.g. its own rename dialog calling the port directly) uses this to force a reload. */
  refreshToken?: string | number;
}

export interface ResourceBoardController<TItem extends ResourceBoardItem> {
  loading: boolean;
  error: string | null;
  /** Raw (pre search-filter) item count — lets a host distinguish "nothing exists yet" from "search matched nothing" without needing its own separate fetch. */
  totalCount: number;
  query: string;
  setQuery: (query: string) => void;
  sort: string | undefined;
  setSort: (value: string) => void;
  viewMode: ResourceBoardViewMode;
  setViewMode: (mode: ResourceBoardViewMode) => void;
  visibleItems: TItem[];
  kanbanColumns: Map<string, TItem[]>;
  selectMode: boolean;
  selected: ReadonlySet<string>;
  enterSelectMode: () => void;
  exitSelectMode: () => void;
  toggleSelected: (id: string) => void;
  bulkDeleteBusy: boolean;
  bulkDelete: () => Promise<{ deleted: number; failed: number }>;
  openMenuId: string | null;
  /** Attach to the currently-open menu's container (only when `openMenuId === item.id`) so the outside-click dismiss effect can tell a click INSIDE the open menu (e.g. clicking a menu item) apart from a genuine outside click — mirrors DesignsTab's own `menuContainerRef` pattern. */
  menuContainerRef: RefObject<HTMLDivElement | null>;
  toggleMenu: (id: string) => void;
  closeMenu: () => void;
  isItemBusy: (id: string) => boolean;
  reload: () => Promise<void>;
  remove: (id: string) => Promise<void>;
  duplicate: (id: string) => Promise<void>;
  /**
   * Set when a single-item `remove`/`duplicate` rejects or otherwise fails
   * (as opposed to `error`, which is the LOAD failure and hides the whole
   * item list — a delete/duplicate failure must stay visible ALONGSIDE the
   * still-present items, mirroring the origin `DesignsTab.tsx`'s
   * `handleDuplicateProject` toast-on-catch). Cleared at the start of the
   * next `remove`/`duplicate` call. `null` when no mutation has failed (or
   * bulk delete, which already reports its own per-item outcome counts and
   * never rejects — see `bulkDelete`).
   */
  actionError: string | null;
}

/**
 * Loads a board item list from the injected port and owns every generic
 * DesignsTab-shaped concern: search, sort, view-mode (persisted), select
 * mode + bulk delete, the single-open-at-a-time kebab menu (with
 * outside-click/Escape dismiss, mirroring the origin's own
 * `menuOpenId`/effect), per-item busy tracking, and kanban-column
 * derivation. Interactive rename (which needs a text input the origin
 * collects via its own `Dialog`) is deliberately NOT handled here — see
 * `ResourceBoard.tsx`'s `onRenameRequest` prop and
 * `packages/ui/archived provenance ledger`'s "Dropped" list.
 */
export function useResourceBoard<TItem extends ResourceBoardItem>(params: UseResourceBoardParams<TItem>): ResourceBoardController<TItem> {
  const { port, refreshToken } = params;
  const viewModeStorage = params.viewModeStorage;
  const storageScopeKey = params.storageScopeKey ?? 'resource-dashboard:view';
  const defaultViewMode = params.defaultViewMode ?? 'grid';
  const statusOrder = params.statusOrder ?? [];

  const [items, setItems] = useState<TItem[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<string | undefined>(params.initialSort);
  const [selectMode, setSelectMode] = useState(false);
  const [selected, setSelected] = useState<ReadonlySet<string>>(new Set());
  const [pendingKeys, setPendingKeys] = useState<ReadonlySet<string>>(new Set());
  const [bulkDeleteBusy, setBulkDeleteBusy] = useState(false);
  const [openMenuId, setOpenMenuId] = useState<string | null>(null);
  const menuContainerRef = useRef<HTMLDivElement | null>(null);
  const [viewMode, setViewModeState] = useState<ResourceBoardViewMode>(() => {
    const stored = (viewModeStorage ?? createLocalStorageViewModeStorage()).getViewMode(storageScopeKey);
    return stored ?? defaultViewMode;
  });

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const fetched = await port.fetchItems();
      setItems(fetched);
      setError(null);
    } catch {
      setError(LOAD_FAILED_MESSAGE);
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port]);

  useEffect(() => {
    void reload();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port, refreshToken]);

  // Drop selected ids that no longer exist (DesignsTab's own "prune selection" effect).
  useEffect(() => {
    setSelected((current) => pruneSelectedIds(current, new Set(items.map((item) => item.id))));
  }, [items]);

  // Leaving grid view exits select mode entirely (DesignsTab hides select-mode UI in kanban view).
  useEffect(() => {
    if (viewMode === 'kanban' && selectMode) {
      setSelectMode(false);
      setSelected(new Set());
    }
  }, [viewMode, selectMode]);

  // Single-open-at-a-time kebab menu: outside-click/Escape dismiss. A click
  // INSIDE the open menu (e.g. a menu item) must NOT close it before its own
  // click handler runs — checked via `menuContainerRef.contains(target)`,
  // same guard DesignsTab's own `menuContainerRef`-based effect uses.
  useEffect(() => {
    if (!openMenuId) return undefined;
    const onKey = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setOpenMenuId(null);
    };
    const onPointerDown = (event: MouseEvent) => {
      const container = menuContainerRef.current;
      if (container && container.contains(event.target as Node)) return;
      setOpenMenuId(null);
    };
    window.addEventListener('keydown', onKey);
    window.addEventListener('mousedown', onPointerDown);
    return () => {
      window.removeEventListener('keydown', onKey);
      window.removeEventListener('mousedown', onPointerDown);
    };
  }, [openMenuId]);

  const setViewMode = useCallback(
    (mode: ResourceBoardViewMode) => {
      setViewModeState(mode);
      (viewModeStorage ?? createLocalStorageViewModeStorage()).setViewMode(storageScopeKey, mode);
    },
    [viewModeStorage, storageScopeKey],
  );

  const enterSelectMode = useCallback(() => setSelectMode(true), []);
  const exitSelectMode = useCallback(() => {
    setSelectMode(false);
    setSelected(new Set());
  }, []);
  const toggleSelected = useCallback((id: string) => setSelected((current) => toggleSelectedId(current, id)), []);

  const toggleMenu = useCallback((id: string) => setOpenMenuId((current) => (current === id ? null : id)), []);
  const closeMenu = useCallback(() => setOpenMenuId(null), []);

  const isItemBusy = useCallback((id: string) => isActionPending(pendingKeys, id, ITEM_ACTION_KIND), [pendingKeys]);

  const remove = useCallback(
    async (id: string) => {
      setPendingKeys((current) => withPendingAction(current, id, ITEM_ACTION_KIND));
      setActionError(null);
      try {
        const ok = await port.deleteItem(id);
        // Selection pruning for a removed id is handled by the `items`-watching
        // effect above, so a single `setItems` call here is sufficient.
        if (ok) setItems((current) => current.filter((item) => item.id !== id));
      } catch {
        // A rejection here used to propagate silently to a caller that
        // discarded the promise with `void` (see `ResourceBoard.tsx`) — no
        // visible error, no reload, item still shown as present. Surface it
        // instead, matching the origin's own catch-and-report shape.
        setActionError(REMOVE_FAILED_MESSAGE);
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, ITEM_ACTION_KIND));
        setOpenMenuId((current) => (current === id ? null : current));
      }
    },
    [port],
  );

  const duplicate = useCallback(
    async (id: string) => {
      if (!port.duplicateItem) return;
      setPendingKeys((current) => withPendingAction(current, id, ITEM_ACTION_KIND));
      setActionError(null);
      try {
        const created = await port.duplicateItem(id);
        if (created) setItems((current) => [...current, created]);
      } catch {
        setActionError(DUPLICATE_FAILED_MESSAGE);
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, ITEM_ACTION_KIND));
        setOpenMenuId((current) => (current === id ? null : current));
      }
    },
    [port],
  );

  const bulkDelete = useCallback(async () => {
    const ids = [...selected];
    if (ids.length === 0) return { deleted: 0, failed: 0 };
    setBulkDeleteBusy(true);
    setPendingKeys((current) => withPendingAction(current, BULK_DELETE_SCOPE, BULK_DELETE_KIND));
    try {
      const results = await Promise.all(
        ids.map(async (id) => {
          try {
            return await port.deleteItem(id);
          } catch {
            return false;
          }
        }),
      );
      const deletedIds = new Set(ids.filter((_id, index) => results[index]));
      setItems((current) => current.filter((item) => !deletedIds.has(item.id)));
      exitSelectMode();
      const deleted = results.filter(Boolean).length;
      return { deleted, failed: results.length - deleted };
    } finally {
      setPendingKeys((current) => withoutPendingAction(current, BULK_DELETE_SCOPE, BULK_DELETE_KIND));
      setBulkDeleteBusy(false);
    }
  }, [selected, port, exitSelectMode]);

  const visibleItems = useMemo(() => sortBoardItems(filterBoardItemsByQuery(items, query), sort), [items, query, sort]);

  const kanbanColumns = useMemo(
    () =>
      groupItemsByStatus(visibleItems, statusOrder, {
        ...(params.defaultStatus !== undefined ? { defaultStatus: params.defaultStatus } : {}),
        ...(params.normalizeStatus !== undefined ? { normalizeStatus: params.normalizeStatus } : {}),
      }),
    [visibleItems, statusOrder, params.defaultStatus, params.normalizeStatus],
  );

  return {
    loading,
    error,
    actionError,
    totalCount: items.length,
    query,
    setQuery,
    sort,
    setSort,
    viewMode,
    setViewMode,
    visibleItems,
    kanbanColumns,
    selectMode,
    selected,
    enterSelectMode,
    exitSelectMode,
    toggleSelected,
    bulkDeleteBusy,
    bulkDelete,
    openMenuId,
    menuContainerRef,
    toggleMenu,
    closeMenu,
    isItemBusy,
    reload,
    remove,
    duplicate,
  };
}

export type UseWiredResourceBoardParams<TItem extends ResourceBoardItem> = {
  dependencies: ResourceBoardDependencies<TItem>;
} & Omit<UseResourceBoardParams<TItem>, 'port' | 'viewModeStorage'>;

/** Wirer: binds `port`/`viewModeStorage` from a host-supplied `dependencies`. */
export function useWiredResourceBoard<TItem extends ResourceBoardItem>(
  params: UseWiredResourceBoardParams<TItem>,
): ResourceBoardController<TItem> {
  const { dependencies, ...rest } = params;
  return useResourceBoard({
    port: dependencies.port,
    ...(dependencies.viewModeStorage !== undefined ? { viewModeStorage: dependencies.viewModeStorage } : {}),
    ...rest,
  });
}

import { useCallback, useEffect, useRef, useState } from 'react';
import { isActionPending, withoutPendingAction, withPendingAction } from '../../rules.js';
import type { ResourceRowListDependencies, ResourceRowListPort } from '../../ports.js';
import type { ResourceRowItem, ResourceRunHistoryItem } from '../../types.js';

const ROW_ACTION_KIND = 'row-action';
const LOAD_FAILED_MESSAGE = 'Failed to load items.';
const ROW_ACTION_FAILED_MESSAGE = 'Failed to complete action.';

export interface UseResourceRowListParams<TRow extends ResourceRowItem> {
  port: ResourceRowListPort<TRow>;
  /** Bumping this value re-fetches (same controlled-invalidation pattern as `useResourceBoard`). */
  refreshToken?: string | number;
}

export interface ResourceRowListController<TRow extends ResourceRowItem> {
  rows: TRow[];
  loading: boolean;
  error: string | null;
  reload: () => Promise<void>;
  isRowBusy: (id: string) => boolean;
  /**
   * Runs an arbitrary host-supplied action for `id` (TasksView's
   * run/edit/pause-resume/delete buttons dispatch through this — this
   * primitive never hardcodes their semantics, see `ports.ts`), tracking
   * busy state for the duration and, on success, reloading the row list and
   * — if `id` is the currently-expanded row — its run history too (mirrors
   * TasksView's own `runNow` bumping `historyTick` after a successful run).
   * A rejection from `run` propagates to the caller and does NOT reload.
   */
  dispatchRowAction: (id: string, run: () => Promise<void> | void) => Promise<void>;
  /**
   * Set when the most recent `dispatchRowAction` call's `run()` rejected —
   * a rejection still propagates to the caller (see `dispatchRowAction`'s
   * own doc comment), but a caller that fires-and-forgets it (as
   * `ResourceRowList.tsx`'s `onRowAction` does) needs a visible surface too,
   * matching real OD `TasksView.tsx`'s own shared `error` state set by every
   * one of `runNow`/`togglePaused`/`remove`'s catch clauses. Cleared at the
   * start of the next `dispatchRowAction` call.
   */
  actionError: string | null;
  /** Whether any row can expand at all — derived from `port.fetchRowHistory` being present. */
  canExpandHistory: boolean;
  expandedRowId: string | null;
  historyLoadingRowId: string | null;
  historyByRowId: Record<string, ResourceRunHistoryItem[] | undefined>;
  /** Expands `id` (fetching fresh history every time, matching TasksView's own re-fetch-on-every-expand behavior) or collapses it if already expanded. No-ops when the port has no `fetchRowHistory`. */
  toggleExpand: (id: string) => void;
}

export function useResourceRowList<TRow extends ResourceRowItem>(
  params: UseResourceRowListParams<TRow>,
): ResourceRowListController<TRow> {
  const { port, refreshToken } = params;
  const [rows, setRows] = useState<TRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [actionError, setActionError] = useState<string | null>(null);
  const [pendingKeys, setPendingKeys] = useState<ReadonlySet<string>>(new Set());
  const [expandedRowId, setExpandedRowId] = useState<string | null>(null);
  const [historyLoadingRowId, setHistoryLoadingRowId] = useState<string | null>(null);
  const [historyByRowId, setHistoryByRowId] = useState<Record<string, ResourceRunHistoryItem[] | undefined>>({});
  // Per-row history request generation, so an older, slower fetch that
  // resolves AFTER a newer one for the SAME row (collapse then re-expand
  // before the first call settled) can detect it's stale and skip
  // committing its result/loading-flag update over the newer call's.
  const historyRequestSeqRef = useRef<Record<string, number>>({});

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const fetched = await port.fetchRows();
      setRows(fetched);
      setError(null);
    } catch {
      setError(LOAD_FAILED_MESSAGE);
    } finally {
      setLoading(false);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port]);

  useEffect(() => {
    void reload();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port, refreshToken]);

  const isRowBusy = useCallback((id: string) => isActionPending(pendingKeys, id, ROW_ACTION_KIND), [pendingKeys]);

  const fetchHistoryFor = useCallback(
    async (id: string) => {
      // Non-null: every call site (`toggleExpand` below, and
      // `dispatchRowAction`'s post-action history refresh) only reaches this
      // function when `port.fetchRowHistory` is known to exist —
      // `toggleExpand` guards it directly before calling this, and
      // `dispatchRowAction` only calls this when `id === expandedRowId`,
      // which can only ever have been set by that same guarded `toggleExpand`.
      const seq = (historyRequestSeqRef.current[id] ?? 0) + 1;
      historyRequestSeqRef.current[id] = seq;
      const isStale = () => historyRequestSeqRef.current[id] !== seq;
      setHistoryLoadingRowId(id);
      try {
        const items = await port.fetchRowHistory!(id);
        // A newer request for this SAME row started (and possibly already
        // resolved) after this one — e.g. collapse then re-expand before
        // this call settled. Committing this stale result now would
        // overwrite the newer, already-committed history.
        if (isStale()) return;
        setHistoryByRowId((current) => ({ ...current, [id]: items }));
      } catch {
        // Real OD `TasksView.tsx`'s history fetch (line ~1044-1062) catches
        // a failure to an empty result rather than leaving `items`
        // `undefined` forever (which renders as permanent "Loading…" — see
        // `ResourceRunHistoryList.tsx`'s `items === undefined` check).
        if (isStale()) return;
        setHistoryByRowId((current) => ({ ...current, [id]: [] }));
      } finally {
        // A newer fetch for a DIFFERENT row (started after this one, e.g. the
        // user switched which row is expanded before this call resolved)
        // must not clobber that newer row's loading flag when this call
        // finally settles — only clear it if we're still the most recent one
        // for BOTH this row id and this specific request generation (an
        // older, still-in-flight request for the same row must not clear
        // the flag out from under a newer request that hasn't settled yet).
        setHistoryLoadingRowId((current) => (current === id && !isStale() ? null : current));
      }
    },
    [port],
  );

  const toggleExpand = useCallback(
    (id: string) => {
      if (!port.fetchRowHistory) return;
      setExpandedRowId((current) => {
        const next = current === id ? null : id;
        if (next) void fetchHistoryFor(id);
        return next;
      });
    },
    [port, fetchHistoryFor],
  );

  const dispatchRowAction = useCallback(
    async (id: string, run: () => Promise<void> | void) => {
      setPendingKeys((current) => withPendingAction(current, id, ROW_ACTION_KIND));
      setActionError(null);
      try {
        await run();
        await reload();
        if (id === expandedRowId) await fetchHistoryFor(id);
      } catch (err) {
        // A rejection still propagates to the caller (documented contract,
        // see this controller's `dispatchRowAction` doc comment and its
        // dedicated regression test) — `ResourceRowList.tsx`'s orchestrator
        // used to fire this with `void`, which discards the return value
        // WITHOUT attaching a rejection handler, leaving both an unhandled
        // rejection and no visible error. Recording `actionError` here
        // gives a fire-and-forget caller a real surface to render, while
        // re-throwing preserves the "propagates and does not reload"
        // contract for a caller that awaits/catches it directly.
        setActionError(ROW_ACTION_FAILED_MESSAGE);
        throw err;
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, ROW_ACTION_KIND));
      }
    },
    [reload, expandedRowId, fetchHistoryFor],
  );

  return {
    rows,
    loading,
    error,
    actionError,
    reload,
    isRowBusy,
    dispatchRowAction,
    canExpandHistory: Boolean(port.fetchRowHistory),
    expandedRowId,
    historyLoadingRowId,
    historyByRowId,
    toggleExpand,
  };
}

export type UseWiredResourceRowListParams<TRow extends ResourceRowItem> = {
  dependencies: ResourceRowListDependencies<TRow>;
} & Omit<UseResourceRowListParams<TRow>, 'port'>;

export function useWiredResourceRowList<TRow extends ResourceRowItem>(
  params: UseWiredResourceRowListParams<TRow>,
): ResourceRowListController<TRow> {
  const { dependencies, ...rest } = params;
  return useResourceRowList({ port: dependencies.port, ...rest });
}

/**
 * A lightweight, non-canvas React stand-in for `@excalidraw/excalidraw`,
 * used by this feature's own tests (and available to a host's tests too).
 * Real Excalidraw is a canvas-heavy third-party library — mounting it in
 * jsdom to test *our* dirty/save/export/DOM-shim logic would be slow and
 * largely untestable anyway (jsdom has no real canvas). This fake renders
 * just enough DOM (matching toolbar `data-testid`s, a menu-trigger, a
 * top-right-UI slot, and the `children` MainMenu) to exercise every hook
 * and the DOM-enhancement toolkit end-to-end.
 *
 * Lives under `react/` rather than at the feature's top-level
 * `dependencies.ts` (a deliberate exception to the "dependencies.ts has zero
 * React import" convention): the thing being faked is *itself* a React
 * component, so its fake unavoidably needs JSX too.
 */
import { useEffect, useRef } from 'react';
import type { ReactNode } from 'react';
import type { SketchEditorDependencies, SketchEditorEnginePort, SketchMainMenuComponent } from '../ports.js';

let fakeElementCounter = 0;

interface FakeExcalidrawInitialData {
  elements?: unknown[];
  appState?: Record<string, unknown>;
  files?: Record<string, unknown>;
}

interface FakeExcalidrawProps {
  initialData?: FakeExcalidrawInitialData;
  excalidrawAPI?: (api: unknown) => void;
  onChange?: (elements: unknown[], appState: Record<string, unknown>, files: Record<string, unknown>) => void;
  renderTopRightUI?: () => ReactNode;
  name?: string;
  /** Real Excalidraw re-themes its own canvas off this prop with nothing
   *  else in the DOM to observe — surfaced here as `data-theme` so a test
   *  driving `theme` through (e.g. via a `useSketchTheme` override) has
   *  something to actually assert on. */
  theme?: string;
  children?: ReactNode;
}

function FakeExcalidraw({ initialData, excalidrawAPI, onChange, renderTopRightUI, name, theme, children }: FakeExcalidrawProps) {
  const elementsRef = useRef<unknown[]>((initialData?.elements ?? []).slice());
  const appStateRef = useRef<Record<string, unknown>>({ ...(initialData?.appState ?? {}) });
  const filesRef = useRef<Record<string, unknown>>({ ...(initialData?.files ?? {}) });

  useEffect(() => {
    excalidrawAPI?.({
      updateScene: (partial: { appState?: Record<string, unknown> } | undefined) => {
        if (partial?.appState) appStateRef.current = { ...appStateRef.current, ...partial.appState };
      },
      getSceneElementsIncludingDeleted: () => elementsRef.current,
      getAppState: () => appStateRef.current,
      getFiles: () => filesRef.current,
    });
    // Mount-once, matching real Excalidraw's own imperative-handle-once contract.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fireChange = () => {
    fakeElementCounter += 1;
    const nextElements = [
      ...elementsRef.current,
      { id: `fake-element-${fakeElementCounter}`, version: fakeElementCounter, versionNonce: fakeElementCounter, isDeleted: false, type: 'rectangle' },
    ];
    elementsRef.current = nextElements;
    onChange?.(nextElements, appStateRef.current, filesRef.current);
  };

  return (
    <div data-testid="fake-excalidraw" aria-label={name} data-theme={theme}>
      <button type="button" data-testid="main-menu-trigger">
        Menu
      </button>
      <button type="button" data-testid="toolbar-selection">
        Selection
      </button>
      <button type="button" data-testid="toolbar-rectangle">
        Rectangle
      </button>
      <button type="button" data-testid="fake-excalidraw-draw" onClick={fireChange}>
        Draw
      </button>
      {renderTopRightUI ? renderTopRightUI() : null}
      {children}
    </div>
  );
}

interface FakeMainMenuItemProps {
  onClick: () => void;
  disabled?: boolean;
  icon?: ReactNode;
  children?: ReactNode;
  [key: string]: unknown;
}

function FakeMainMenuItem({ onClick, disabled, icon, children, ...rest }: FakeMainMenuItemProps) {
  return (
    <button type="button" onClick={onClick} disabled={disabled} {...rest}>
      {icon}
      {children}
    </button>
  );
}

function FakeMainMenuSeparator() {
  return <hr />;
}

function FakeMainMenuBase({ children }: { children?: ReactNode }) {
  return (
    <div data-testid="fake-main-menu" role="menu">
      {children}
    </div>
  );
}

const FakeMainMenu = Object.assign(FakeMainMenuBase, {
  Item: FakeMainMenuItem,
  Separator: FakeMainMenuSeparator,
  DefaultItems: {
    SearchMenu: () => <div data-testid="fake-search-menu" />,
    Help: () => <div data-testid="fake-help-menu" />,
    ChangeCanvasBackground: () => <div data-testid="fake-change-bg" />,
  },
}) as unknown as SketchMainMenuComponent;

export function createFakeSketchEditorEngine(overrides: Partial<SketchEditorEnginePort> = {}): SketchEditorEnginePort {
  return {
    Excalidraw: FakeExcalidraw as unknown as SketchEditorEnginePort['Excalidraw'],
    MainMenu: FakeMainMenu,
    exportToBlob: async () => new Blob(['fake-exported-image'], { type: 'image/png' }),
    ...overrides,
  };
}

export function createFakeSketchEditorDependencies(overrides: Partial<SketchEditorEnginePort> = {}): SketchEditorDependencies {
  return { engine: createFakeSketchEditorEngine(overrides) };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { DRAFT_TEST_SCOPE } from '../../constants.js';
import type { SourceConfigDependencies, SourceConfigPort } from '../../ports.js';
import {
  isActionPending,
  removeSourceById,
  updateSourceById,
  upsertSourceById,
  withoutPendingAction,
  withPendingAction,
} from '../../rules.js';
import type {
  SourceActionKind,
  SourceConfigItem,
  SourceFieldValues,
  SourceTestResult,
  SourceUpdateInput,
} from '../../types.js';

export interface SourceConfigListCapabilities {
  canRefresh: boolean;
  canSetTrust: boolean;
  canTest: boolean;
  canUpdate: boolean;
}

export interface UseSourceConfigListParams<TSource extends SourceConfigItem> {
  port: SourceConfigPort<TSource>;
}

export interface SourceConfigListController<TSource extends SourceConfigItem> {
  sources: TSource[];
  loading: boolean;
  error: string | null;
  pendingKeys: ReadonlySet<string>;
  testResults: Record<string, SourceTestResult>;
  capabilities: SourceConfigListCapabilities;
  isPending: (id: string, kind: SourceActionKind) => boolean;
  reload: () => Promise<void>;
  addSourceToList: (source: TSource) => void;
  remove: (id: string) => Promise<void>;
  refresh: (id: string) => Promise<void>;
  setTrust: (id: string, trust: string) => Promise<void>;
  /**
   * `id === undefined` tests the add-form's still-unsaved draft (the byok
   * "test before save" flow — see `ports.ts`'s `testSource` doc comment);
   * pending/result state for that case is tracked under
   * {@link DRAFT_TEST_SCOPE} instead of a real item id.
   */
  test: (id: string | undefined, draft?: SourceFieldValues) => Promise<void>;
  /**
   * Patches an existing source's `label`/`enabled`/`fields` (see `ports.ts`'s
   * `updateSource` doc comment). No-op when the port has no `updateSource`.
   *
   * **Passes `patch` through unvalidated, deliberately** — this hook is given a
   * `port` and no `fieldSpecs`, so it has nothing to validate against. The
   * shipped edit UI (`SourceConfigItemCard`) runs `validateSourceDraft` before
   * calling this, the same check the add form runs; a host driving this method
   * directly owns that check itself, exactly as `validateSourceDraft`'s own doc
   * says for `addSource`. Stated here because the gap used to be silent: the
   * edit path ran no validation at any layer.
   */
  update: (id: string, patch: SourceUpdateInput) => Promise<void>;
}

const LOAD_FAILED_MESSAGE = 'Failed to load sources.';

/**
 * Loads a source list from the injected port and exposes per-item
 * refresh/remove/trust-change/test actions, each tracked independently via
 * `pendingKeys` (see `rules.ts`'s `pendingActionKey`) so one card's in-flight
 * action never disables an unrelated card. `capabilities` is derived from
 * which optional port methods the host actually implements — the React
 * layer never needs a separate set of boolean feature flags to keep in sync
 * with the port.
 */
export function useSourceConfigList<TSource extends SourceConfigItem>(
  params: UseSourceConfigListParams<TSource>,
): SourceConfigListController<TSource> {
  const { port } = params;
  const [sources, setSources] = useState<TSource[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [pendingKeys, setPendingKeys] = useState<ReadonlySet<string>>(new Set());
  const [testResults, setTestResults] = useState<Record<string, SourceTestResult>>({});

  const reload = useCallback(async () => {
    setLoading(true);
    try {
      const fetched = await port.fetchSources();
      setSources(fetched);
      setError(null);
    } catch {
      setError(LOAD_FAILED_MESSAGE);
    } finally {
      setLoading(false);
    }
  }, [port]);

  useEffect(() => {
    void reload();
    // `reload` intentionally excluded: it's `port`-derived and re-running it
    // on every `reload` identity change would just mean "port changed",
    // which the `[port]` dep below already covers via `reload`'s own
    // `[port]` dependency.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [port]);

  const addSourceToList = useCallback((source: TSource) => {
    setSources((current) => upsertSourceById(current, source));
  }, []);

  const remove = useCallback(
    async (id: string) => {
      setPendingKeys((current) => withPendingAction(current, id, 'remove'));
      try {
        const ok = await port.removeSource(id);
        if (ok) setSources((current) => removeSourceById(current, id));
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, 'remove'));
      }
    },
    [port],
  );

  const refresh = useCallback(
    async (id: string) => {
      if (!port.refreshSource) return;
      setPendingKeys((current) => withPendingAction(current, id, 'refresh'));
      try {
        const refreshed = await port.refreshSource(id);
        if (refreshed) setSources((current) => updateSourceById(current, id, refreshed));
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, 'refresh'));
      }
    },
    [port],
  );

  const setTrust = useCallback(
    async (id: string, trust: string) => {
      if (!port.setTrust) return;
      setPendingKeys((current) => withPendingAction(current, id, 'trust'));
      try {
        const updated = await port.setTrust(id, trust);
        if (updated) setSources((current) => updateSourceById(current, id, updated));
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, 'trust'));
      }
    },
    [port],
  );

  const test = useCallback(
    async (id: string | undefined, draft?: SourceFieldValues) => {
      if (!port.testSource) return;
      const key = id ?? DRAFT_TEST_SCOPE;
      setPendingKeys((current) => withPendingAction(current, key, 'test'));
      try {
        const result = await port.testSource(id, draft);
        setTestResults((current) => ({ ...current, [key]: result }));
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, key, 'test'));
      }
    },
    [port],
  );

  const update = useCallback(
    async (id: string, patch: SourceUpdateInput) => {
      if (!port.updateSource) return;
      setPendingKeys((current) => withPendingAction(current, id, 'update'));
      try {
        const updated = await port.updateSource(id, patch);
        if (updated) setSources((current) => updateSourceById(current, id, updated));
      } finally {
        setPendingKeys((current) => withoutPendingAction(current, id, 'update'));
      }
    },
    [port],
  );

  const capabilities = useMemo<SourceConfigListCapabilities>(
    () => ({
      canRefresh: Boolean(port.refreshSource),
      canSetTrust: Boolean(port.setTrust),
      canTest: Boolean(port.testSource),
      canUpdate: Boolean(port.updateSource),
    }),
    [port],
  );

  const isPending = useCallback((id: string, kind: SourceActionKind) => isActionPending(pendingKeys, id, kind), [pendingKeys]);

  return {
    sources,
    loading,
    error,
    pendingKeys,
    testResults,
    capabilities,
    isPending,
    reload,
    addSourceToList,
    remove,
    refresh,
    setTrust,
    test,
    update,
  };
}

export type UseWiredSourceConfigListParams<TSource extends SourceConfigItem> = {
  dependencies: SourceConfigDependencies<TSource>;
};

/**
 * Wirer: binds `port` from a host-supplied `dependencies`. Unlike
 * `features/asset-grid/`'s `useWiredAssetGridData`, `dependencies` here has
 * no zero-config default — see `dependencies.ts`'s file-level comment for
 * why a generic `TSource` can't have a synthesizable fallback `createSource`.
 */
export function useWiredSourceConfigList<TSource extends SourceConfigItem>(
  params: UseWiredSourceConfigListParams<TSource>,
): SourceConfigListController<TSource> {
  return useSourceConfigList({ port: params.dependencies.port });
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type KeyboardEvent, type RefObject } from 'react';
import { useDismissOnOutsideOrEscape } from '../../../../browser/index.js';
import { ALL_KIND_FILTER } from '../../constants.js';
import {
  clampAnchoredPosition,
  clampSelection,
  filterFiles,
  filterTabs,
  nextSelected,
  presentKinds,
  resolveSelection,
} from '../../rules.js';
import type {
  TabLauncherAction,
  TabLauncherPosition,
  TabLauncherResultItem,
  TabLauncherTrackEvent,
} from '../../types.js';

export interface UseTabLauncherMenuOptions<TActionCtx = void> {
  /** The "+" button (or similar) the menu is anchored to, for fixed positioning. Menu stays closed (renders nothing) while null. */
  anchor: HTMLElement | null;
  files: readonly TabLauncherResultItem[];
  tabs?: readonly TabLauncherResultItem[];
  /** "Create new" actions shown above the search results. */
  actions?: readonly TabLauncherAction<TActionCtx>[];
  /** Context passed to every action's `run`. Only needed when `actions` is non-empty. */
  actionContext?: TActionCtx;
  onOpenFile: (item: TabLauncherResultItem) => void;
  onOpenTab?: (item: TabLauncherResultItem) => void;
  onTrack?: (event: TabLauncherTrackEvent) => void;
  onClose: () => void;
}

export interface TabLauncherMenuController<TActionCtx = void> {
  containerRef: RefObject<HTMLDivElement | null>;
  position: TabLauncherPosition | null;
  query: string;
  setQuery: (query: string) => void;
  kindFilter: string;
  setKindFilter: (kind: string) => void;
  presentKinds: string[];
  fileResults: TabLauncherResultItem[];
  tabResults: TabLauncherResultItem[];
  actions: readonly TabLauncherAction<TActionCtx>[];
  selected: number;
  setSelected: (index: number) => void;
  selectFile: (item: TabLauncherResultItem) => void;
  selectTab: (item: TabLauncherResultItem) => void;
  runAction: (action: TabLauncherAction<TActionCtx>) => void;
  handleInputKeyDown: (event: KeyboardEvent<HTMLInputElement>) => void;
}

/**
 * Owns anchored viewport-clamped positioning (recalculated on scroll/resize),
 * outside-click/Escape dismissal, file+tab search/kind-filter state, and
 * keyboard navigation (arrow-key selection spanning the "create new" actions,
 * file results, and tab results as one flat list; Enter opens/runs whatever
 * is selected) for a "+"-button launcher dropdown.
 */
export function useTabLauncherMenu<TActionCtx = void>(
  options: UseTabLauncherMenuOptions<TActionCtx>,
): TabLauncherMenuController<TActionCtx> {
  const {
    anchor,
    files,
    tabs = [],
    actions = [],
    onOpenFile,
    onOpenTab,
    onTrack,
    onClose,
  } = options;
  const containerRef = useRef<HTMLDivElement | null>(null);
  const [query, setQuery] = useState('');
  const [kindFilter, setKindFilterState] = useState<string>(ALL_KIND_FILTER);
  const [selected, setSelected] = useState(0);
  const [position, setPosition] = useState<TabLauncherPosition | null>(null);

  useLayoutEffect(() => {
    if (!anchor) return undefined;
    const update = () => {
      const rect = anchor.getBoundingClientRect();
      setPosition(clampAnchoredPosition(rect, window.innerWidth));
    };
    update();
    window.addEventListener('scroll', update, true);
    window.addEventListener('resize', update);
    return () => {
      window.removeEventListener('scroll', update, true);
      window.removeEventListener('resize', update);
    };
  }, [anchor]);

  useDismissOnOutsideOrEscape({ onDismiss: onClose }, { containerRef });

  const kinds = useMemo(() => presentKinds(files), [files]);
  const fileResults = useMemo(() => filterFiles(files, query, kindFilter), [files, query, kindFilter]);
  const tabResults = useMemo(() => filterTabs(tabs, query, kindFilter), [tabs, query, kindFilter]);
  const selectableCount = fileResults.length + tabResults.length;

  useEffect(() => {
    setSelected((current) => clampSelection(current, selectableCount));
  }, [selectableCount]);

  useEffect(() => {
    onTrack?.({ type: 'open' });
    // Fires once when the menu mounts (it only mounts while open) —
    // deliberately not re-fired on every onTrack identity change.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const setKindFilter = useCallback((kind: string) => {
    onTrack?.({ type: 'filter', kind });
    setKindFilterState(kind);
  }, [onTrack]);

  const selectFile = useCallback((item: TabLauncherResultItem) => {
    onTrack?.({ type: 'select-file', item });
    onOpenFile(item);
    onClose();
  }, [onTrack, onOpenFile, onClose]);

  const selectTab = useCallback((item: TabLauncherResultItem) => {
    onTrack?.({ type: 'select-tab', item });
    onOpenTab?.(item);
    onClose();
  }, [onTrack, onOpenTab, onClose]);

  const runAction = useCallback((action: TabLauncherAction<TActionCtx>) => {
    onTrack?.({ type: 'run-action', actionId: action.id });
    action.run(options.actionContext as TActionCtx);
    onClose();
  }, [onTrack, onClose, options.actionContext]);

  const handleInputKeyDown = useCallback((event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      setSelected((current) => nextSelected(current, selectableCount, 1));
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      setSelected((current) => nextSelected(current, selectableCount, -1));
      return;
    }
    if (event.key !== 'Enter') return;
    event.preventDefault();
    if (selectableCount === 0) {
      // No file/tab matches the query but "create new" actions exist —
      // Enter triggers the first one so the keyboard path is never a dead end.
      const firstAction = actions[0];
      if (firstAction) runAction(firstAction);
      return;
    }
    const resolved = resolveSelection(selected, fileResults.length);
    if (resolved.zone === 'file') {
      const file = fileResults[resolved.index];
      if (file) selectFile(file);
      return;
    }
    const tab = tabResults[resolved.index];
    if (tab) selectTab(tab);
  }, [selectableCount, selected, fileResults, tabResults, actions, selectFile, selectTab, runAction]);

  return {
    containerRef,
    position,
    query,
    setQuery,
    kindFilter,
    setKindFilter,
    presentKinds: kinds,
    fileResults,
    tabResults,
    actions,
    selected,
    setSelected,
    selectFile,
    selectTab,
    runAction,
    handleInputKeyDown,
  };
}

import { useCallback, useEffect, useMemo, useRef, type RefObject } from 'react';
import { extractMarkdownBlockLines } from '../../../../utils/markdown-scroll-sync.js';
import {
  computeSplitPaneScrollTarget,
  measureEditorBlockOffsets,
  measurePreviewBlockOffsets,
} from '../../rules.js';
import type { MarkdownScrollPane, MarkdownSplitPaneMode } from '../../types.js';

export interface UseMarkdownScrollSyncOptions {
  mode: MarkdownSplitPaneMode;
  sourceText: string;
  editorRef: RefObject<HTMLTextAreaElement | null>;
  previewRef: RefObject<HTMLElement | null>;
  /** CSS selector for the rendered preview's root element inside
   *  `previewRef.current`, forwarded to `measurePreviewBlockOffsets`. */
  previewSelector?: string | undefined;
  /** Bump this (e.g. pass the rendered HTML string) whenever the preview's
   *  rendered content changes, so a resync runs even though `sourceText`
   *  itself didn't move (matches the source's own `[html, mode]` effect
   *  dependency). */
  resyncKey?: unknown;
}

export interface UseMarkdownScrollSyncResult {
  handleEditorScroll: () => void;
  handlePreviewScroll: () => void;
  activatePane: (pane: MarkdownScrollPane) => void;
}

/**
 * Keeps a split editor/preview pane aligned while scrolling either side, by
 * anchoring on each top-level markdown block's source line vs. its rendered
 * DOM element (falling back to plain ratio-sync when block anchors can't be
 * measured). This is the generic mechanism behind the source component's
 * split-pane markdown viewer — ported without its artifact-status gate, its
 * autosave/upload pipeline, and its shiki-based syntax highlighting (all
 * genuinely OD/product-specific; see `packages/ui/archived provenance ledger`).
 */
export function useMarkdownScrollSync(options: UseMarkdownScrollSyncOptions): UseMarkdownScrollSyncResult {
  const { mode, sourceText, editorRef, previewRef, previewSelector, resyncKey } = options;

  const editorBlockOffsetsRef = useRef<{ width: number; offsets: number[] } | null>(null);
  const scrollSyncFrameRef = useRef<number | null>(null);
  const programmaticScrollClearFrameRef = useRef<number | null>(null);
  const pendingScrollSyncRef = useRef<{ sourcePane: MarkdownScrollPane; targetPane: MarkdownScrollPane } | null>(null);
  const programmaticScrollRef = useRef<{ pane: MarkdownScrollPane; top: number } | null>(null);
  const activePaneRef = useRef<MarkdownScrollPane>('editor');

  const blockLines = useMemo(() => extractMarkdownBlockLines(sourceText), [sourceText]);

  useEffect(() => {
    editorBlockOffsetsRef.current = null;
  }, [sourceText]);

  useEffect(() => {
    return () => {
      if (scrollSyncFrameRef.current !== null) cancelAnimationFrame(scrollSyncFrameRef.current);
      if (programmaticScrollClearFrameRef.current !== null) cancelAnimationFrame(programmaticScrollClearFrameRef.current);
    };
  }, []);

  const clearProgrammaticScrollSoon = useCallback(() => {
    if (programmaticScrollClearFrameRef.current !== null) {
      cancelAnimationFrame(programmaticScrollClearFrameRef.current);
    }
    programmaticScrollClearFrameRef.current = requestAnimationFrame(() => {
      programmaticScrollClearFrameRef.current = requestAnimationFrame(() => {
        programmaticScrollRef.current = null;
        programmaticScrollClearFrameRef.current = null;
      });
    });
  }, []);

  const getEditorBlockOffsets = useCallback((): number[] | null => {
    const editor = editorRef.current;
    if (!editor || blockLines.length === 0) return null;
    const width = editor.clientWidth;
    const cached = editorBlockOffsetsRef.current;
    if (cached && cached.width === width && cached.offsets.length === blockLines.length) {
      return cached.offsets;
    }
    const offsets = measureEditorBlockOffsets(editor, blockLines, sourceText);
    if (!offsets) return null;
    editorBlockOffsetsRef.current = { width, offsets };
    return offsets;
  }, [blockLines, editorRef, sourceText]);

  const applyScrollSync = useCallback(
    (sourcePane: MarkdownScrollPane, targetPane: MarkdownScrollPane) => {
      const source = sourcePane === 'editor' ? editorRef.current : previewRef.current;
      const target = targetPane === 'editor' ? editorRef.current : previewRef.current;
      if (mode !== 'split' || !source || !target) return;
      const editorOffsets = getEditorBlockOffsets();
      const previewOffsets = editorOffsets ? measurePreviewBlockOffsets(previewRef.current!, blockLines.length, previewSelector) : null;
      const targetTop = computeSplitPaneScrollTarget({
        sourcePane,
        source,
        target,
        blockLineCount: blockLines.length,
        editorOffsets,
        previewOffsets,
      });
      if (Math.abs(target.scrollTop - targetTop) < 1) return;
      programmaticScrollRef.current = { pane: targetPane, top: targetTop };
      target.scrollTop = targetTop;
      clearProgrammaticScrollSoon();
    },
    [blockLines.length, clearProgrammaticScrollSoon, editorRef, getEditorBlockOffsets, mode, previewRef, previewSelector],
  );

  const scheduleScrollSync = useCallback(
    (sourcePane: MarkdownScrollPane, targetPane: MarkdownScrollPane) => {
      if (mode !== 'split') {
        pendingScrollSyncRef.current = null;
        return;
      }
      pendingScrollSyncRef.current = { sourcePane, targetPane };
      if (scrollSyncFrameRef.current !== null) return;
      scrollSyncFrameRef.current = requestAnimationFrame(() => {
        scrollSyncFrameRef.current = null;
        // `pendingScrollSyncRef.current` is always non-null here: the only
        // writers are this same callback's `{ sourcePane, targetPane }`
        // assignment two lines above (which always runs immediately before
        // a frame is requested) and the mode-effect's cleanup below, which
        // nulls it out *together with* cancelling this very
        // `scrollSyncFrameRef` frame via `cancelAnimationFrame` — so a
        // cancelled frame's callback never actually runs to observe a null
        // value. The non-null assertion exists only to satisfy
        // TypeScript's `| null` ref type, not a real runtime path.
        const pending = pendingScrollSyncRef.current!;
        pendingScrollSyncRef.current = null;
        applyScrollSync(pending.sourcePane, pending.targetPane);
      });
    },
    [applyScrollSync, mode],
  );

  const shouldIgnoreScroll = useCallback((pane: MarkdownScrollPane, element: HTMLElement): boolean => {
    const programmatic = programmaticScrollRef.current;
    if (programmatic?.pane !== pane) return false;
    if (Math.abs(element.scrollTop - programmatic.top) > 1 && activePaneRef.current === pane) {
      return false;
    }
    programmaticScrollRef.current = null;
    return true;
  }, []);

  const handleEditorScroll = useCallback(() => {
    const editor = editorRef.current;
    if (!editor || shouldIgnoreScroll('editor', editor)) return;
    activePaneRef.current = 'editor';
    scheduleScrollSync('editor', 'preview');
  }, [editorRef, scheduleScrollSync, shouldIgnoreScroll]);

  const handlePreviewScroll = useCallback(() => {
    const previewPane = previewRef.current;
    if (!previewPane || shouldIgnoreScroll('preview', previewPane)) return;
    if (activePaneRef.current !== 'preview') return;
    scheduleScrollSync('preview', 'editor');
  }, [previewRef, scheduleScrollSync, shouldIgnoreScroll]);

  const activatePane = useCallback((pane: MarkdownScrollPane) => {
    activePaneRef.current = pane;
  }, []);

  useEffect(() => {
    if (mode !== 'split') {
      if (scrollSyncFrameRef.current !== null) {
        cancelAnimationFrame(scrollSyncFrameRef.current);
        scrollSyncFrameRef.current = null;
      }
      if (programmaticScrollClearFrameRef.current !== null) {
        cancelAnimationFrame(programmaticScrollClearFrameRef.current);
        programmaticScrollClearFrameRef.current = null;
      }
      pendingScrollSyncRef.current = null;
      programmaticScrollRef.current = null;
      activePaneRef.current = 'editor';
      return;
    }
    // `activePaneRef.current` is a `MarkdownScrollPane` (never null/undefined
    // — it's initialized to `'editor'` and every writer above assigns a real
    // pane), so it's used directly rather than through a `??` fallback.
    const sourcePane = activePaneRef.current;
    const targetPane = sourcePane === 'preview' ? 'editor' : 'preview';
    scheduleScrollSync(sourcePane, targetPane);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- resyncKey intentionally re-triggers this on preview content changes.
  }, [mode, resyncKey, scheduleScrollSync]);

  return { handleEditorScroll, handlePreviewScroll, activatePane };
}

/**
 * @module react/mcp-ui/useMcpUiHost
 *
 * The Host half of the MCP Apps handshake — now backed by the REAL, official `@mcp-ui/client`
 * package (`AppRenderer`) instead of this package's own hand-rolled `postMessage` state machine.
 *
 * ## What changed, and why this file still exists at all
 *
 * The owner's decision (2026-08-18): stop hand-rolling MCP-UI client-side rendering; use
 * `@mcp-ui/client` for real. This hook and {@link ../../features/mcp-ui/sandbox-proxy.js} are that
 * swap's Host-side landing point. `useMcpUiHost`/`McpUiHost` are KEPT — same export names, same
 * subpath (`@jini-ai/ui/mcp-ui`) — because real external consumers may already import them by name;
 * see this session's report for what could and could not be held identical.
 *
 * The wire protocol did NOT change: every existing surface this package generates
 * (`surfaces/document.ts`, `surfaces/bridge.ts`, `surfaces/confirmation.ts`, `surfaces/form.ts`, …)
 * is untouched, and still speaks the same JSON-RPC-over-`postMessage` envelope to `window.parent`
 * that it always has. What makes the swap possible without touching any of those builders is
 * {@link ../../features/mcp-ui/sandbox-proxy.js}'s single-hop relay design — see that module's own
 * doc for the exact mechanism and the security tradeoff it makes.
 *
 * ## What could NOT be held identical — read before assuming parity
 *
 * - **A new REQUIRED option: {@link McpUiHostOptions.sandboxProxyUrl}.** `@mcp-ui/client`'s
 *   `AppRenderer` renders into a real, separately-served page rather than a `srcdoc` string, so
 *   every caller now has to say where that page lives. There is no sane default — see
 *   `sandbox-proxy.ts`'s doc for what has to serve it and where. This is the one addition to
 *   `McpUiHostOptions` that could not be avoided; every other field below is either preserved or a
 *   documented, deliberate reduction.
 * - **`iframeRef` is gone.** `AppRenderer` owns its own iframe internally and does not expose it.
 *   Nothing in this monorepo read `useMcpUiHost(...).iframeRef` outside `McpUiHost.tsx` itself
 *   (verified by search before this swap), so this is believed to be safe, but it is a real removal
 *   from the old `McpUiHostResult` shape, not a preserved one.
 * - **`state` is coarser.** The old hand-rolled state machine could observe
 *   `awaiting-initialize`/`awaiting-initialized` as DISTINCT states because it watched every
 *   handshake message itself. `AppRenderer` does not expose an "initialized" callback (only
 *   `onSizeChanged`, `onError`, and the imperative ref methods) — see {@link McpUiHostState}'s own
 *   doc for exactly what this hook infers instead and the one assumption that inference rests on.
 * - **`teardownAcknowledged` can no longer be genuinely tracked.** `AppRendererHandle.teardownResource()`
 *   is synchronous, fire-and-forget — `@mcp-ui/client` exposes no signal for "the View acknowledged
 *   teardown." The field is kept (so the shape still matches) but can only ever be `null` now. See
 *   {@link McpUiHostResult.teardownAcknowledged}.
 * - **`messageSource` (the test-injection seam) is gone.** There is no `postMessage` listening left
 *   in this file to inject a fake source into — `AppRenderer` owns that internally. Tests against
 *   this hook now drive real `AppRenderer` callbacks instead; see `__tests__/useMcpUiHost.test.tsx`.
 *
 * ## How a consumer uses this hook now
 *
 * `useMcpUiHost` cannot mount DOM by itself — `@mcp-ui/client`'s primitives are React COMPONENTS,
 * not a framework-free state machine a hook can drive imperatively (the old implementation could,
 * because it hand-rolled the iframe and the `postMessage` listening both). So this hook returns
 * {@link McpUiHostResult.rendererProps}: a ready-to-spread props object for `@mcp-ui/client`'s
 * `<AppRenderer>`. `McpUiHost.tsx` is the reference consumer — a caller building custom chrome
 * writes `<AppRenderer key={sessionKey} {...host.rendererProps} />` the same way `McpUiHost.tsx`
 * does, and reads `host.state`/`host.size` to build UI around it.
 */
import { useCallback, useEffect, useMemo, useRef, useState, type RefObject } from 'react';
import type { AppRendererHandle, AppRendererProps } from '@mcp-ui/client';

/**
 * Vestigial after this swap — `@mcp-ui/client` owns the sandbox-proxy-ready handshake internally on
 * a fixed, non-configurable 10s timeout this package cannot change. Kept exported (existing
 * consumers/tests reference it) and repurposed below as this hook's OWN ready-watchdog timeout,
 * which is a real, still-enforced behavior — see {@link McpUiHostOptions.initializedTimeoutMs}.
 */
export const DEFAULT_TEARDOWN_TIMEOUT_MS = 3_000;
/** How long {@link useMcpUiHost} waits for the View's first size report before giving up — see {@link McpUiHostState}. */
export const DEFAULT_INITIALIZED_TIMEOUT_MS = 4_000;

/**
 * Coarser than the old hand-rolled state machine's five states — see this module's own doc for why.
 *
 * `'ready'` is inferred from the View's FIRST `ui/notifications/size-changed` report, not observed
 * directly: `@mcp-ui/client`'s `AppRenderer` exposes no "handshake complete" callback. This is a
 * verified-true, not merely assumed, proxy for every surface `../../features/mcp-ui/surfaces/`
 * generates — `surfaces/bridge.ts`'s `onHandshakeDone` calls `reportSize()` unconditionally, so a
 * Jini-built surface always reports a size the instant it becomes ready. It is NOT a spec guarantee
 * for an arbitrary third-party View that happens to never call `ui/notifications/size-changed`.
 */
export type McpUiHostState = 'awaiting-ready' | 'ready' | 'timed-out' | 'errored' | 'torn-down';

/** One observable protocol moment. Purely informational, same as before — nothing here reads these back. */
export interface McpUiHostEvent {
  readonly direction: 'in' | 'out' | 'rejected' | 'refused' | 'timeout' | 'info';
  readonly note: string;
}

export interface McpUiToolCall {
  readonly name: string;
  readonly arguments: Readonly<Record<string, unknown>>;
}

/**
 * Executes a tool a View asked for. Unchanged from before this swap — see this hook's module doc
 * for the verified runtime guarantee that a rejection is relayed to the View as a JSON-RPC error and
 * a resolution is passed through as the `result` UNVALIDATED against any particular shape (checked
 * directly against the installed `@modelcontextprotocol/sdk`'s `Protocol._onrequest`, not assumed).
 */
export type McpUiToolCallHandler = (call: McpUiToolCall) => Promise<unknown> | unknown;

export interface McpUiHostOptions {
  /** The View document. Unchanged in meaning; no longer mounted via `srcdoc` — see this module's doc. */
  readonly html: string;
  /**
   * Where the sandbox proxy page (`../../features/mcp-ui/sandbox-proxy.js`'s `SANDBOX_PROXY_HTML`)
   * is served. NEW, and required — see this module's own doc for why there is no sane default.
   */
  readonly sandboxProxyUrl: URL;
  /**
   * Reported to `@mcp-ui/client` as this View's `toolName`. Purely a label in this package's usage
   * (no live MCP `client` is ever supplied, so `AppRenderer`'s tool/resource-fetching machinery
   * that would otherwise consume this never runs) — defaults to a generic constant when omitted.
   * A caller with a real tool name (e.g. `content_post_delete`) should pass it for clearer
   * diagnostics/telemetry on `@mcp-ui/client`'s side.
   */
  readonly toolName?: string;
  /** Changing this remounts the `<AppRenderer>` a consumer keys by it — see `McpUiHost.tsx`. */
  readonly sessionKey?: string | number;
  readonly onToolCall?: McpUiToolCallHandler;
  /** Handles `ui/open-link`. Omit and the Host refuses the request (mirrors the old behavior). */
  readonly onOpenLink?: (url: string) => void;
  readonly onSizeChanged?: (size: { readonly width: number; readonly height: number }) => void;
  readonly onEvent?: (event: McpUiHostEvent) => void;
  readonly hostInfo?: { readonly name: string; readonly version: string };
  readonly hostContext?: Readonly<Record<string, unknown>>;
  /** How long to wait for the View's first size report before {@link McpUiHostState} becomes `'timed-out'`. */
  readonly initializedTimeoutMs?: number;
}

export interface McpUiHostResult {
  readonly state: McpUiHostState;
  readonly size: { readonly width: number; readonly height: number } | null;
  /** Best-effort: notifies the View, but see {@link teardownAcknowledged} — no acknowledgement is observable anymore. */
  readonly requestTeardown: () => void;
  /**
   * Always `null` after this swap. `@mcp-ui/client`'s `AppRendererHandle.teardownResource()` is
   * synchronous and fire-and-forget; nothing in its public API reports whether a View answered.
   * Kept in this shape (rather than removed) so existing code reading it does not need an unrelated
   * type-level change; see this module's own doc for the follow-up this leaves open.
   */
  readonly teardownAcknowledged: boolean | null;
  /** Spread onto `<AppRenderer key={sessionKey ?? html} {...rendererProps} />` — see this module's own doc. */
  readonly rendererProps: AppRendererProps;
  /**
   * Pass as `ref` on that same `<AppRenderer>` element. Separate from {@link rendererProps} because
   * `ref` is not a member of `AppRendererProps` itself — `AppRenderer` is a `forwardRef` component,
   * so React types it as an addition alongside the props, not a prop.
   */
  readonly rendererRef: RefObject<AppRendererHandle | null>;
}

const DEFAULT_TOOL_NAME = 'mcp-ui-surface';

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * Runs the Host-side protocol for one View, on top of `@mcp-ui/client`'s `AppRenderer`.
 *
 * @param options - See {@link McpUiHostOptions}.
 * @returns See {@link McpUiHostResult}.
 */
export function useMcpUiHost(options: McpUiHostOptions): McpUiHostResult {
  const { html, sandboxProxyUrl, sessionKey, initializedTimeoutMs = DEFAULT_INITIALIZED_TIMEOUT_MS } = options;

  const [state, setState] = useState<McpUiHostState>('awaiting-ready');
  const [size, setSize] = useState<{ width: number; height: number } | null>(null);
  const [teardownAcknowledged] = useState<boolean | null>(null);

  const stateRef = useRef<McpUiHostState>('awaiting-ready');
  const settledRef = useRef(false);
  const handleRef = useRef<AppRendererHandle>(null);

  // Every caller-supplied callback read through a ref, same reasoning as the pre-swap
  // implementation: they are almost always inline arrow functions, and depending on them directly
  // would recreate `rendererProps`'s callbacks (and therefore remount `AppRenderer`, restarting the
  // whole handshake) on every render.
  const optionsRef = useRef(options);
  useEffect(() => {
    optionsRef.current = options;
  });

  const setStateBoth = useCallback((next: McpUiHostState) => {
    stateRef.current = next;
    setState(next);
  }, []);

  const emit = useCallback((direction: McpUiHostEvent['direction'], note: string) => {
    optionsRef.current.onEvent?.({ direction, note });
  }, []);

  const effectiveSessionKey = sessionKey ?? html;

  // The ready-watchdog. See `McpUiHostState`'s own doc for why "first size report" stands in for
  // "handshake complete" here, and this hook's module doc for why `@mcp-ui/client` itself gives us
  // no better signal to watch instead.
  useEffect(() => {
    settledRef.current = false;
    setStateBoth('awaiting-ready');
    setSize(null);
    const timer = setTimeout(() => {
      if (settledRef.current) return;
      settledRef.current = true;
      emit('timeout', `No size report from the View within ${initializedTimeoutMs}ms — treating the handshake as failed`);
      setStateBoth('timed-out');
    }, initializedTimeoutMs);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps -- effectiveSessionKey intentionally
    // stands in for both `sessionKey` and `html` (mirrors the pre-swap effect's own `[sessionKey, ...]`).
  }, [effectiveSessionKey, initializedTimeoutMs, emit, setStateBoth]);

  const handleSizeChanged = useCallback<NonNullable<AppRendererProps['onSizeChanged']>>(
    (params) => {
      if (!settledRef.current) {
        settledRef.current = true;
        emit('in', 'first size report received — treating the handshake as complete');
        setStateBoth('ready');
      }
      const next = { width: params.width ?? 0, height: params.height ?? 0 };
      setSize(next);
      optionsRef.current.onSizeChanged?.(next);
    },
    [emit, setStateBoth],
  );

  const handleError = useCallback<NonNullable<AppRendererProps['onError']>>(
    (error) => {
      emit('rejected', `AppRenderer error: ${errorMessage(error)}`);
      if (!settledRef.current) {
        settledRef.current = true;
        setStateBoth('errored');
      }
    },
    [emit, setStateBoth],
  );

  const handleCallTool = useCallback<NonNullable<AppRendererProps['onCallTool']>>(
    async (params) => {
      const handler = optionsRef.current.onToolCall;
      if (handler === undefined) {
        emit('refused', 'tools/call received but this host has no tool executor');
        throw new Error('This host executes no tools.');
      }
      const call: McpUiToolCall = {
        name: params.name,
        arguments: (params.arguments ?? {}) as Record<string, unknown>,
      };
      emit('in', `tools/call ${call.name}`);
      try {
        const result = await handler(call);
        emit('out', `tools/call ${call.name} resolved`);
        // See this hook's module doc: verified against the installed MCP SDK that a resolved
        // handler value reaches the View as the JSON-RPC `result` completely unvalidated against
        // any CallToolResult shape. This cast documents that gap; it is not a claim that `result`
        // structurally satisfies CallToolResult.
        return result as Awaited<ReturnType<NonNullable<AppRendererProps['onCallTool']>>>;
      } catch (error) {
        emit('out', `tools/call ${call.name} rejected`);
        throw error;
      }
    },
    [emit],
  );

  const handleOpenLink = useCallback<NonNullable<AppRendererProps['onOpenLink']>>(
    async ({ url }) => {
      const handler = optionsRef.current.onOpenLink;
      if (handler === undefined) {
        emit('refused', 'ui/open-link refused: no handler');
        return { isError: true };
      }
      handler(url);
      emit('out', 'ui/open-link handled');
      return {};
    },
    [emit],
  );

  const requestTeardown = useCallback(() => {
    if (stateRef.current !== 'ready') return;
    handleRef.current?.teardownResource();
    emit(
      'out',
      'requestTeardown sent (fire-and-forget — @mcp-ui/client exposes no acknowledgement signal, see module doc)',
    );
    setStateBoth('torn-down');
  }, [emit, setStateBoth]);

  const rendererProps = useMemo<AppRendererProps>(
    () => ({
      toolName: optionsRef.current.toolName ?? DEFAULT_TOOL_NAME,
      sandbox: { url: sandboxProxyUrl },
      html,
      ...(optionsRef.current.hostInfo === undefined ? {} : { hostInfo: optionsRef.current.hostInfo }),
      ...(optionsRef.current.hostContext === undefined ? {} : { hostContext: optionsRef.current.hostContext }),
      onCallTool: handleCallTool,
      onOpenLink: handleOpenLink,
      onSizeChanged: handleSizeChanged,
      onError: handleError,
      // eslint-disable-next-line react-hooks/exhaustive-deps -- optionsRef.current.toolName/hostInfo/hostContext
      // are read once per `html`/`sandboxProxyUrl` change intentionally, same ref-read pattern as the rest of this hook.
    }),
    [html, sandboxProxyUrl, handleCallTool, handleOpenLink, handleSizeChanged, handleError],
  );

  return { state, size, requestTeardown, teardownAcknowledged, rendererProps, rendererRef: handleRef };
}

/**
 * Headless controller for the preview-modal shell — all state/effects,
 * no JSX. `react/components/PreviewModalShell.tsx` is the presentational
 * consumer.
 *
 * Origin: `apps/web/src/components/PreviewModal.tsx`'s component body (the
 * generic-chrome subset — see `../../archived provenance ledger`'s classification). The
 * merged Share/Export popover's state (`templateShareOpen`/
 * `copyShareFeedback`/`socialShareTargets`/...) is deliberately not ported
 * here; that block is OD-specific and out of scope for this shell.
 */
import { useEffect, useMemo, useRef, useState, type RefObject } from 'react';
import { computeScalerStyle, computeStageScale, findActiveView, resolveInitialViewId, type PreviewModalViewLike } from '../../rules.js';
import type { PreviewModalScalerStyle } from '../../types.js';

export interface UsePreviewModalShellOptions<V extends PreviewModalViewLike> {
  views: readonly V[];
  initialViewId?: string | undefined;
  /** Fired whenever the active view changes — including on first mount with `initialViewId` — so the host can drive lazy fetches. */
  onView?: ((viewId: string) => void) | undefined;
  onClose: () => void;
  sidebarDefaultOpen?: boolean | undefined;
  sidebarOnToggle?: ((open: boolean) => void) | undefined;
  /** When this changes while the sidebar is open, `sidebarOnToggle` re-fires so the host can prime a fresh fetch for the new content. */
  sidebarContentKey?: string | number | undefined;
  /** Logical viewport width the content is assumed to render at before being scaled to fit the stage. Defaults to 1280. */
  designWidth?: number | undefined;
}

export interface PreviewModalShellController<V extends PreviewModalViewLike> {
  activeId: string;
  setActiveId: (id: string) => void;
  activeView: V | undefined;
  fullscreen: boolean;
  enterFullscreen: () => void;
  exitFullscreen: () => void;
  sidebarOpen: boolean;
  setSidebarOpen: (next: boolean) => void;
  primaryMenuOpen: boolean;
  setPrimaryMenuOpen: (next: boolean | ((prev: boolean) => boolean)) => void;
  stageSize: { w: number; h: number };
  scale: number;
  scalerStyle: PreviewModalScalerStyle;
  stageRef: RefObject<HTMLDivElement | null>;
  stageFrameRef: RefObject<HTMLDivElement | null>;
  primaryMenuRef: RefObject<HTMLDivElement | null>;
}

export function usePreviewModalShell<V extends PreviewModalViewLike>(
  options: UsePreviewModalShellOptions<V>,
): PreviewModalShellController<V> {
  const {
    views,
    initialViewId,
    onView,
    onClose,
    sidebarDefaultOpen = false,
    sidebarOnToggle,
    sidebarContentKey,
    designWidth = 1280,
  } = options;

  const initial = resolveInitialViewId(views, initialViewId);
  const [activeId, setActiveId] = useState<string>(initial);
  const [fullscreen, setFullscreen] = useState(false);
  const [sidebarOpen, setSidebarOpen] = useState<boolean>(sidebarDefaultOpen);
  const [primaryMenuOpen, setPrimaryMenuOpen] = useState(false);
  const [stageSize, setStageSize] = useState<{ w: number; h: number }>({ w: 0, h: 0 });

  const stageRef = useRef<HTMLDivElement | null>(null);
  const stageFrameRef = useRef<HTMLDivElement | null>(null);
  const primaryMenuRef = useRef<HTMLDivElement | null>(null);

  // Captured in a ref so the lazy-load effect below depends only on
  // sidebarOpen/sidebarContentKey — a fresh `sidebarOnToggle` identity on
  // every host render would otherwise re-fire the load every render.
  const sidebarToggleRef = useRef(sidebarOnToggle);
  sidebarToggleRef.current = sidebarOnToggle;

  useEffect(() => {
    sidebarToggleRef.current?.(sidebarOpen);
  }, [sidebarOpen, sidebarContentKey]);

  useEffect(() => {
    onView?.(activeId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeId, onView]);

  // Close on Escape. In fullscreen, the first Escape exits fullscreen
  // instead of dismissing the whole modal.
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== 'Escape') return;
      if (fullscreen) {
        setFullscreen(false);
        return;
      }
      onClose();
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, [onClose, fullscreen]);

  // Mirror native fullscreen state into React so a browser-level Escape
  // (consumed by the browser, not always delivered as a keydown) still
  // clears the `fullscreen` flag in lock-step.
  useEffect(() => {
    const onFsChange = () => {
      if (!document.fullscreenElement) setFullscreen(false);
    };
    document.addEventListener('fullscreenchange', onFsChange);
    return () => document.removeEventListener('fullscreenchange', onFsChange);
  }, []);

  // Outside-click / Escape dismissal for the split-button's secondary menu.
  useEffect(() => {
    if (!primaryMenuOpen) return undefined;
    const onDoc = (e: MouseEvent) => {
      const target = e.target as Node;
      if (!primaryMenuRef.current?.contains(target)) setPrimaryMenuOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setPrimaryMenuOpen(false);
    };
    document.addEventListener('mousedown', onDoc);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDoc);
      document.removeEventListener('keydown', onKey);
    };
  }, [primaryMenuOpen]);

  // Lock body scroll while mounted.
  useEffect(() => {
    const prev = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    return () => {
      document.body.style.overflow = prev;
    };
  }, []);

  // Track the stage size so content can render at a fixed logical width and
  // scale to fit. ResizeObserver is missing from some environments (jsdom,
  // older embedded WebViews) — guarded with a window-resize fallback so the
  // shell still mounts, it just loses element-level resize tracking.
  useEffect(() => {
    const el = stageFrameRef.current;
    if (!el) return undefined;
    // clientWidth/Height (layout box), not getBoundingClientRect (transform-
    // aware and lands short during the modal's own entrance animation).
    const measure = () => setStageSize({ w: el.clientWidth, h: el.clientHeight });
    measure();
    // A synchronous first measure can land before the modal's entrance
    // layout settles; re-measure next frame so the scaler fills the stage.
    const raf = requestAnimationFrame(measure);
    if (typeof ResizeObserver !== 'undefined') {
      const ro = new ResizeObserver(measure);
      ro.observe(el);
      return () => {
        cancelAnimationFrame(raf);
        ro.disconnect();
      };
    }
    window.addEventListener('resize', measure);
    return () => {
      cancelAnimationFrame(raf);
      window.removeEventListener('resize', measure);
    };
  }, []);

  // Re-measure when the sidebar toggles (the stage width jumps) or the
  // active view changes, so `scale` tracks the current stage width instead
  // of a stale value from the previous layout.
  useEffect(() => {
    const el = stageFrameRef.current;
    if (!el) return undefined;
    const raf = requestAnimationFrame(() => {
      setStageSize({ w: el.clientWidth, h: el.clientHeight });
    });
    return () => cancelAnimationFrame(raf);
  }, [sidebarOpen, activeId]);

  const activeView = findActiveView(views, activeId);
  const scale = computeStageScale(stageSize.w, designWidth);
  const scalerStyle = useMemo(
    () => computeScalerStyle(stageSize, designWidth, scale),
    [scale, stageSize.w, stageSize.h, designWidth],
  );

  function enterFullscreen() {
    const el = stageRef.current;
    if (el && typeof el.requestFullscreen === 'function') {
      el.requestFullscreen()
        .then(() => setFullscreen(true))
        .catch(() => setFullscreen(true));
    } else {
      setFullscreen(true);
    }
  }

  function exitFullscreen() {
    if (document.fullscreenElement && document.exitFullscreen) {
      document.exitFullscreen().catch(() => {});
    }
    setFullscreen(false);
  }

  return {
    activeId,
    setActiveId,
    activeView,
    fullscreen,
    enterFullscreen,
    exitFullscreen,
    sidebarOpen,
    setSidebarOpen,
    primaryMenuOpen,
    setPrimaryMenuOpen,
    stageSize,
    scale,
    scalerStyle,
    stageRef,
    stageFrameRef,
    primaryMenuRef,
  };
}

/**
 * Resolves an {@link ArtifactFile} against a {@link RendererRegistry} and
 * renders it. Built-in default rendering only covers the renderer ids this
 * package ships (`html`, `svg`, `markdown` — always through the sandboxed
 * iframe for `html`/`svg`, since arbitrary SVG can carry `<script>`/event
 * handlers just like HTML). Every other renderer id (`deck-html`,
 * `react-component`, `mini-app`, `design-system`, `code`, `diagram`, or any
 * host-registered custom id) requires the host to supply a `slots.renderers`
 * entry; without one, a fallback message is shown instead of guessing at
 * how to render host-specific content.
 */
import type { ReactNode } from 'react';
import { useMemo } from 'react';
import { RendererRegistry, type ArtifactRenderMatch } from '../../registry.js';
import type { ArtifactFile } from '../../types.js';
import type { BuildSrcDocOptions } from '../../srcdoc/build.js';
import { renderMarkdownToSafeHtml } from '../../renderers/markdown.js';
import { useT } from '../i18n.js';
import { SrcDocSandbox } from './SrcDocSandbox.js';
import { AnnotationCanvas, type AnnotationCanvasProps } from '../../annotation-canvas/index.js';

export interface ArtifactViewSlotProps {
  file: ArtifactFile;
  match: ArtifactRenderMatch;
}

export type ArtifactViewSlot = (props: ArtifactViewSlotProps) => ReactNode;

export interface ArtifactViewSlots {
  /** Keyed by `ArtifactRenderer.id`. Takes priority over this component's own built-in rendering when present, including for `html`/`svg`/`markdown`. */
  renderers?: Partial<Record<string, ArtifactViewSlot>> | undefined;
}

export interface ArtifactViewProps {
  file: ArtifactFile;
  registry: RendererRegistry;
  /** Passed through to `registry.resolve({ file }, { hints })`. */
  hints?: Record<string, unknown> | undefined;
  /** Passed through to `SrcDocSandbox` for the built-in `html`/`svg` rendering. */
  srcDocOptions?: BuildSrcDocOptions | undefined;
  slots?: ArtifactViewSlots | undefined;
  className?: string | undefined;
  /**
   * Wraps whatever this artifact resolves to render (a built-in renderer, a
   * host slot, or the fallback message) in an `<AnnotationCanvas>` overlay —
   * this is the annotation-canvas feature's actual integration point with
   * the renderer-registry pipeline, rather than a standalone component a
   * caller bolts on separately. Omit entirely to render without any
   * annotation overlay.
   */
  annotation?: Omit<AnnotationCanvasProps, 'children'> | undefined;
}

export function ArtifactView({ file, registry, hints, srcDocOptions, slots, className, annotation }: ArtifactViewProps) {
  const t = useT();
  const match = useMemo(() => registry.resolve({ file }, { hints }), [registry, file, hints]);

  const wrap = (node: ReactNode): ReactNode => (annotation ? <AnnotationCanvas {...annotation}>{node}</AnnotationCanvas> : node);

  if (!match) {
    return wrap(
      <div className={className} role="status">
        {t('No renderer is registered for this artifact.')}
      </div>,
    );
  }

  const slotRenderer = slots?.renderers?.[match.renderer.id];
  if (slotRenderer) return wrap(<>{slotRenderer({ file, match })}</>);

  return wrap(renderBuiltIn({ file, match, t }, { className, srcDocOptions }));
}

type Translate = ReturnType<typeof useT>;

/** Built-in rendering for the renderer ids this package ships; any other id gets the "supply a slot" fallback message. */
function renderBuiltIn(
  { file, match, t }: { file: ArtifactFile; match: ArtifactRenderMatch; t: Translate },
  { className, srcDocOptions }: { className?: string | undefined; srcDocOptions?: BuildSrcDocOptions | undefined },
): ReactNode {
  const content = file.content ?? '';
  switch (match.renderer.id) {
    case 'html':
    case 'svg':
      return <SrcDocSandbox className={className} html={content} options={srcDocOptions} title={match.manifest.title} />;
    case 'markdown': {
      const html = match.renderer.renderPartial ? match.renderer.renderPartial(content) : renderMarkdownToSafeHtml(content);
      // eslint-disable-next-line react/no-danger -- html is produced by renderMarkdownToSafeHtml, which escapes/allow-lists links; see markdown.ts.
      return <div className={className} dangerouslySetInnerHTML={{ __html: html }} />;
    }
    default:
      return (
        <div className={className} role="status">
          {t('No renderer registered for "{rendererId}" — supply one via slots.renderers.', {
            rendererId: match.renderer.id,
          })}
        </div>
      );
  }
}

import { useCallback, useEffect, useRef, type RefObject } from 'react';
import type { SandboxBridgeHandler, SandboxBridgeMessage } from './types.js';

export interface UseSandboxBridgeOptions {
  /** Ref to the sandboxed iframe this bridge talks to. */
  iframeRef: RefObject<HTMLIFrameElement | null>;
  /**
   * Handlers keyed by `message.type`. A message whose `type` has no
   * registered handler is ignored. Re-registering with a new object every
   * render is fine — the latest handlers are always used without
   * re-attaching the underlying `message` listener (see the effect-deps
   * note below).
   */
  handlers: Record<string, SandboxBridgeHandler>;
  /**
   * Restrict outbound `postMessage` (and — since a same-document sandboxed
   * `srcDoc` iframe has an opaque `"null"` origin that can't be checked
   * positionally — inbound acceptance) to a specific origin. Omit to post
   * with `'*'`; inbound messages are still scoped by verifying
   * `event.source` is this exact iframe's `contentWindow`, not by origin.
   */
  targetOrigin?: string;
}

export interface SandboxBridge {
  /** Post a message to the sandboxed iframe's `contentWindow`. No-op if the iframe isn't mounted yet. */
  post(message: SandboxBridgeMessage): void;
}

/**
 * Wire a `window` `message` listener scoped to one sandboxed iframe: every
 * inbound message is checked against `event.source === iframe.contentWindow`
 * before being dispatched (by `message.type`) to a registered handler, and
 * `post()` sends a message to that same iframe. This is deliberately just
 * the transport — it carries no message *vocabulary* of its own. A
 * consuming feature (deck navigation, comment pinning, an inspector panel,
 * …) defines its own message shapes and registers handlers for them.
 *
 * The listener is attached once per mount, not re-attached whenever
 * `handlers` changes identity (a fresh object literal every render is the
 * common case) — the latest `handlers`/`targetOrigin` are read through a
 * ref on every incoming message instead, avoiding the churn (and, if a
 * caller's handler closes over `useT()`'s `t`, the infinite-render-loop
 * gotcha) of listing them as effect dependencies.
 */
export function useSandboxBridge(options: UseSandboxBridgeOptions): SandboxBridge {
  const { iframeRef } = options;
  const optionsRef = useRef(options);
  optionsRef.current = options;

  useEffect(() => {
    function onMessage(event: MessageEvent) {
      const iframe = iframeRef.current;
      if (!iframe || event.source !== iframe.contentWindow) return;
      const data = event.data as SandboxBridgeMessage | null | undefined;
      if (!data || typeof data.type !== 'string') return;
      const handler = optionsRef.current.handlers[data.type];
      handler?.(data);
    }
    window.addEventListener('message', onMessage);
    return () => window.removeEventListener('message', onMessage);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [iframeRef]);

  const post = useCallback(
    (message: SandboxBridgeMessage) => {
      const iframe = iframeRef.current;
      const contentWindow = iframe?.contentWindow;
      if (!contentWindow) return;
      contentWindow.postMessage(message, optionsRef.current.targetOrigin ?? '*');
    },
    [iframeRef],
  );

  return { post };
}

/**
 * Wrap artifact HTML for a sandboxed iframe (`srcDoc`).
 *
 * Origin: `apps/web/src/runtime/srcdoc.ts` in the origin project (2,689
 * lines). Ported the generic sandbox mechanics only — document wrapping,
 * title sanitization, the same-origin storage shim, the anti-focus-steal
 * guard, and the lazy-transport-shell perf optimization. NOT ported: every
 * postMessage bridge (deck navigation, comment/inspect element-selection,
 * CSS tweaks palette, manual-edit overlay, snapshot/export-capture) — those
 * are that product's own UI protocols. They become `SrcDocBridge` plugins a
 * host registers via `bridges` (see `bridge.ts`), not built-ins. See
 * `archived provenance ledger` for the full file-by-file breakdown.
 */
import { defaultTreeAdapter, parse, type DefaultTreeAdapterMap } from 'parse5';
import { escapeHtmlAttribute } from '../html-utils.js';
import { wrapFragmentAsDocument } from '../sandboxed-document.js';
import { buildFocusScript, buildStorageScript } from '../sandbox-scripts.js';
import { applySrcDocBridges, type SrcDocBridge, type SrcDocBridgeContext } from './bridge.js';

export interface BuildSrcDocOptions {
  /** `<base href>` for the document, so relative asset/script URLs resolve as if served from this path. */
  baseHref?: string | undefined;
  /**
   * Suppress focus-stealing scripts (`window.focus()`, `element.focus()` at
   * load, `autofocus`) unless the user just interacted with the iframe.
   * Callers decide when this is needed — see `htmlNeedsFocusGuard` in
   * `url-load-decision.ts` for the auto-detection heuristic used upstream.
   */
  previewFocusGuard?: boolean | undefined;
  /** Host-registered bridges to splice in, run in array order after the mandatory sandbox shim + focus guard. */
  bridges?: readonly SrcDocBridge[] | undefined;
  /** Extra context passed through to every bridge's `inject`. */
  bridgeContext?: Record<string, unknown> | undefined;
  /**
   * Wrap the result as a small "lazy transport" shell instead of the real
   * document (see {@link buildLazySrcDocTransport}) — the host activates it
   * later via a `postMessage`, avoiding a second full srcDoc reflow when the
   * same iframe is reused across renders.
   */
  lazyTransport?: boolean | undefined;
  /**
   * Content-Security-Policy meta tag to inject into the document `<head>`.
   * `true` (default) injects {@link DEFAULT_SRC_DOC_CSP}; `false` skips CSP
   * injection entirely (the iframe's `sandbox` attribute is still the
   * primary isolation boundary — see `react/components/SrcDocSandbox.tsx`);
   * a string uses that policy verbatim.
   */
  csp?: string | boolean | undefined;
}

/**
 * Default Content-Security-Policy applied to every srcDoc document unless
 * overridden. Locks down `object-src`/`base-uri`/`form-action` (no plugin
 * embeds, no `<base>`-hijacking, no form navigation out of the sandbox)
 * while still allowing the inline scripts/styles and `blob:`/`data:` assets
 * that typical agent-generated HTML/React/SVG artifacts use. This is
 * defense in depth on top of the iframe's own `sandbox` attribute (which
 * lacks `allow-same-origin`, so the document already has no access to the
 * host's storage/cookies/DOM regardless of CSP).
 */
export const DEFAULT_SRC_DOC_CSP =
  "default-src 'none'; script-src 'unsafe-inline' 'unsafe-eval' blob: data:; style-src 'unsafe-inline'; img-src * data: blob:; font-src * data:; media-src * data: blob:; connect-src *; frame-src *; child-src *; object-src 'none'; base-uri 'none'; form-action 'none';";

/** Resolve the existing default/disabled/custom policy contract without changing caller options.
 * An empty custom string injects no policy, just like `false`.
 */
function resolveContentSecurityPolicy({ csp }: Pick<BuildSrcDocOptions, 'csp'>): string | null {
  if (csp === false) return null;
  return csp === true || csp === undefined ? DEFAULT_SRC_DOC_CSP : csp;
}

/** The safety tags spliced once at the parsed head opener. Order is load-bearing: the host's
 * own scripts precede the policy, the host `<base>` precedes it so the default `base-uri 'none'`
 * cannot block it, and authored markup follows it. Separate regex splices could match `<head`
 * inside a quoted attribute, and the next tag's quotes then pushed the policy into `<body>`. */
function buildSafetyHead(options: BuildSrcDocOptions): string {
  const csp = resolveContentSecurityPolicy(options);
  return (options.previewFocusGuard ? buildFocusScript({ format: 'srcdoc' }) : '')
    + buildStorageScript({ format: 'srcdoc' })
    + (options.baseHref ? `<base href="${escapeHtmlAttribute(options.baseHref)}">` : '')
    + (csp ? `<meta http-equiv="Content-Security-Policy" content="${escapeHtmlAttribute(csp)}">` : '');
}

/**
 * Sanitize a title string so it is safe to use as a downloaded/printed
 * filename (avoids characters several common desktop OSes and collaboration
 * tools reject in filenames: `: # % & * { } \ < > ? / + | "`), and strips
 * doubled `~$` lock-file prefixes some office tools leave behind.
 */
export function sanitizePreviewTitle(text: string): string {
  let result = text.trim();
  let prev: string;
  do {
    prev = result;
    result = result.replace(/^~\$/, '').trim();
  } while (result !== prev);
  // eslint-disable-next-line no-useless-escape
  result = result.replace(/[:#%&*{}\\<>?/+|"]+/g, '-');
  return result.trim();
}

/** Finds a direct element child; template contents must not supply the document title. */
function findElementChild({ parent, tagName }: {
  parent: DefaultTreeAdapterMap['parentNode'] | undefined;
  tagName: string;
}): DefaultTreeAdapterMap['element'] | undefined {
  return parent?.childNodes.find(
    (node): node is DefaultTreeAdapterMap['element'] => defaultTreeAdapter.isElementNode(node) && node.tagName === tagName,
  );
}

/**
 * Rewrite the `<title>` element in an HTML string so its text content is
 * filename-safe (see {@link sanitizePreviewTitle}). Only the real `<title>`
 * in the parsed `<head>` is changed — comments, scripts, styles, templates,
 * and body titles cannot supply it. parse5 owns HTML recovery and single-pass
 * entity decoding, identically in Node and the browser. Source offsets let us
 * splice only title content; serializing the document would change unrelated
 * formatting. A title without an explicit closing tag is left untouched.
 *
 * @param html Original document source; never mutated or re-serialized.
 * @returns Source with the first head title's decoded, filename-safe text.
 * @complexity O(n) time and space in source length for parsing and splicing.
 * @example sanitizeTitleInDoc('<title>Q3: Report</title>') // '<title>Q3- Report</title>'
 */
export function sanitizeTitleInDoc(html: string): string {
  const document = parse(html, { sourceCodeLocationInfo: true });
  const root = findElementChild({ parent: document, tagName: 'html' });
  const head = findElementChild({ parent: root, tagName: 'head' });
  const title = findElementChild({ parent: head, tagName: 'title' });
  const location = title?.sourceCodeLocation;
  if (!title || !location?.startTag || !location.endTag) return html;

  const decoded = title.childNodes.filter(defaultTreeAdapter.isTextNode).map((node) => node.value).join('');
  const safe = sanitizePreviewTitle(decoded);
  return html.slice(0, location.startTag.endOffset) + safe + html.slice(location.endTag.startOffset);
}

function serializeHtmlDocument(doc: Document): string {
  const doctype = doc.doctype ? '<!doctype html>\n' : '';
  return `${doctype}${doc.documentElement.outerHTML}`;
}

/** An implicit element has no authored opening tag to splice after. */
function openingTagEnd({ node }: { node: DefaultTreeAdapterMap['element'] | undefined }): number | undefined {
  return node?.sourceCodeLocation?.startTag?.endOffset;
}

/** Splice after the parsed head opener, or before content in an implicit head.
 * Source offsets exclude comments, raw text and quoted attributes without rewriting the document.
 * @complexity O(n) time and space for parsing n source characters.
 */
export function injectAfterHeadOpen(doc: string, payload: string): string {
  const document = parse(doc, { sourceCodeLocationInfo: true });
  const root = findElementChild({ parent: document, tagName: 'html' });
  const head = findElementChild({ parent: root, tagName: 'head' });
  const doctype = document.childNodes.find(defaultTreeAdapter.isDocumentTypeNode);
  const offset = openingTagEnd({ node: head })
    ?? openingTagEnd({ node: root })
    ?? doctype?.sourceCodeLocation?.endOffset ?? 0;
  return doc.slice(0, offset) + payload + doc.slice(offset);
}

/**
 * Splice `payload` right before the real `</head>` (the last one before
 * `<body>`, so a literal `</head>` inside a `<script>`/`<style>` isn't
 * mistaken for the real close tag). String-first for speed; falls back to
 * `DOMParser` only for head-less fragments where no textual insertion point
 * exists.
 */
export function injectBeforeHeadEnd(doc: string, payload: string): string {
  const lower = doc.toLowerCase();
  const bodyStart = lower.indexOf('<body');
  const limit = bodyStart >= 0 ? bodyStart : lower.length;
  const idx = lower.lastIndexOf('</head>', limit - 1);
  if (idx >= 0) return doc.slice(0, idx) + payload + doc.slice(idx);
  if (/<head[^>]*>/i.test(doc)) return injectAfterHeadOpen(doc, payload);
  return injectViaDomParser({ doc, payload, section: 'head' }) ?? payload + doc;
}

/** Splice `payload` right before the real `</body>` (the last one before `</html>`). See {@link injectBeforeHeadEnd}. */
export function injectBeforeBodyEnd(doc: string, payload: string): string {
  const lower = doc.toLowerCase();
  const htmlEnd = lower.lastIndexOf('</html>');
  const limit = htmlEnd >= 0 ? htmlEnd : lower.length;
  const idx = lower.lastIndexOf('</body>', limit - 1);
  if (idx >= 0) return doc.slice(0, idx) + payload + doc.slice(idx);
  return injectViaDomParser({ doc, payload, section: 'body' }) ?? doc + payload;
}

/**
 * DOMParser fallback shared by the head/body splicers for fragments with no
 * textual insertion point. Returns `null` when `DOMParser` is unavailable or
 * throws, so the caller falls through to its own prepend/append.
 */
function injectViaDomParser(
  { doc, payload, section }: { doc: string; payload: string; section: 'head' | 'body' },
  _options: Record<string, never> = {},
): string | null {
  if (typeof DOMParser === 'undefined') return null;
  try {
    const parsed = new DOMParser().parseFromString(doc, 'text/html');
    parsed[section]?.insertAdjacentHTML('beforeend', payload);
    return serializeHtmlDocument(parsed);
  } catch {
    /* fall through to the caller's prepend/append */
    return null;
  }
}

function injectSrcdocTransportActivationBridge(doc: string): string {
  const script = `<script data-jini-srcdoc-transport-activation>(function(){
  window.addEventListener('message', function(ev){
    // Only the embedding host may replace this document; nested frames are untrusted.
    if (ev.source !== window.parent) return;
    var data = ev && ev.data;
    if (!data || data.type !== 'jini:srcdoc-transport-activate' || typeof data.html !== 'string') return;
    document.open();
    document.write(data.html);
    document.close();
  });
})();</script>`;
  return injectBeforeBodyEnd(doc, script);
}

/**
 * Build the lazy transport shell: a tiny placeholder document that, once
 * mounted, listens for a `jini:srcdoc-transport-activate` postMessage
 * carrying the real artifact HTML and replaces itself via
 * `document.write`. Lets a host reuse one already-mounted iframe across
 * renders instead of paying a full `srcDoc` reflow every time, at the cost
 * of one extra postMessage round trip on first activation.
 *
 * The shell posts `jini:srcdoc-transport-ready` to the parent as soon as
 * its listener is installed — the *only* reliable signal a host has that
 * the listener is live. Without it, a host that posts `activate` too early
 * (e.g. immediately after a key-driven iframe re-mount) risks the message
 * being dropped before the shell's script has executed, leaving the iframe
 * stuck on the empty shell.
 */
export function buildLazySrcDocTransport(): string {
  return `<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <script data-jini-lazy-srcdoc-transport>(function(){
      window.addEventListener('message', function(ev){
        // Only the embedding host may replace this document; nested frames are untrusted.
        if (ev.source !== window.parent) return;
        var data = ev && ev.data;
        if (!data || data.type !== 'jini:srcdoc-transport-activate' || typeof data.html !== 'string') return;
        document.open();
        document.write(data.html);
        document.close();
      });
      try {
        if (window.parent && window.parent !== window) {
          window.parent.postMessage({ type: 'jini:srcdoc-transport-ready' }, '*');
        }
      } catch (_) { /* sandboxed parent — host falls back to onLoad */ }
    })();</script>
  </head>
  <body></body>
</html>`;
}

export interface SrcDocActivationInputs {
  /** The real artifact HTML the host wants to inject into the shell. */
  srcDoc: string;
  /** Host is currently showing a URL-loaded iframe (the srcDoc iframe is hidden). */
  useUrlLoadPreview: boolean;
  /** Host's render pipeline is routing through the lazy transport shell. */
  useLazyTransport: boolean;
  /** The shell document has loaded AND posted `jini:srcdoc-transport-ready`. */
  shellReady: boolean;
  /** Which artifact HTML has already been pushed into this shell (dedupe). */
  activatedHtml: string | null;
}

/**
 * Pure decision for whether a host should now post
 * `jini:srcdoc-transport-activate` to the shell iframe. Gating on
 * `shellReady` matters: without it, an activation triggered by
 * `useUrlLoadPreview` flipping to false can fire before the iframe's shell
 * script has registered its message listener — the message is dropped, the
 * shell stays on its empty body, and a naive dedupe check then suppresses
 * the follow-up activation from the iframe's own `onLoad` path.
 */
export function canActivateSrcDocTransport(state: SrcDocActivationInputs): boolean {
  if (!state.srcDoc) return false;
  if (state.useUrlLoadPreview) return false;
  if (!state.useLazyTransport) return false;
  if (!state.shellReady) return false;
  if (state.activatedHtml === state.srcDoc) return false;
  return true;
}

/**
 * Wrap `html` for a sandboxed iframe's `srcDoc`. If `html` is already a full
 * document (`<!doctype …>` / `<html>`), it's passed through unchanged;
 * otherwise it's wrapped in a minimal doctype shell. Always applies the
 * safety mechanics (title sanitization, sandbox shim, focus guard); runs any
 * `options.bridges` afterward via {@link applySrcDocBridges}.
 */
export function buildSrcDoc(html: string, options: BuildSrcDocOptions = {}): string {
  if (options.lazyTransport) return buildLazySrcDocTransport();

  const wrapped = wrapFragmentAsDocument(html);

  const withSafety = injectAfterHeadOpen(sanitizeTitleInDoc(wrapped), buildSafetyHead(options));

  const ctx: SrcDocBridgeContext = { baseHref: options.baseHref, ...options.bridgeContext };
  const withBridges = options.bridges?.length
    ? applySrcDocBridges(withSafety, options.bridges, ctx)
    : withSafety;

  return injectSrcdocTransportActivationBridge(withBridges);
}
